const DATA = {"source":"https://smarttani.sabah.gov.my/ALUS/Pest/","crops":[{"code":"BUAH","name":{"ms":"Avokado","en":"Avocado","zh":"牛油果"},"pests":[132,128,183,126,129,127,131],"img":"Screenshot_2024-01-16_103032.jpg"},{"code":"DURIAN","name":{"ms":"Durian","en":"Durian","zh":"榴莲"},"pests":[118,120,117,112,25,22,27,20,16,26],"img":"koya_durian_DOA_Sabah.jpg"},{"code":"COCONUT","name":{"ms":"Kelapa","en":"Coconut","zh":"椰子"},"pests":[290,310,110,109,283],"img":"Source__Stephanie_Sokol_Nov_9_2023_8.jpg"},{"code":"KOPI","name":{"ms":"Kopi","en":"Coffee","zh":"咖啡"},"pests":[92,90,134],"img":"Fungus_DOA_Sabah.jpg"},{"code":"PINEAPPLE","name":{"ms":"Nanas","en":"Pineapple","zh":"黄梨（菠萝）"},"pests":[173,309],"img":"Koya_nanas_Doa_sabah.jpg"},{"code":"JACKFRUIT","name":{"ms":"Nangka","en":"Jackfruit","zh":"菠萝蜜"},"pests":[286,288,47],"img":"Source__Stephanie_Sokol_Nov_9_2023_1.jpg"},{"code":"PADDY","name":{"ms":"Padi","en":"Paddy","zh":"稻米"},"pests":[122,124,42,43,38,105,125,97,44,41,45,104],"img":"Penyakit_PMV_DOA_Sabah.jpg"},{"code":"BANANA","name":{"ms":"Pisang","en":"Banana","zh":"香蕉"},"pests":[100,1,2,3,4,102],"img":"Penyakit_Pisang_Bintik_Daun_Cordana_New_PnG.jpg"},{"code":"MAIZE","name":{"ms":"Jagung","en":"Maize","zh":"玉米"},"pests":[29],"extra":true,"img":"Untitled-5.jpg"},{"code":"CITRUS","name":{"ms":"Sitrus","en":"Citrus","zh":"柑橘"},"pests":[71],"extra":true,"img":"buahcgggg.jpg"},{"code":"PAPAYA","name":{"ms":"Betik","en":"Papaya","zh":"木瓜"},"pests":[79,157],"extra":true,"img":"buahdiebacknew.jpg"},{"code":"MANGO","name":{"ms":"Mangga","en":"Mango","zh":"芒果"},"pests":[106],"extra":true,"img":"Deporaus_marginatus.jpg"},{"code":"CABBAGE","name":{"ms":"Kobis","en":"Cabbage","zh":"包菜"},"pests":[156],"extra":true,"img":"kobis.jpg"},{"code":"GINGER","name":{"ms":"Halia","en":"Ginger","zh":"姜"},"pests":[159,171,182],"extra":true,"img":"Untitled_design.jpg"}],"parts":{"STEM":{"ms":"Batang","en":"Stem","zh":"茎/树干"},"LEAF":{"ms":"Daun","en":"Leaf","zh":"叶子"},"PLANT":{"ms":"Pokok","en":"Plant","zh":"整株"},"ROOT":{"ms":"Akar","en":"Root","zh":"根部"},"FR":{"ms":"Buah","en":"Fruit","zh":"果实"},"PEST":{"ms":"Perosak","en":"Pest","zh":"虫体（害虫本身）"},"TREE":{"ms":"Pokok","en":"Tree","zh":"树"},"MORFOLOGI":{"ms":"Morfologi","en":"Morphology","zh":"形态特征"},"BEAN":{"ms":"Biji Kopi","en":"Coffee Bean","zh":"咖啡豆"},"F":{"ms":"Pelepah","en":"Frond","zh":"椰叶"},"LC":{"ms":"Kitaran Hidup","en":"Life Cycle","zh":"生活史"}},"pests":[{"id":1,"crops":["BANANA"],"name":{"ms":"Layu Bakteria","en":"Bacterial Wilt","zh":"香蕉青枯病"},"desc":{"ms":"<em>Ralstonia solanacearum</em> spesis kompleks adalah bakteria bawaan tanah, aerob tanpa spora dan gram-negatif yang menyebabkan penyakit tanaman. Bakteria ini menjangkiti zailem menyebabkan penyakit layu pada tanaman pisang. Tanaman yang dijangkiti harus dihapuskan dengan segera. Belum ada kaedah yang berkesan untuk mengawal penyakit ini. Oleh itu untuk penanaman di kawasan baharu gunakan bahan tanaman yang bebas penyakit.","en":"<em>Ralstonia solanacearum</em> species complex is a soil-borne, aerobic, non-spore-forming, gram-negative bacterium that causes plant disease. The bacterium infects the xylem and causes wilt disease in banana plants. Infected plants must be destroyed immediately. There is no effective method yet to control this disease. Therefore, when planting in a new area, use disease-free planting material.","zh":"<em>Ralstonia solanacearum</em> 复合种（青枯雷尔氏菌）是一种土传、好氧、不产孢子的革兰氏阴性植物病原细菌。这种细菌侵染木质部，使香蕉植株发生萎蔫病。受感染的植株必须立即销毁。目前尚无有效的方法防治此病。因此，在新地区种植时，请使用无病的种植材料。"},"symptoms":[{"part":"STEM","img":"THUMBNAIL_9.jpg","text":{"ms":"Batang menunjukkan perubahan warna pada tisu vaskular. Bahagian batang yang di potong jika direndam dalam air jernih dalam bekas lutsinar atau kaca menunjukkan juraian ooz bakteria.","en":"The stem shows discolouration of the vascular tissue. When a cut piece of the stem is soaked in clear water in a transparent or glass container, streams of bacterial ooze can be seen.","zh":"茎干的维管组织变色。把切下的茎段浸泡在透明或玻璃容器的清水中，可看到细菌菌脓呈丝状流出。"},"steps":[{"img":"THUMBNAIL_8.jpg","text":{"ms":"Potong batang pisang atau tangkai buah dan lihat perubahan warna pada tisu vaskular (bahagian tengah atau batang sebenar). Bahagian yang dipotong ini jika direndam dalam air jernih dalam bekas yang lutsinar akan keluar juraian ooz bakteria. Ooz bakteria ini boleh juga dalam keadaan tidak berwarna. Pada pisang yang dijangkiti dengan teruk, ooz bakteria ini boleh kelihatan pada potongan batang yang terdedah.","en":"Cut the banana stem or the fruit stalk and look for discolouration in the vascular tissue (the centre or true stem). If the cut piece is soaked in clear water in a transparent container, streams of bacterial ooze will come out. The bacterial ooze can also be colourless. In badly infected banana plants, the bacterial ooze can be seen on the exposed cut surface of the stem.","zh":"切开香蕉茎干或果柄，观察维管组织（中心部分或真茎）是否变色。把切下的部分浸泡在透明容器的清水中，会有细菌菌脓呈丝状流出。菌脓也可能是无色的。在严重受感染的香蕉植株上，茎干切面上就能直接看到菌脓。"}},{"img":"THUMBNAIL_10_qEPiMfP.jpg","text":{"ms":"Ooz bakteria kelihatan apabila bahagian batang atau umbut di rendam dalam air jernih dalam bekas yang jernih. Ooz bakteria ini berwarna keputihan kadang-kadang tidak berwarna.","en":"Bacterial ooze can be seen when a piece of the stem or the heart (pith) is soaked in clear water in a clear container. The bacterial ooze is whitish, sometimes colourless.","zh":"把茎段或蕉心浸泡在透明容器的清水中，可看到细菌菌脓。菌脓呈白色，有时无色。"}}]},{"part":"LEAF","img":"THUMBNAIL_6.jpg","text":{"ms":"Daun muda menguning dan layu.","en":"Young leaves turn yellow and wilt.","zh":"嫩叶变黄并萎蔫。"},"steps":[{"img":"THUMBNAIL_6_6TOxXn7.jpg","text":{"ms":"Daun muda menguning dan layu.","en":"Young leaves turn yellow and wilt.","zh":"嫩叶变黄并萎蔫。"}}]},{"part":"PLANT","img":"pokok_pisang_layu_bakteria_YKoZ989.jpg","text":{"ms":"Pokok pisang yang dijangkiti penyakit bakteria mempunyai simtom kekuningan dan layu dengan buah dan isi buah yang berubah warna.","en":"Banana plants infected with the bacterial disease show yellowing and wilting, and the fruit and fruit flesh become discoloured.","zh":"感染细菌病害的香蕉植株出现叶片发黄和萎蔫，果实和果肉也会变色。"},"steps":[{"img":"THUMBNAIL_6.jpg","text":{"ms":"Pokok yang dijangkiti menunjukkan daun muda yang kuning dan layu.","en":"Infected plants show young leaves that are yellow and wilted.","zh":"受感染的植株嫩叶发黄、萎蔫。"}},{"img":"THUMBNAIL_10.jpg","text":{"ms":"Pokok yang dijangkiti akan mengeluarkan ooz bakteria yang boleh diperiksa dengan merendam umbut pisang dalam air dan bekas yang jernih.","en":"Infected plants produce bacterial ooze, which can be checked by soaking a piece of the banana heart (pith) in clear water in a clear container.","zh":"受感染的植株会产生细菌菌脓，可将一段蕉心浸泡在透明容器的清水中进行检查。"}}]}],"sci":"<em>Ralstonia solanacearum</em> species complex","kind":"bacteria","ai":[]},{"id":2,"crops":["BANANA"],"name":{"ms":"Layu Fusarium","en":"Fusarium Wilt (Panama Disease)","zh":"香蕉枯萎病（巴拿马病）"},"desc":{"ms":"<em>Fusarium oxysporum</em> biasa didapati dalam tanah dan mengeluarkan tiga jenis spora aseksual; makrokonidia, mikrokonidia dan klamidospora. Makrokonidia dan klamidospora biasa berlaku pada perumah / tanaman yang telah atau sedang mati. Klamidospora adalah struktur yang paling signifikan dalam kelangsungan hidup patogen ini. <em>Fusarium oxysporum</em> f. sp. cubense (Foc) menyebabkan penyakit Layu Fusarium atau Penyakit Panama pada tanaman pisang. Patogen ini boleh disebarkan melalui pokok induk dan sulur yang dijangkiti. Oleh itu mana-mana bahan tanaman termasuk sulur yang tidak menunjukkan simtom berpotensi sebagai sumber inokulum. Belum ada kaedah yang berkesan untuk mengawal penyakit ini. Tanaman yang dijangkiti haruslah dimusnahkan dan gunakan bahan tanaman bebas penyakit apabila menanam di kawasan yang baru.","en":"<em>Fusarium oxysporum</em> is commonly found in soil and produces three types of asexual spores: macroconidia, microconidia and chlamydospores. Macroconidia and chlamydospores usually form on host plants that are dead or dying. Chlamydospores are the most important structures for the survival of this pathogen. <em>Fusarium oxysporum</em> f. sp. <em>cubense</em> (Foc) causes Fusarium Wilt, also called Panama Disease, in banana. The pathogen can be spread through infected mother plants and suckers. Therefore, any planting material, including suckers that show no symptoms, can be a source of infection. There is no effective method yet to control this disease. Infected plants must be destroyed, and disease-free planting material should be used when planting in a new area.","zh":"<em>Fusarium oxysporum</em>（尖孢镰刀菌）常见于土壤中，会产生三种无性孢子：大型分生孢子、小型分生孢子和厚垣孢子。大型分生孢子和厚垣孢子通常在已经死亡或正在死亡的寄主植物上形成。厚垣孢子是这种病原菌赖以存活的最重要结构。<em>Fusarium oxysporum</em> f. sp. <em>cubense</em>（Foc）会引起香蕉的镰刀菌枯萎病，也叫巴拿马病。病原菌可通过受感染的母株和吸芽传播。因此，任何种植材料，包括没有显示症状的吸芽，都可能成为传染源。目前还没有有效的方法防治这种病害。受感染的植株必须销毁，在新地区种植时应使用无病种苗。"},"symptoms":[{"part":"ROOT","img":"THUMBNAIL_13_loCSQpI.jpg","text":{"ms":"Hujung akar rambut adalah tempat bermulanya jangkitan dan merebak ke umbisi. Tanda jangkitan adalah kesan hitam pada tisu dalaman akar berkenaan. Kehadiran nematoda parasitik ini dikaitkan dengan jangkitan yang tinggi penyakit Layu Fusarium atau Panama.","en":"Infection starts at the tips of the fine feeder roots and spreads to the rhizome (corm). A sign of infection is a black stain on the inner tissue of the affected roots. The presence of parasitic nematodes is linked to high levels of Fusarium Wilt (Panama Disease) infection.","zh":"感染从细小须根的根尖开始，然后扩散到球茎（根状茎）。感染的迹象是受害根部内部组织出现黑色斑痕。寄生性线虫的存在与镰刀菌枯萎病（巴拿马病）的高感染率有关。"},"steps":[{"img":"THUMBNAIL_13_Hd6lNFs.jpg","text":{"ms":"Hujung akar rambut adalah tempat bermulanya jangkitan dan merebak ke umbisi. Tanda jangkitan adalah kesan hitam pada tisu dalaman akar berkenaan. Penularan jangkitan menyebabkan bahagian zailem berwarna merah-keperangan. Penyakit Layu Fusarium atau Panama ini adalah berkait rapat dengan infestasi nematoda parasit pada akar.","en":"Infection starts at the tips of the fine feeder roots and spreads to the rhizome (corm). A sign of infection is a black stain on the inner tissue of the affected roots. As the infection spreads, the xylem (water-conducting tissue) turns reddish-brown. Fusarium Wilt (Panama Disease) is closely linked to infestation of the roots by parasitic nematodes.","zh":"感染从细小须根的根尖开始，然后扩散到球茎（根状茎）。感染的迹象是受害根部内部组织出现黑色斑痕。随着感染扩散，木质部（输水组织）会变成红褐色。镰刀菌枯萎病（巴拿马病）与根部受寄生性线虫侵害密切相关。"}}]},{"part":"PLANT","img":"THUMBNAIL_1.jpg","text":{"ms":"Jangkitan Fusarium oxysporum bermula daripada hujung akar rambut kemudian ke raizom. Jangkitan kelihatan sebagai bintik hitam pada tisu akar dimana stele bersambung dengan korteks. Perkembangan jangkitan menyebabkan bahagian zailem menjadi perang kemerahan. Daun yang tua akan menjadi kuning dan layu sehingga merebak ke daun muda. Daun-daun yang layu akan patah dan terkulai pada batang pisang.","en":"<em>Fusarium oxysporum</em> infection starts at the tips of the fine feeder roots and then moves to the rhizome. The infection appears as black spots in the root tissue where the stele joins the cortex. As the infection develops, the xylem turns reddish-brown. The old leaves turn yellow and wilt, and this spreads to the young leaves. The wilted leaves break and hang down along the banana pseudostem.","zh":"<em>Fusarium oxysporum</em>的感染从细小须根的根尖开始，然后扩散到根状茎。在根部组织中维管柱与皮层相接的地方会出现黑色斑点。随着感染发展，木质部会变成红褐色。老叶先变黄并枯萎，然后扩散到嫩叶。枯萎的叶片会折断，沿着香蕉假茎下垂。"},"steps":[{"img":"THUMBNAIL_2.jpg","text":{"ms":"Daun tua menguning dan layu. Daun-daun yang layu patah dan jatuh terkulai pada batang pisang.","en":"Old leaves turn yellow and wilt. The wilted leaves break and hang down along the banana pseudostem.","zh":"老叶变黄并枯萎。枯萎的叶片折断，沿着香蕉假茎下垂。"}}]},{"part":"STEM","img":"THUMBNAIL_3.jpg","text":{"ms":"Jangkitan Fusarium oxysporum mencetuskan mekanisma pertahanan pada pokok perumah menyebabkan pengeluaran lendir. Ini diikuti dengan pembentukan 'tylose' dalam berkas pembuluh yang menyebabkan pergerakkan air dan nutrient ke bahagian atas tanaman tersekat. Keratan rentas batang akan menunjukkan warna perang-kemerahan.","en":"<em>Fusarium oxysporum</em> infection triggers the plant's defence mechanism, causing it to produce a gel. This is followed by the formation of tyloses in the vascular bundles, which block the movement of water and nutrients to the upper parts of the plant. A cross-section of the pseudostem shows a reddish-brown colour.","zh":"<em>Fusarium oxysporum</em>的感染会触发寄主植物的防御机制，使其分泌胶状物。随后维管束内形成侵填体（tylose），阻断水分和养分向植株上部输送。切开假茎的横截面可见红褐色变色。"},"steps":[{"img":"THUMBNAIL_3_Rzpu0r8.jpg","text":{"ms":"Jangkitan Fusarium oxysporum mencetuskan mekanisma pertahanan oleh tanaman yang menyebabkan pengeluaran lendir. Ini diikuti dengan pembentukan \"tylose\" dalam berkas pembuluh yang menyebabkan pergerakkan air dan nutrien ke bahagian atas tanaman tersekat. Keratan rentas batang pokok yang dijangkiti berwarna perang-kemerahan.","en":"<em>Fusarium oxysporum</em> infection triggers the plant's defence mechanism, causing it to produce a gel. This is followed by the formation of tyloses in the vascular bundles, which block the movement of water and nutrients to the upper parts of the plant. A cross-section of the stem of an infected plant is reddish-brown.","zh":"<em>Fusarium oxysporum</em>的感染会触发植株的防御机制，使其分泌胶状物。随后维管束内形成侵填体（tylose），阻断水分和养分向植株上部输送。受感染植株的茎部横截面呈红褐色。"}}]}],"sci":"<em>Fusarium oxysporum</em> f. sp. <em>cubense</em>","kind":"fungus","ai":[]},{"id":3,"crops":["BANANA"],"name":{"ms":"Nematod Parasit Tanaman","en":"Plant-Parasitic Nematodes","zh":"植物寄生线虫"},"desc":{"ms":"Nematoda parasitik pada tanaman pisang di Malaysia trmasuk <em>Pratylenchus reniformis</em>, <em>Melodogyne incognita</em>, <em>Helicothylenchus </em>spp., <em>Radopholus </em>spp., <em>Pratylenchus</em> spp. Nematoda parasitik ini mendapatkan makanan daripada tisu kortikal akar. Aktiviti patogen ini menyebakan kerosakan pada akar tanaman yang dijangkiti dan menjejaskan pengambilan air dan nutrien. Tanaman yang terjejas dengan teruk adalah terbantut dan kurus serta daun kekuningan dengan garisan berwarna hijau-kekuningan di sepanjang daun. Tidak ada kaedah yang berkesan untuk mengawal penyakit ini oleh itu pokok yang dijangkiti harus dihapuskan dengan segera. Tanah dan tanaman yang dijangkiti adalah dilarang untuk di bawa daripada kawasan ini.","en":"Plant-parasitic nematodes found on banana in Malaysia include <em>Pratylenchus reniformis</em>, <em>Meloidogyne incognita</em>, <em>Helicotylenchus</em> spp., <em>Radopholus</em> spp. and <em>Pratylenchus</em> spp. These nematodes feed on the cortical tissue of the roots. Their activity damages the roots of infected plants and reduces the uptake of water and nutrients. Badly affected plants are stunted and thin, with yellowish leaves that have greenish-yellow streaks along the leaf. There is no effective method to control this disease, so infected plants must be destroyed immediately. Soil and plants from infected areas must not be moved out of the area.","zh":"马来西亚香蕉上的植物寄生线虫包括 <em>Pratylenchus reniformis</em>、<em>Meloidogyne incognita</em>（南方根结线虫）、<em>Helicotylenchus</em> spp.（螺旋线虫）、<em>Radopholus</em> spp.（穿孔线虫）和 <em>Pratylenchus</em> spp.（根腐线虫）。这些线虫以根部皮层组织为食，会损伤受感染植株的根系，影响水分和养分的吸收。严重受害的植株矮小、瘦弱，叶片发黄，并沿叶片出现黄绿色条纹。目前没有有效的方法防治此病，因此受感染的植株必须立即销毁。禁止将受感染地区的泥土和植株带出该地区。"},"symptoms":[{"part":"ROOT","img":"Nematode_on_banana_roots_9Qo331x.jpg","text":{"ms":"Akar yang dijangkiti mempunyai kesan luka dan tisu-tisu yang mati.","en":"Infected roots have lesions and dead tissue.","zh":"受感染的根部有伤斑和坏死组织。"},"steps":[{"img":"THUMBNAIL_13_ehl8bbR.jpg","text":{"ms":"Akar yang dijangkiti mempunyai kesan luka dan tisu-tisu yang mati.","en":"Infected roots have lesions and dead tissue.","zh":"受感染的根部有伤斑和坏死组织。"}}]},{"part":"PLANT","img":"Nematode_on_banana2.jpg","text":{"ms":"Pokok pisang yang dijangkiti adalah terbantut dan kurus dengan daun yang menguning. Pokok yang teruk dijangkiti menjadi layu walaupun dalam cuaca yang kurang panas serta mudah tumbang.","en":"Infected banana plants are stunted and thin, with yellowing leaves. Badly infected plants wilt even when the weather is not very hot, and topple over easily.","zh":"受感染的香蕉植株矮小、瘦弱，叶片发黄。严重受感染的植株即使天气不太热也会萎蔫，而且容易倒伏。"},"steps":[{"img":"THUMBNAIL_12_VIK46Rg.jpg","text":{"ms":"Pokok pisang yang dijangkiti adalah terbantut dan kurus dengan daun yang menguning. Pokok yang teruk dijangkiti menjadi layu walaupun dalam cuaca yang kurang panas serta mudah tumbang.","en":"Infected banana plants are stunted and thin, with yellowing leaves. Badly infected plants wilt even when the weather is not very hot, and topple over easily.","zh":"受感染的香蕉植株矮小、瘦弱，叶片发黄。严重受感染的植株即使天气不太热也会萎蔫，而且容易倒伏。"}}]},{"part":"LEAF","img":"THUMBNAIL_11.jpg","text":{"ms":"Daun kekuningan dan mempunyai garisan berwarna hijau-kekuningan.","en":"Leaves turn yellowish and have greenish-yellow streaks.","zh":"叶片发黄，并出现黄绿色条纹。"},"steps":[{"img":"THUMBNAIL_11.jpg","text":{"ms":"Daun menguning atau menunjukkan perubahan warna dan terdapat garisan hijau-kuning pada tepi daun.","en":"Leaves turn yellow or become discoloured, with greenish-yellow streaks along the edges of the leaf.","zh":"叶片发黄或变色，叶缘出现黄绿色条纹。"}},{"img":"THUMBNAIL_12.jpg","text":{"ms":"Pokok pisang yang dijangkiti oleh nematoda parasit senang tumbang walaupun tiupan angin tidak kencang.","en":"Banana plants infected by parasitic nematodes topple over easily, even when the wind is not strong.","zh":"受寄生线虫感染的香蕉植株很容易倒伏，即使风不大也会倒下。"}},{"img":"THUMBNAIL_13_zxP6RkZ.jpg","text":{"ms":"Akar pokok pisang yang di infestasi oleh nematoda parasit mempunyai kesan reput yang kecil yang tidak dalam dan hanya di permukaan. Infestasi yang teruk menyebabkan nekrosis pada akar.","en":"Roots of banana plants infested by parasitic nematodes have small, shallow rotting lesions only on the surface. Heavy infestation causes necrosis (death of tissue) in the roots.","zh":"受寄生线虫侵害的香蕉根部有细小、浅表的腐烂伤斑，只在表面。严重侵害会导致根部坏死。"}}]}],"sci":"<em>Meloidogyne incognita</em>, <em>Pratylenchus</em> spp., <em>Radopholus</em> spp., <em>Helicotylenchus</em> spp.","kind":"nematode","ai":[]},{"id":4,"crops":["BANANA"],"name":{"ms":"Sigatoka Hitam","en":"Black Sigatoka","zh":"香蕉黑条叶斑病"},"desc":{"ms":"Penyakit ini biasa menjangkiti tanaman pisang. Jangkitan bermula dengan bintik kekuningan pada daun yang kemudian membesar dengan warna ungu/hitam ditengahnya. Jangkitan yang teruk menyebabkan pokok kelihatan seperti terbakar. Penyakit boleh dikawal dengan pemangkasan dan penggunaan racun kulat seperti Mancozeb.","en":"This disease commonly infects banana plants. Infection begins as yellowish spots on the leaves, which then enlarge with a purple/black centre. Severe infection makes the plant look as if it has been burnt. The disease can be controlled by pruning and by using fungicides such as Mancozeb.","zh":"这种病害常见于香蕉。感染初期叶片上出现淡黄色斑点，之后斑点扩大，中间呈紫色或黑色。严重感染时植株看起来像被火烧过一样。可通过修剪及使用杀菌剂如代森锰锌 Mancozeb 来防治。"},"symptoms":[{"part":"LEAF","img":"Penyakit_Pisang_Sigatoka_Hitam_PnG.jpg","text":{"ms":"Bintik Hitam Sigatoka","en":"Black Sigatoka leaf spot","zh":"黑条叶斑病叶斑"},"steps":[]}],"sci":"<em>Mycosphaerella fijiensis</em>","kind":"fungus","ai":["Mancozeb"]},{"id":16,"crops":["DURIAN"],"name":{"ms":"Kulat Phytophthora","en":"Phytophthora Fungus","zh":"榴莲疫病（棕榈疫霉）"},"desc":{"ms":"Kulat <em>Phytophthora palmivora</em> adalah patogen yang sering dilaporkan pada durian. Ia boleh menjadi penyebab kepada penyakit Bengkak Cerana Durian dan Reput Buah Phytophthora. Ia adalah patogen yang berkesan di mana ia akan menghasilkan sporangium yang mempunyai kemampuan untuk bertahan dan menyebar melalui udara dan mempunyai sporulasi yang cepat di tanaman. Zoospora dapat memasuki akar secara kimia dan elektrostatik. Ia juga dapat hidup lama di dalam dan di luar tanaman.","en":"The fungus <em>Phytophthora palmivora</em> is a pathogen often reported on durian. It can cause Durian Patch Canker and Phytophthora Fruit Rot. It is an effective pathogen: it produces sporangia that can survive and spread through the air, and it sporulates quickly on the plant. Its zoospores can enter the roots, attracted chemically and electrostatically. It can also survive for a long time both inside and outside the plant.","zh":"<em>Phytophthora palmivora</em>（棕榈疫霉）是榴莲上常见的病原菌，可引起榴莲斑块溃疡病（茎溃疡）和疫霉果腐病。这种病原菌侵染力强，会产生孢子囊，能够存活并随空气传播，在植株上产孢速度很快。其游动孢子可通过化学和静电吸引进入根部。它在植株体内外都能长期存活。"},"symptoms":[{"part":"FR","img":"fruitrotdurian.jpg","text":{"ms":"Pada peringkat awal, tompok<em> lesion</em> kecil berwarna coklat gelap akan bertukar kepada warna hitam pada permukaan buah. Apabila keadaan lembab dan sesuai, miselium kulat akan tumbuh pada <em>lesion</em> yang berwarna putih dan hitam. Buah tersebut akan menjadi reput dan busuk dalam masa beberapa hari sahaja. Ia juga akan merosakkan bahagian biji buah durian.","en":"In the early stage, small dark brown <em>lesion</em> spots appear on the fruit surface and turn black. In moist, favourable conditions, white and black fungal mycelium grows on the <em>lesions</em>. The fruit becomes rotten and foul within just a few days. It also damages the seeds of the durian fruit.","zh":"初期，果实表面出现深褐色的小<em>病斑</em>，随后变成黑色。在潮湿适宜的条件下，<em>病斑</em>上会长出白色和黑色的菌丝。果实在短短几天内便会腐烂发臭，还会损坏榴莲的种子。"},"steps":[{"img":"fruitrotdurian.jpg","text":{"ms":"Tompok<em> lesion</em> kecil berwarna coklat gelap yang akan bertukar kepada warna hitam pada permukaan buah. Miselium kulat berwarna putih dan hitam akan kelihatan. Perhatikan juga buah yang kelihatan reput dan berbau busuk.","en":"Small dark brown <em>lesion</em> spots on the fruit surface that turn black. White and black fungal mycelium can be seen. Also look for fruit that appears rotten and smells foul.","zh":"果实表面出现深褐色的小<em>病斑</em>，并逐渐变黑，可见白色和黑色的菌丝。同时留意外观腐烂、发出臭味的果实。"}}]},{"part":"PLANT","img":"canker_durian_new.jpg","text":{"ms":"Pada peringkat jangkitan teruk, daun akan menjadi layu dan gugur. Bunga pada pokok akan keluar dengan banyak dan akhirnya pokok akan mati.","en":"When the infection is severe, the leaves wilt and fall. The tree produces a large number of flowers and eventually dies.","zh":"感染严重时，叶片会萎蔫脱落。树上会大量开花，最终整棵树死亡。"},"steps":[{"img":"canker_durian_new_zGYkrtN.jpg","text":{"ms":"Pokok mula mengeluarkan bunga yang banyak dan daun-daun gugur. Ini menandakan pokok durian itu akan mati.","en":"The tree starts producing many flowers and the leaves fall. This is a sign that the durian tree is going to die.","zh":"树开始大量开花，叶片脱落。这表示这棵榴莲树即将死亡。"}}]},{"part":"STEM","img":"rotdurian.jpg","text":{"ms":"Berlakunya<em> lesion</em> pada permukaan kulit kayu dan damar yang mengalir berwarna coklat kemerahan. Jangkitan bermula pada bahagian batang dan bergerak ke atas. Apabila kulit dikikis, tisu pada batang kelihatan kemerahan dan ranting akan layu dan kering diikuti dengan kematian dahan pada bahagian atas.","en":"<em>Lesions</em> form on the bark surface, with reddish-brown sap oozing out. The infection starts on the trunk and moves upwards. When the bark is scraped, the tissue underneath looks reddish, and the twigs wilt and dry out, followed by dieback of the upper branches.","zh":"树皮表面出现<em>病斑</em>，并流出红褐色的树液（流胶）。感染从树干开始，向上蔓延。刮开树皮，可见树干组织呈红色，小枝萎蔫干枯，随后上部枝条枯死。"},"steps":[{"img":"rotdurian_2BGtF8q.jpg","text":{"ms":"Terdapat<em> lesion</em> pada permukaan kulit kayu dan cairan damar berwarna coklat kemerahan. Apabila kulit dikikis, tisu pada batang akan kelihatan kemerahan dan ranting akan layu dan kering diikuti dengan kematian dahan pada bahagian atas.","en":"<em>Lesions</em> on the bark surface with reddish-brown sap. When the bark is scraped, the tissue of the trunk looks reddish, and the twigs wilt and dry out, followed by dieback of the upper branches.","zh":"树皮表面有<em>病斑</em>，并流出红褐色树液。刮开树皮，可见树干组织呈红色，小枝萎蔫干枯，随后上部枝条枯死。"}}]}],"sci":"<em>Phytophthora palmivora</em>","kind":"oomycete","ai":[]},{"id":20,"crops":["DURIAN"],"name":{"ms":"Antraknos Daun Durian","en":"Durian Leaf Anthracnose","zh":"榴莲炭疽病"},"desc":{"ms":"<em>Colletothricum gloeosporioides </em>menyebabkan Antraknos Daun di ladang durian. Jangkitan dan perkembangan penyakit oleh fungus ini biasanya bergantung pada air hujan dan juga memerlukan suhu antara 20-25 darjah Celcius agar konidia bercambah dan jangkitan berlaku. Jangkitan bermula dengan konidia yang bercambah yang menghasilkan apesoria yang melekat kuat pada permukaan inang. Ia kemudian akan menembusi kutikula host dan dinding sel. Untuk mengelakkan perkara ini berlaku, pastikan selalu mengamalkan Amalan Pertanian yang Baik (APB) di mana semua daun yang gugur di ladang harus dibersihkan terutama di pangkal pokok agar penyakit tidak merebak. Pemangkasan dahan secara berkala untuk meningkatkan pengudaraan di dalam kanopi dan mengurangkan kelembapan di sekitar pokok. Di bawah jangkitan teruk, semburkan racun kulat sistemik seperti benomyl dan carbendazim dan bergantian dengan fungisida sentuhan (mancozeb dan maneb dalam masa 7-10 hari.","en":"<em>Colletotrichum gloeosporioides</em> causes Leaf Anthracnose in durian farms. Infection and disease development by this fungus usually depend on rainwater, and a temperature of 20-25 degrees Celsius is needed for the conidia (spores) to germinate and for infection to happen. Infection starts when the conidia germinate and form appressoria that stick firmly to the surface of the host plant. The fungus then breaks through the host cuticle and cell walls. To prevent this, always practise Good Agricultural Practices (GAP): clean up all fallen leaves in the farm, especially at the base of the tree, so that the disease does not spread. Prune branches regularly to improve air flow inside the canopy and reduce humidity around the tree. In severe infection, spray a systemic fungicide such as benomyl or carbendazim, alternating with a contact fungicide (mancozeb or maneb), at 7-10 day intervals.","zh":"<em>Colletotrichum gloeosporioides</em>（胶孢炭疽菌）会引起榴莲园的叶片炭疽病。这种真菌的侵染和病害发展通常依赖雨水，而且需要20-25摄氏度的温度，分生孢子才能萌发并造成侵染。侵染开始时，萌发的分生孢子形成附着胞，牢牢附着在寄主表面，然后穿透寄主的角质层和细胞壁。为避免发生这种情况，务必坚持良好农业规范（APB/GAP）：清除园内所有落叶，特别是树干基部的落叶，以免病害蔓延。定期修剪枝条，改善树冠内的通风，降低树木周围的湿度。严重感染时，喷施内吸性杀菌剂如苯菌灵 benomyl 和多菌灵 carbendazim，并与保护性（触杀性）杀菌剂（代森锰锌 mancozeb 和代森锰 maneb）轮换使用，每隔7-10天喷一次。"},"symptoms":[{"part":"LEAF","img":"durianantrachnose.jpg","text":{"ms":"Berlaku pada pokok dan anak pokok yang kurang dijaga. Bintik nekrotik bulat atau tidak sekata pada bahagian daun atau tepi daun akan timbul. Bintik ini biasanya berwarna kelabu keperangan dan mempunyai beberapa lapisan seperti cincin yang berpusar di sekelilingnya. Serangan teruk akan menyebabkan daun gugur.","en":"Occurs on poorly maintained trees and seedlings. Round or irregular necrotic (dead) spots appear on the leaf or along the leaf edge. These spots are usually greyish-brown and have several ring-like layers circling around them. Severe attack causes the leaves to fall.","zh":"多发生在缺乏照顾的果树和幼苗上。叶片上或叶缘出现圆形或不规则的坏死斑。这些病斑通常呈灰褐色，周围有好几层像环纹一样的同心轮纹。严重侵染会导致落叶。"},"steps":[{"img":"durianantrachnose_Ta9FAhC.jpg","text":{"ms":"Bintik nekrotik bulat atau tidak sekata pada bahagian daun atau tepi daun akan timbul. Bintik ini biasanya berwarna kelabu keperangan dan mempunyai beberapa lapisan seperti cincin yang berpusar di sekelilingnya. Serangan teruk akan menyebabkan daun gugur.","en":"Round or irregular necrotic (dead) spots appear on the leaf or along the leaf edge. These spots are usually greyish-brown and have several ring-like layers circling around them. Severe attack causes the leaves to fall.","zh":"叶片上或叶缘出现圆形或不规则的坏死斑。这些病斑通常呈灰褐色，周围有好几层像环纹一样的同心轮纹。严重侵染会导致落叶。"}}]}],"sci":"<em>Colletotrichum gloeosporioides</em>","kind":"fungus","ai":["Benomyl","Carbendazim","Mancozeb","Maneb"]},{"id":22,"crops":["DURIAN"],"name":{"ms":"Cendawan Angin","en":"Pink Disease","zh":"榴莲赤衣病"},"desc":{"ms":"Kulat ini akan menyerang ranting atau dahan pokok durian pada usia bawah 6 tahun. Kulat ini akan mengganggu sistem saliran nutrient pokok dan sangat aktif pada waktu hujan. Penanaman durian berhampiran ladang getah sangat berisiko tinggi untuk menghadapi masalah ini. Bagi mengelakkan masalah penyakit ini, sentiasa amalkan Amalan Pertanian Baik (APB) dengan mencantas dan memusnahkan bahagian yang dijangkiti untuk pengudaraan yang baik bagi mengelakkan jangkitan penyakit. Bagi penanaman baru, pastikan jarak tanaman adalah seperti yang disyorkan. Bagi kaedah pengawalan kimia, sembur atau sapu racun kulat sistemik (benomyl, carbendazim, tridemorph) dan diselangselikan dengan racun kulat sentuh (copper oxychloride) pada setiap 7-10 hari.","en":"This fungus attacks the twigs and branches of durian trees under 6 years old. It disrupts the flow of nutrients in the tree and is very active in rainy weather. Durian planted near rubber estates is at very high risk of this problem. To prevent this disease, always follow Good Agricultural Practices (GAP): prune and destroy infected parts so the tree is well ventilated and infection is avoided. For new plantings, make sure the planting distance is as recommended. For chemical control, spray or paint on a systemic fungicide (benomyl, carbendazim, tridemorph), alternating with a contact fungicide (copper oxychloride), every 7-10 days.","zh":"这种真菌危害6年以下榴莲树的小枝和枝条。它会干扰树体的养分输送，在雨天特别活跃。靠近橡胶园种植的榴莲发生此病的风险非常高。为预防此病，应始终遵循良好农业规范（APB/GAP）：修剪并销毁受感染部位，使树冠通风良好，避免感染。新种植时，确保株距符合建议。化学防治方面，每7-10天喷洒或涂抹内吸性杀菌剂（苯菌灵 benomyl、多菌灵 carbendazim、十三吗啉 tridemorph），并与保护性（接触性）杀菌剂（氧氯化铜 copper oxychloride）轮换使用。"},"symptoms":[{"part":"STEM","img":"newdurianpinkdisease.jpg","text":{"ms":"Pada peringkat awal, miselium berwarna putih pada kulit dahan atau ranting akan kelihatan. Miselium ini akan menjadi bebenang berwarna merah jambu dan lama-kelamaan ranting atau dahan yang dijangkiti akan mati dan meninggalkan lapisan miselium yang tebal berwarna merah jambu keputihan.","en":"In the early stage, white mycelium can be seen on the bark of branches or twigs. This mycelium turns into pink threads, and over time the infected twigs or branches die, leaving a thick layer of whitish-pink mycelium.","zh":"早期可在枝条或小枝的树皮上看到白色菌丝。菌丝随后变成粉红色的丝状物，久而久之受感染的小枝或枝条会枯死，并留下一层厚厚的粉白色菌丝。"},"steps":[{"img":"newdurianpinkdisease_IlOh0Cf.jpg","text":{"ms":"Terdapat miselium berwarna putih pada kulit dahan atau ranting dan akan menjadi bebenang berwarna merah jambu. Lama-kelamaan ranting atau dahan yang dijangkiti akan mati dan meninggalkan lapisan miselium yang tebal berwarna merah jambu keputihan.","en":"White mycelium appears on the bark of branches or twigs and turns into pink threads. Over time the infected twigs or branches die, leaving a thick layer of whitish-pink mycelium.","zh":"枝条或小枝的树皮上出现白色菌丝，并变成粉红色的丝状物。久而久之，受感染的小枝或枝条会枯死，留下一层厚厚的粉白色菌丝。"}}]}],"sci":"<em>Corticium salmonicolor</em>","kind":"fungus","ai":["Benomyl","Carbendazim","Copper","Tridemorph"]},{"id":25,"crops":["DURIAN"],"name":{"ms":"Alga Trentepohlia","en":"Trentepohlia Algae","zh":"橘色藻"},"desc":{"ms":"Alga ini adalah sejenis parasit tumbuhan pada tanaman durian. Ia boleh dielakkan dengan melakukan pemangkasan bagi meningkatkan pengudaraan di sekeliling pokok dan mengurangkan kelembapan. Pengairan dan pembajaan yang sempurna boleh mengurangkan infestasi alga ini. Jika berlaku infestasi yang teruk, semburan racun kulat berasaskan kuprum boleh dilakukan.","en":"This alga is a plant parasite on durian trees. It can be prevented by pruning to improve air flow around the tree and reduce humidity. Proper watering and fertilising can reduce infestation by this alga. If the infestation is severe, a copper-based fungicide spray can be applied.","zh":"这种藻类是寄生在榴莲树上的植物寄生物。可以通过修剪枝条来增加树体周围的通风、降低湿度，从而预防它。适当的灌溉和施肥可以减少这种藻类的侵染。如果侵染严重，可以喷施铜基杀菌剂。"},"symptoms":[{"part":"STEM","img":"Trentepohlia_Durian.jpg","text":{"ms":"Batang dan dahan diselaputi oleh lapisan berwarna oren keemasan terang pada bahagian kulit pokok yang terdedah kepada cahaya matahari. Bagi pokok yang terlindung atau batang lembap, alga ini akan berwarna hijau keputihan. Ini akan mengganggu pengeluaran buah dan bunga.","en":"The trunk and branches are covered with a bright golden-orange layer on the parts of the bark exposed to sunlight. On shaded trees or damp trunks, the alga appears whitish-green. This interferes with fruit and flower production.","zh":"树干和枝条上暴露在阳光下的树皮部分覆盖着一层鲜艳的金橙色物质。在遮荫的树或潮湿的树干上，这种藻类呈白绿色。这会影响开花和结果。"},"steps":[{"img":"Trentepohlia_Durian.jpg","text":{"ms":"Perhatikan pada batang dan dahan jika terdapat selaput lapisan berwarna oren keemasan terang pada bahagian kulit pokok yang terdedah kepada cahaya matahari. Bagi pokok yang terlindung atau batang lembap, alga ini akan berwarna hijau keputihan.","en":"Check the trunk and branches for a bright golden-orange layer on the parts of the bark exposed to sunlight. On shaded trees or damp trunks, the alga appears whitish-green.","zh":"检查树干和枝条上暴露在阳光下的树皮部分是否覆盖着一层鲜艳的金橙色物质。在遮荫的树或潮湿的树干上，这种藻类呈白绿色。"}}]}],"sci":"<em>Trentepohlia</em> spp.","kind":"alga","ai":["Copper"]},{"id":26,"crops":["DURIAN"],"name":{"ms":"Liken","en":"Lichen","zh":"地衣"},"desc":{"ms":"Alga ini akan menyebabkan Infestasi Liken pada pokok. Ia akan menyerang pokok yang berada di kawasan berkelembapan tinggi, terutama pada musim hujan. Sekiranya terdapat jangkitan teruk, lakukan penyemburan dengan racun kulat yang mengandungi kuprum dan emulsi minyak. Penyemburan akan lebih berkesan apabila dilakukan semasa liken kering.","en":"This alga causes lichen infestation on trees. It attacks trees in areas with high humidity, especially during the rainy season. If the infection is severe, spray with a copper-based fungicide and an oil emulsion. Spraying is more effective when it is done while the lichen is dry.","zh":"这种藻类会使树木受地衣侵染。它会侵害处于高湿度地区的树木，尤其是在雨季。如果感染严重，可喷洒含铜的杀菌剂和油乳剂。在地衣干燥时喷洒，效果会更好。"},"symptoms":[{"part":"STEM","img":"Durian_Lichen_.jpg","text":{"ms":"Infestasi akan berlaku pada batang. dahan dan daun. Tompok-tompok putih kehijauan akan kelihatan pada batang yang diserang. Jika serangan teruk, kulit pokok akan terbelah. Ini akan memberikan kesan kepada pengeluaran bunga dan buah durian.","en":"Infestation occurs on the trunk, branches and leaves. Greenish-white patches appear on the attacked trunk. If the attack is severe, the tree bark will split. This affects the production of durian flowers and fruits.","zh":"侵染发生在树干、枝条和叶片上。受害的树干上会出现青白色斑块。如果侵害严重，树皮会裂开。这会影响榴莲开花和结果。"},"steps":[{"img":"Durian_Lichen_.jpg","text":{"ms":"Perhatikan infestasi lichen pada batang. dahan dan daun. Tompok-tompok putih kehijauan akan kelihatan pada batang yang diserang. Jika serangan teruk, kulit pokok akan terbelah.","en":"Look for lichen infestation on the trunk, branches and leaves. Greenish-white patches appear on the attacked trunk. If the attack is severe, the tree bark will split.","zh":"检查树干、枝条和叶片上是否有地衣侵染。受害的树干上会出现青白色斑块。如果侵害严重，树皮会裂开。"}}]}],"sci":"<em>Parmelia</em> sp.","kind":"lichen","ai":["Copper"]},{"id":27,"crops":["DURIAN"],"name":{"ms":"Karat Alga Cephaleuros","en":"Cephaleuros Algal Rust","zh":"榴莲藻斑病（红锈藻病）"},"desc":{"ms":"Alga ini akan menyebabkan penyakit iaitu Karat Alga Cephaleuros pada daun durian. Ini adalah alga hijau filamen yang dikenali sebagai parasit pada tumbuhan yang lebih tinggi. Sentiasa amalkan Good Agriculture Pratices (GAP) di mana pembajaan dan pengairan dilakukan dengan baik dan bertani bebas daripada rumpai terutamanya di sekitar pokok. Jarak penanaman juga mesti mengikut cadangan untuk memastikan pengudaraan yang baik dan mengurangkan kelembapan di sekitar pokok.","en":"This alga causes a disease called Cephaleuros Algal Rust on durian leaves. It is a filamentous green alga known to be a parasite of higher plants. Always follow Good Agricultural Practices (GAP): fertilise and irrigate properly and keep the farm free of weeds, especially around the trees. Planting distance must also follow the recommendation to ensure good air flow and to reduce humidity around the trees.","zh":"这种藻类会引起榴莲叶片的藻斑病（红锈藻病）。它是一种丝状绿藻，已知会寄生于高等植物。应始终遵守良好农业规范（GAP）：做好施肥和灌溉，保持农场无杂草，尤其是树木周围。种植距离也必须按照建议，以确保通风良好并降低树木周围的湿度。"},"symptoms":[{"part":"LEAF","img":"Untitled-3_cSYjWfC.jpg","text":{"ms":"Tompok-tompok perang kemerahan seperti baldu akan kelihatan pada permukaan daun dan ranting. Daun akan menjadi kekuningan dan gugur.","en":"Reddish-brown, velvet-like spots appear on the surface of leaves and twigs. The leaves turn yellowish and fall off.","zh":"叶片和小枝表面出现红褐色、像天鹅绒般的斑点。叶片会变黄并脱落。"},"steps":[{"img":"Untitled-3_cZ3wCxL.jpg","text":{"ms":"Tompok-tompok perang kemerahan seperti baldu akan kelihatan pada permukaan daun dan ranting. Daun akan menjadi kekuningan dan gugur.","en":"Reddish-brown, velvet-like spots appear on the surface of leaves and twigs. The leaves turn yellowish and fall off.","zh":"叶片和小枝表面出现红褐色、像天鹅绒般的斑点。叶片会变黄并脱落。"}}]}],"sci":"<em>Cephaleuros virescens</em>","kind":"alga","ai":[]},{"id":29,"crops":["MAIZE"],"name":{"ms":"Karat Daun Jagung","en":"Maize Leaf Rust","zh":"玉米锈病"},"desc":{"ms":"Kulat ini menyebabkan Karat Daun di jagung. Ini adalah penyakit yang paling membimbangkan yang mempengaruhi pertumbuhan jagung. Patogen ini juga menjangkiti hos lain yang akan menyebabkan membantutkan tumbesaran tumbuhan. Untuk mengelakkan ini berlaku, musnahkan tanaman yang dijangkiti dan amalkan tanaman giliran. Sentiasa pastikan bahawa ladang mempunyai sistem saliran yang baik dan gunakan varieti biji benih yang rintang terhadap penyakit ini. Gunakan racun kimia seperti tebuconazole dengan kadar yang disyorkan.","en":"This fungus causes leaf rust in maize. It is the most worrying disease affecting maize growth. The pathogen also infects other hosts and stunts plant growth. To prevent this, destroy infected plants and practise crop rotation. Always make sure the field has good drainage and use seed varieties that are resistant to this disease. Use chemical fungicides such as tebuconazole at the recommended rate.","zh":"这种真菌会引起玉米锈病，是影响玉米生长最令人担忧的病害。该病原菌也会侵染其他寄主，使植株生长受阻。为防止发病，应销毁受感染的植株并实行轮作。务必确保田地排水良好，并使用抗此病的种子品种。可按推荐用量使用化学药剂，如戊唑醇 Tebuconazole。"},"symptoms":[{"part":"LEAF","img":"Untitled-5.jpg","text":{"ms":"Bintik berbentuk bujur dan berwarna oren/karat besi pada permukaan daun yang mengakibatkan daun-daun menjadi kering. Seludang daun juga akan dijangkiti dan dalam keadaan tertentu daun akan klorosis atau mati.","en":"Oval, orange/rust-coloured spots appear on the leaf surface, causing the leaves to dry out. The leaf sheath is also infected, and in some conditions the leaves become yellow (chlorosis) or die.","zh":"叶片表面出现椭圆形、橙色/铁锈色的斑点，导致叶片干枯。叶鞘也会受感染，在某些情况下叶片会黄化（褪绿）或枯死。"},"steps":[]}],"sci":"<em>Puccinia polysora</em> Underw., <em>Puccinia sorghi</em> Schwein.","kind":"fungus","ai":["Tebuconazole"]},{"id":38,"crops":["PADDY"],"name":{"ms":"Hawar Daun Bakteria","en":"Bacterial Leaf Blight","zh":"水稻白叶枯病"},"desc":{"ms":"Ia adalah patogen bakteria yang menyebabkan Hawar Daun Bakteria serius pada padi. Patogen ini tersebar dan menjangkiti urat daun dan xilem yang menyebabkan penyumbatan dan juga layu. <em>Bacterial ooze</em> yang keluar dari <em>lesion</em> daun disebarkan oleh angin atau hujan dan menyebabkan luka pada tanaman. Untuk mengelakkan hal ini terjadi, gunakan varieti padi yang rintang dari penyakit ini, elakkan penggunaan baja yang berlebihan dan kawal paras air di ladang.","en":"This is a bacterial pathogen that causes serious Bacterial Leaf Blight in paddy. The pathogen spreads in the plant and infects the leaf veins and xylem, causing blockage and wilting. <em>Bacterial ooze</em> coming out of the leaf <em>lesions</em> is spread by wind or rain and infects plants through wounds. To prevent this, use paddy varieties that are resistant to this disease, avoid using too much fertiliser and control the water level in the field.","zh":"这是一种细菌性病原体，会在稻田引起严重的白叶枯病。病原菌在植株内扩散，侵染叶脉和木质部，造成堵塞并导致萎蔫。从叶片<em>病斑</em>渗出的<em>菌脓</em>会随风或雨水传播，并从伤口侵染植株。为防止发生，应种植抗此病的水稻品种，避免过量施肥，并控制田间水位。"},"symptoms":[{"part":"LEAF","img":"BLLLLLLLLLLLLLLLB.jpg","text":{"ms":"Kecederaan bermula di tepi hujung daun. Warnanya hijau pucat ke hijau kelabu, yang kemudiannya bertukar menjadi putih dan kemudian kuning. Garisan kecederaan tidak sama. Hujung daun menjadi kering dan bergulung ke dalam.","en":"Lesions start at the edge of the leaf tip. They are pale green to greyish green, then turn white and later yellow. The edges of the lesions are uneven (wavy). The leaf tips dry up and roll inwards.","zh":"病斑从叶尖边缘开始出现，颜色由淡绿色至灰绿色，随后变白，再转黄。病斑边缘不整齐（呈波浪状）。叶尖干枯并向内卷曲。"},"steps":[]}],"sci":"<em>Xanthomonas campestris</em> pv. <em>oryzae</em>","kind":"bacteria","ai":[]},{"id":41,"crops":["PADDY"],"name":{"ms":"Penyakit Karah","en":"Rice Blast","zh":"稻瘟病"},"desc":{"ms":"<p><em>Pycularia oryzae </em>adalah kulat yang menyebabkan Karah daun dan Karah Tangkai pada padi. Penyakit Ini adalah penyakit yang paling serius dalam penanaman padi. Ia adalah kulat fitopatogenik berfilamen yang menjadi nekrotropik yang memusnahkan tisu tumbuhan.</p><p><strong>Kawalan</strong></p><ul><li>Amalkan Amalan Pertanian yang Baik di ladang.</li><li>Bersihkan kawasan sawah dari rumpai dengan menebas, membakar semua jerami padi dan tunggul.</li><li> Gunakan biji yang sihat dengan mengikuti kadar yang disarankan (120kg / ha).</li><li>Rawat benih dengan racun kulat seperti benomil (4g / kg biji) atau captan (2g / kg biji).</li><li>Gunakan baja nitrogen pada kadar yang disyorkan (120 kg N/ha) dan secara berperingkat dengan mengikut keperluan.</li><li>Gunakan baja silika (kadar yang disarankan 50-75 kg / ha) sebagai baja asas untuk mengurangkan jangkitan penyakit.</li></ul>","en":"<p><em>Pyricularia oryzae</em> is the fungus that causes leaf blast and neck blast in rice. This is the most serious disease in rice cultivation. It is a filamentous plant-pathogenic fungus that becomes necrotrophic and destroys plant tissue.</p><p><strong>Control</strong></p><ul><li>Follow Good Agricultural Practices in the field.</li><li>Clear weeds from the paddy field by slashing, and burn all rice straw and stubble.</li><li>Use healthy seed at the recommended rate (120kg / ha).</li><li>Treat seed with a fungicide such as benomyl (4g / kg seed) or captan (2g / kg seed).</li><li>Apply nitrogen fertiliser at the recommended rate (120 kg N/ha), in split doses according to the crop's needs.</li><li>Apply silica fertiliser (recommended rate 50-75 kg / ha) as a basal fertiliser to reduce disease infection.</li></ul>","zh":"<p><em>Pyricularia oryzae</em>（稻瘟病菌）是引起水稻叶瘟和穗颈瘟的真菌。这是水稻种植中最严重的病害。它是一种丝状植物病原真菌，会转为坏死营养型，破坏植物组织。</p><p><strong>防治</strong></p><ul><li>在田间遵循良好农业规范。</li><li>通过砍除清理稻田杂草，并烧毁所有稻草和稻茬。</li><li>使用健康种子，并按建议用量播种（120kg / ha）。</li><li>用杀菌剂处理种子，例如苯菌灵 benomyl（4g / kg 种子）或克菌丹 captan（2g / kg 种子）。</li><li>按建议用量（120 kg N/ha）施用氮肥，并根据作物需要分次施用。</li><li>施用硅肥（建议用量 50-75 kg / ha）作为基肥，以减少病害感染。</li></ul>"},"symptoms":[{"part":"LEAF","img":"BBlast_lesion.jpg","text":{"ms":"Bintik daun berbentuk lonjong dan tajam di kedua-dua hujung. Bahagian tepi berwarna perang kemerahan dengan tengahnya berwarna kelabu keputihan.","en":"Leaf spots are oval (spindle-shaped) and pointed at both ends. The edges are reddish-brown with a whitish-grey centre.","zh":"叶斑呈椭圆形（梭形），两端尖。病斑边缘红褐色，中央灰白色。"},"steps":[]},{"part":"STEM","img":"blast_2.jpg","text":{"ms":"Jangkitan juga boleh berlaku pada buku batang padi dan pangkal tangkai padi yang menyebabkan penyakit reput tangkai. Serangan penyakit reput tangkai di peringkat awal pembentukan bulir boleh menyebabkan padi sambang.","en":"Infection can also occur on the stem nodes and at the base of the panicle (neck), causing neck rot. Neck rot at the early stage of grain formation can cause empty, unfilled grains (padi sambang).","zh":"病菌也可侵染稻茎的节和稻穗基部（穗颈），引起穗颈腐烂（穗颈瘟）。在谷粒形成初期发生穗颈瘟，会造成空瘪粒（padi sambang）。"},"steps":[]}],"sci":"<em>Pyricularia oryzae</em>","kind":"fungus","ai":["Benomyl","Captan"]},{"id":42,"crops":["PADDY"],"name":{"ms":"Bintik Perang","en":"Brown Spot","zh":"水稻胡麻斑病"},"desc":{"ms":"<p><em>Cochliobolus miyabeanus </em>adalah kulat yang menyebabkan Penyakit Bintik Perang pada padi. Ia merupakan penyakit padi yang lazim dan berleluasa yang boleh menyebabkan petani kehilangan hasil padi yang tinggi. Penyakit berlaku di persekitaran yang lebih kering di mana jumlah air berkurang. Ia tumbuh dengan baik pada suhu rendah semasa peringkat perkembangan.</p><p><strong>Kawalan</strong></p><ul><li>Gunakan varieti padi yang tahan penyakit terutama di kawasan di mana kesuburan tanah menjadi masalah.</li><li>Gunakan baja silika sebelum penanaman untuk meningkatkan daya tahan dari jangkitan bintik perang dan untuk meningkatkan hasil.</li><li> Elakkan stress air kerana penyakit ini teruk ketika musim kemarau atau kekurangan air.</li><li>Bajak atau bakar semua tunggul dan sisa tanaman yang dijangkiti.</li><li>Sekiranya terdapat serangan teruk, semburkan dengan racun kulat seperti mancozeb + tricyclazole atau carbendazim pada peringkat bunting.</li><li>Rawat biji benih dengan racun kulat seperti thiram, captan, carbendazim dan mancozeb untuk mengurangkan jangkitan anak benih.</li></ul>","en":"<p><em>Cochliobolus miyabeanus</em> is the fungus that causes Brown Spot disease in rice. It is a common and widespread rice disease that can cause farmers to lose a large part of their harvest. The disease occurs in drier conditions where there is less water. It grows well at low temperatures during the growth stages.</p><p><strong>Control</strong></p><ul><li>Use disease-resistant rice varieties, especially in areas where soil fertility is a problem.</li><li>Apply silica fertiliser before planting to increase resistance to brown spot infection and to improve yield.</li><li>Avoid water stress, because this disease is severe during the dry season or when water is short.</li><li>Plough in or burn all infected stubble and crop residues.</li><li>If the attack is severe, spray with fungicides such as mancozeb + tricyclazole or carbendazim at the booting stage.</li><li>Treat seeds with fungicides such as thiram, captan, carbendazim and mancozeb to reduce seedling infection.</li></ul>","zh":"<p><em>Cochliobolus miyabeanus</em>是引起水稻胡麻斑病（褐斑病）的真菌。这是一种常见且分布广泛的水稻病害，可使农民的稻米产量大幅损失。病害多发生在较干燥、水量减少的环境中。在生长阶段，它在低温下生长良好。</p><p><strong>防治</strong></p><ul><li>使用抗病水稻品种，尤其是在土壤肥力有问题的地区。</li><li>种植前施用硅肥，以提高对胡麻斑病的抵抗力并提高产量。</li><li>避免水分胁迫，因为在旱季或缺水时此病会更严重。</li><li>将所有受感染的稻桩和作物残体翻耕入土或烧毁。</li><li>如果病害严重，在孕穗期喷施杀菌剂，例如 mancozeb（代森锰锌）+ tricyclazole（三环唑）或 carbendazim（多菌灵）。</li><li>用 thiram（福美双）、captan（克菌丹）、carbendazim（多菌灵）和 mancozeb（代森锰锌）等杀菌剂处理种子，以减少秧苗感染。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Untitled-2_6r41B6p.jpg","text":{"ms":"Bintik bulat bujur di permukaan daun, saiz seperti bijan bergaris pusat 8*15 mm, berwarna perak coklat. Bahagian tengah bintik menjadi kelabu keputihan apabila bintik terbentuk sepenuhnya. Bintik juga terdapat pada glumes-kelihatan bintik perang gelap ataupun hitam pada glumes. Bintik perang terdapat pada keleoptil, batang, seludang daun, tangkai panikel dan akar pokok semakin matang.","en":"Oval spots on the leaf surface, about the size of a sesame seed, 8–15 mm in diameter, silvery-brown in colour. The centre of the spot turns whitish-grey when the spot is fully formed. Spots also appear on the glumes (grain husks) as dark brown or black spots. Brown spots are also found on the coleoptile, stem, leaf sheath, panicle stalk and roots as the plant matures.","zh":"叶面出现椭圆形斑点，大小如芝麻粒，直径 8–15 mm，呈银褐色。斑点完全形成后，中央变成灰白色。颖壳（谷壳）上也会出现深褐色或黑色斑点。随着植株成熟，胚芽鞘、茎秆、叶鞘、穗柄和根部也会出现褐色斑点。"},"steps":[{"img":"Untitled-2.jpg","text":{"ms":"Perhatikan bintik bulat bujur di permukaan daun yang berwarna perak coklat. Bahagian tengah bintik menjadi kelabu keputihan apabila bintik terbentuk sepenuhnya. Bintik juga terdapat pada glumes-kelihatan bintik perang gelap ataupun hitam pada glumes.","en":"Look for oval, silvery-brown spots on the leaf surface. The centre of the spot turns whitish-grey when the spot is fully formed. Spots also appear on the glumes (grain husks) as dark brown or black spots.","zh":"观察叶面是否有椭圆形、银褐色的斑点。斑点完全形成后，中央变成灰白色。颖壳（谷壳）上也会出现深褐色或黑色斑点。"}}]}],"sci":"<em>Cochliobolus miyabeanus</em>","kind":"fungus","ai":["Captan","Carbendazim","Mancozeb","Thiram","Tricyclazole"]},{"id":43,"crops":["PADDY"],"name":{"ms":"Bintik Perang Tirus","en":"Narrow Brown Leaf Spot","zh":"水稻窄条斑病"},"desc":{"ms":"Kulat ini menyebabkan Bintik Perang Tirus pada padi. Ia boleh menjangkiti daun, sarung dan panikel. Penyakit ini biasanya berlaku di tanah yang kekurangan potasium dan di kawasan dengan suhu antara 25-28 darjah Celsius. Ia muncul pada peringkat akhir tanaman padi, bermula pada tahap awal. Tumbuhan paling mudah dijangkiti semasa permulaan panikel dan kerosakan menjadi lebih teruk apabila tanaman semakin matang. Untuk mengelakkan ini terjadi, gunakan varieti padi yang tahan dari penyakit ini dan lakukan pembajaan dengan baja yang mengandungi potassium dan phosphorus. Adalah tidak ekonomi untuk menggunakan racun kulat tetapi penyemburan racun kulat dapat mengawal penyakit kulat lain untuk mencegah penyakit ini.","en":"This fungus causes narrow brown leaf spot in paddy. It can infect the leaves, leaf sheaths and panicles. The disease usually occurs in potassium-deficient soils and in areas with temperatures between 25-28 degrees Celsius. It appears in the late stages of the rice crop, starting from heading. Plants are most easily infected from panicle initiation onwards, and the damage becomes more severe as the crop matures. To prevent it, plant rice varieties that are resistant to this disease and apply fertiliser containing potassium and phosphorus. Using fungicide is not economical, but fungicide sprays used to control other fungal diseases can also help prevent this disease.","zh":"这种真菌会引起水稻窄条斑病。它可以感染叶片、叶鞘和稻穗。此病通常发生在缺钾的土壤，以及气温在25-28摄氏度之间的地区。它出现在水稻生长后期，从抽穗期开始。植株在幼穗分化期以后最容易受感染，越接近成熟，损害越严重。为预防此病，应种植抗病的水稻品种，并施用含钾和磷的肥料。专门使用杀菌剂并不划算，但为防治其他真菌病害而喷洒的杀菌剂也可以帮助预防此病。"},"symptoms":[{"part":"LEAF","img":"brown_spot_paddy.jpg","text":{"ms":"<em>Lesion</em> yang pendek, lurus dan halus (lebih kurang 2-20 mm panjang dan 1 mm lebar) berwarna coklat keperangan pada permukaan daun. <em>Lesion</em> in juga terdapat pada seludang daun, pedikel, <em>glume </em>atau <em>rice hull</em>.","en":"Short, straight, narrow <em>lesions</em> (about 2-20 mm long and 1 mm wide), reddish-brown in colour, on the leaf surface. These <em>lesions</em> are also found on the leaf sheath, pedicel, <em>glume</em> or <em>rice hull</em>.","zh":"叶面上出现短、直而细的红褐色<em>病斑</em>（长约2-20 mm，宽约1 mm）。这些<em>病斑</em>也会出现在叶鞘、小穗梗、<em>颖片</em>或<em>谷壳</em>上。"},"steps":[{"img":"narrow_brown_spot.jpg","text":{"ms":"<em>Lesion</em> yang pendek, lurus dan halus (lebih kurang 2-20 mm panjang dan 1 mm lebar) berwarna coklat keperangan pada permukaan daun. <em>Lesion</em> in juga terdapat pada seludang daun, pedikel, <em>glume </em>atau <em>rice hull</em>.","en":"Short, straight, narrow <em>lesions</em> (about 2-20 mm long and 1 mm wide), reddish-brown in colour, on the leaf surface. These <em>lesions</em> are also found on the leaf sheath, pedicel, <em>glume</em> or <em>rice hull</em>.","zh":"叶面上出现短、直而细的红褐色<em>病斑</em>（长约2-20 mm，宽约1 mm）。这些<em>病斑</em>也会出现在叶鞘、小穗梗、<em>颖片</em>或<em>谷壳</em>上。"}}]}],"sci":"<em>Cercospora oryzae</em> Miyake","kind":"fungus","ai":[]},{"id":44,"crops":["PADDY"],"name":{"ms":"Penyakit Hawar Seludang","en":"Sheath Blight","zh":"水稻纹枯病"},"desc":{"ms":"<p><em>Rhizoctonia solani </em>adalah kulat yang menyebabkan Hawar Seludang pada padi dan merupakan salah satu penyakit paling serius dalam penanaman padi. Jangkitan penyakit berlaku apabila padi mencapai pertumbuhan vegetatif sepenuhnya. Simptom dapat diperhatikan pada tahap tumbesaran maksimum atau tumbesaran batang.</p><p><strong>Kawalan</strong></p><ul><li>Gunakan biji benih yang sihat pada kadar optimum dan elakkan pembajaan berlebihan.</li><li>Penambahan baja kalium dan silika dapat mengurangkan jangkitan penyakit. </li><li>Pastikan paras air di tapak semaian tidak terlalu kering.</li><li>Bagi kawalan kimia, gunakan racun perosak kimia seperti isoprothiolane (2kg / ha) dan rawat benih dengan racun kulat seperti thiram (3g / 100g biji), benomil (4g / kg biji) atau captan (3g / 100g biji).</li></ul>","en":"<p><em>Rhizoctonia solani</em> is the fungus that causes sheath blight in paddy and is one of the most serious diseases in rice cultivation. Infection occurs when the paddy reaches full vegetative growth. Symptoms can be seen at the maximum tillering or stem elongation stage.</p><p><strong>Control</strong></p><ul><li>Use healthy seed at the optimum rate and avoid over-fertilising.</li><li>Adding potassium and silica fertiliser can reduce infection.</li><li>Make sure the water level in the nursery does not become too dry.</li><li>For chemical control, use pesticides such as isoprothiolane (2kg / ha) and treat seed with fungicides such as thiram (3g / 100g seed), benomyl (4g / kg seed) or captan (3g / 100g seed).</li></ul>","zh":"<p><em>Rhizoctonia solani</em>（立枯丝核菌）是引起水稻纹枯病的真菌，是稻米种植中最严重的病害之一。当水稻达到营养生长旺盛期时便会发生感染。症状可在分蘖盛期或拔节期观察到。</p><p><strong>防治</strong></p><ul><li>按最适用量使用健康的种子，避免过量施肥。</li><li>增施钾肥和硅肥可减少病害感染。</li><li>确保秧田水位不要太干。</li><li>化学防治方面，可使用农药如稻瘟灵 isoprothiolane（2kg / ha），并用杀菌剂处理种子，如福美双 thiram（3g / 100g 种子）、苯菌灵 benomyl（4g / kg 种子）或克菌丹 captan（3g / 100g 种子）。</li></ul>"},"symptoms":[{"part":"STEM","img":"6.jpg","text":{"ms":"Biasanya mula menyerang pada peringkat beranak maksimum. Bentuk lesi bujur dan melecuh, merebak dengan cepat pada peringkat berbunga sehingga pengisian biji bila terdapat hujan. Boleh menyebabkan padi rebah.","en":"Usually starts attacking at the maximum tillering stage. Lesions are oval and blister-like, and spread quickly from flowering until grain filling when there is rain. Can cause the rice plants to fall over (lodging).","zh":"通常在分蘖盛期开始发病。病斑呈椭圆形、像水泡状，遇雨时从开花期到灌浆期迅速扩散。可导致稻株倒伏。"},"steps":[]}],"sci":"<em>Rhizoctonia solani</em>","kind":"fungus","ai":["Benomyl","Captan","Isoprothiolane","Thiram"]},{"id":45,"crops":["PADDY"],"name":{"ms":"Penyakit Merah Virus (Tungro)","en":"Rice Tungro Disease","zh":"水稻东格鲁病（通格罗病）"},"desc":{"ms":"<p>Penyakit Merah Virus (Tungro) disebabkan oleh gabungan dua virus iaitu &#39;Rice tungro spherical virus&#39; (RTSV) dan &#39;Rice tungro bacilliform virus&#39; (RTBV). Penyakit ini disebarkan oleh bena hijau yang memakan tanaman yang dijangkiti virus tungro. Penyakit ini boleh berlaku pada semua peringkat pertumbuhan tanaman padi.</p><p><strong>Langkah Kawalan</strong></p><ul><li>Musnahkan tunggul padi dan rumpai yang dijangkiti.</li><li>Laksanakan penanaman secara serentak dan elakkan penggunaan baja nitrogen yang berlebihan.</li><li>Gunakan varieti tanaman yang tahan terhadap penyakit ini atau terhadap vektor serangga.</li><li>Kawal serangga vektor iaitu bena hijau menggunakan kaedah kawalan secara bersepadu. </li></ul>","en":"<p>Rice tungro disease is caused by a combination of two viruses: Rice tungro spherical virus (RTSV) and Rice tungro bacilliform virus (RTBV). The disease is spread by green leafhoppers that feed on plants infected with the tungro virus. It can occur at all growth stages of the rice plant.</p><p><strong>Control Measures</strong></p><ul><li>Destroy infected rice stubble and weeds.</li><li>Plant at the same time as neighbouring fields and avoid using too much nitrogen fertilizer.</li><li>Use varieties that are resistant to this disease or to the insect vector.</li><li>Control the insect vector, the green leafhopper, using integrated control methods.</li></ul>","zh":"<p>水稻东格鲁病由两种病毒共同引起：水稻东格鲁球状病毒（RTSV）和水稻东格鲁杆状病毒（RTBV）。此病由取食过染病植株的黑尾叶蝉（绿叶蝉）传播，可发生在水稻生长的各个阶段。</p><p><strong>防治措施</strong></p><ul><li>销毁受感染的稻桩和杂草。</li><li>统一同期种植，避免过量施用氮肥。</li><li>使用抗此病或抗传毒昆虫的品种。</li><li>以综合防治方法控制传毒昆虫——黑尾叶蝉。</li></ul>"},"symptoms":[{"part":"LEAF","img":"tungro-2.jpg","text":{"ms":"Daun yang diserang berwarna kuning muda hingga kuning jingga. Daun muda menjadi &#39;mottled&#39; dan berwarna hijau pucat keputihan di antara urat daun.","en":"Infected leaves turn light yellow to orange-yellow. Young leaves become 'mottled', with a pale whitish-green colour between the leaf veins.","zh":"受害叶片呈淡黄色至橙黄色。嫩叶出现“斑驳”，叶脉之间呈淡绿偏白色。"},"steps":[]},{"part":"PLANT","img":"Untitled-3_HGL1VcX.jpg","text":{"ms":"<ul><li>Pokok terbantut. </li><li>Lambat berbunga</li><li>Pengeluaran tangkai tidak sempurna</li></ul>","en":"<ul><li>Plants are stunted.</li><li>Late flowering.</li><li>Poor, incomplete panicle production.</li></ul>","zh":"<ul><li>植株矮化。</li><li>抽穗开花推迟。</li><li>稻穗抽出不完全。</li></ul>"},"steps":[]}],"sci":"Rice tungro spherical virus (RTSV) &amp; Rice tungro bacilliform virus (RTBV)","kind":"virus","ai":[]},{"id":47,"crops":["JACKFRUIT"],"name":{"ms":"Reput Buah Nangka","en":"Jackfruit Fruit Rot","zh":"菠萝蜜果腐病"},"desc":{"ms":"<ul><li><p>Reput Buah nangka disebabkan oleh jangkitan kulat.</p></li><li><p>Amalkan Amalan Pertanian yang Baik (APB):</p><ul><li><p>Lakukan pemangkasan untuk meningkatkan pengudaraan di dalam kanopi pokok.</p></li><li><p>Musnahkan semua buah yang dijangkiti, sama ada di pokok atau yang jatuh ke tanah &mdash; bakar atau tanam dalam tanah.</p></li><li><p>Bersihkan kawasan ladang dari rumpai, semak, dan daun gugur.</p></li><li><p>Elakkan mencederakan buah semasa aktiviti ladang.</p></li><li><p>Pastikan buah tidak bersentuhan dengan tanah atau ditindih.</p></li><li><p>Elakkan menyimpan buah di tempat panas dan kurang pengudaraan.</p></li></ul></li><li><p>Jika berlaku serangan teruk:</p><ul><li><p>Semburkan racun kulat berasaskan kuprum pada bunga, tangkai buah, dan buah setiap 7&ndash;10 hari.</p></li></ul></li></ul>","en":"<ul><li><p>Jackfruit Fruit Rot is caused by a fungal infection.</p></li><li><p>Practise Good Agricultural Practices (GAP):</p><ul><li><p>Prune the trees to improve air flow inside the canopy.</p></li><li><p>Destroy all infected fruits, whether on the tree or fallen on the ground &mdash; burn them or bury them in the soil.</p></li><li><p>Clear the farm of weeds, bushes and fallen leaves.</p></li><li><p>Avoid injuring the fruits during farm work.</p></li><li><p>Make sure fruits do not touch the soil and are not stacked on top of each other.</p></li><li><p>Avoid storing fruits in hot, poorly ventilated places.</p></li></ul></li><li><p>If the attack is severe:</p><ul><li><p>Spray a copper-based fungicide on the flowers, fruit stalks and fruits every 7&ndash;10 days.</p></li></ul></li></ul>","zh":"<ul><li><p>菠萝蜜果腐病由真菌感染引起。</p></li><li><p>坚持良好农业规范（APB/GAP）：</p><ul><li><p>进行修剪，改善树冠内的通风。</p></li><li><p>销毁所有受感染的果实，不论是挂在树上的还是掉落地面的——烧毁或埋入土中。</p></li><li><p>清除园内的杂草、灌木和落叶。</p></li><li><p>在园间作业时避免弄伤果实。</p></li><li><p>确保果实不接触土壤，也不互相堆压。</p></li><li><p>避免把果实存放在炎热、通风不良的地方。</p></li></ul></li><li><p>如果侵染严重：</p><ul><li><p>每7–10天在花、果柄和果实上喷施铜基杀菌剂。</p></li></ul></li></ul>"},"symptoms":[{"part":"FR","img":"WhatsApp_Image_2025-07-11_at_15_24_39_2.jpg","text":{"ms":"<p>Boleh menyerang ranting, tangkai, buah, bunga, putik dan buah.</p><ul><li>Empulur kelihatan reput kehitaman bermula dari bahagian tangkai sehingga keseluruhannya.</li><li>Isi buah, jerami, kulit dan selaput biji kelihatan perang seperti karat dan reput kehitaman. </li><li>Bunga menjadi reput dan diselaputi miselium hitam.</li></ul>","en":"<p>Can attack twigs, stalks, flowers, young fruit (fruitlets) and fruit.</p><ul><li>The core (pith) rots and turns blackish, starting from the stalk and spreading through the whole fruit.</li><li>The fruit flesh, rags (fibrous strands), skin and seed coat turn rusty brown and rot black.</li><li>Flowers rot and become covered with black fungal growth (mycelium).</li></ul>","zh":"<p>可危害枝条、果柄、花、幼果和果实。</p><ul><li>果心（果轴）从果柄部位开始腐烂发黑，并蔓延到整个果实。</li><li>果肉、果丝（纤维状部分）、果皮和种皮变成锈褐色，并腐烂发黑。</li><li>花朵腐烂，并被黑色的菌丝体覆盖。</li></ul>"},"steps":[]}],"sci":"<em>Rhizopus</em> sp.","kind":"fungus","ai":["Copper"]},{"id":71,"crops":["CITRUS"],"name":{"ms":"Penyakit Greening Sitrus","en":"Citrus Greening Disease","zh":"柑橘黄龙病"},"desc":{"ms":"Bakteria ini menyebabkan Penyakit &#39;Citrus Greening&#39; pada limau manis. Ini adalah penyakit tanaman sitrus yang paling serius di dunia. Penyakit ini adalah penyakit yang sangat merbahaya kerana belum ada cara kawalan yang berkesan. Penyakit ini disebarkan oleh serangga yang dijangkiti penyakit. Bakteria &#39;Citrus Greening&#39; dan &#39;psyllid&#39; sitrus Asia merebak pada tanaman sitrus dan bahan tanaman sitrus yang dijangkiti. Tumbuhan dan bahan dapat menyebarkan jangkitan walaupun tidak ada &#39;psyllid&#39; yang kelihatan. Buah sitrus komersial, yang biasanya digred, dicuci, disikat dan dibersihkan tidak menyebarkan penyakit ini. Untuk mengelakkan ini berlaku, langkah-langkah kawalan jangka panjang dapat dilakukan dengan menggunakan bahan penanaman yang bebas dari penyakit dan pastikan perumah kedua untuk patogen seperti limau nipis, pokok daun kari dan limau purut tidak ada di sekitarnya. Musnahkan semua tanaman yang dijangkiti dan cantas semua dahan-dahan yang berpenyakit. Tebang dan bakar semua pokok yang telah disahkan terkena penyakit ini. Kawal lelompat (<em>Diaphorina citri</em>) dengan menyemburkan racun perosak seperti imidachloprid dan diafenthiuron.","en":"This bacterium causes Citrus Greening disease in sweet oranges. It is the most serious disease of citrus crops in the world. It is a very dangerous disease because there is no effective control yet. The disease is spread by infected insects. The Citrus Greening bacterium and the Asian citrus psyllid spread through infected citrus plants and citrus planting material. Plants and planting material can spread the infection even when no psyllids are visible. Commercial citrus fruit, which is normally graded, washed, brushed and cleaned, does not spread this disease. To prevent infection, long-term control measures include using disease-free planting material and making sure that alternative hosts of the pathogen, such as key lime (limau nipis), curry leaf plants and kaffir lime (limau purut), are not present in the surrounding area. Destroy all infected plants and prune all diseased branches. Cut down and burn all trees confirmed to have this disease. Control the psyllid (<em>Diaphorina citri</em>) by spraying pesticides such as imidacloprid and diafenthiuron.","zh":"这种细菌在甜橙上引起柑橘黄龙病（Citrus Greening）。这是世界上最严重的柑橘病害。此病非常危险，因为目前还没有有效的防治方法。病害由带菌的昆虫传播。黄龙病菌和亚洲柑橘木虱会随受感染的柑橘植株和柑橘种植材料传播。即使看不到木虱，植株和种植材料也能传播病害。商业柑橘果实通常经过分级、清洗、刷洗和清洁，不会传播此病。为防止发生，可采取长期防治措施：使用无病的种植材料，并确保周围没有病原菌的其他寄主，例如青柠（limau nipis）、咖喱叶树和泰国青柠（limau purut）。销毁所有受感染的植株，并剪除所有患病枝条。经确认染病的果树应全部砍伐并烧毁。喷洒吡虫啉 imidacloprid 和丁醚脲 diafenthiuron 等农药，防治柑橘木虱（<em>Diaphorina citri</em>）。"},"symptoms":[{"part":"FR","img":"buahcgggg.jpg","text":{"ms":"Buah menjadi semakin kecil, keras dan tidak sekata.","en":"Fruit becomes smaller, hard and lopsided.","zh":"果实变小、变硬且形状不对称（歪果）。"},"steps":[{"img":"diagcgbuah.jpg","text":{"ms":"Buah limau akan menjadi kecil, pahit dan keras serta tidak sekata (<em>lopsided</em>).","en":"The citrus fruit becomes small, bitter, hard and uneven in shape (<em>lopsided</em>).","zh":"柑橘果实变小、味苦、变硬，形状不对称（<em>lopsided</em>，歪果）。"}}]},{"part":"PLANT","img":"dbcg.jpg","text":{"ms":"Pokok akan mati rosot.","en":"The tree will die back.","zh":"果树会逐渐枯死（枯梢）。"},"steps":[{"img":"digtree.jpg","text":{"ms":"Pucuk pokok akan menjadi kekuningan, pokok akan terbantut dan perlahan-lahan pokok akan mati.","en":"The shoots turn yellowish, the tree becomes stunted and slowly dies.","zh":"嫩梢变黄，树体生长受阻，并慢慢枯死。"}}]},{"part":"LEAF","img":"dauncg_new.jpg","text":{"ms":"<ul><li>Kekuningan antara urat daun pada sebahagian dahan (sektorial)</li><li>Daun menjadi lebih kecil seperti inai dan tumbuh tegak.</li><li>Daun melengkung sedikit dan keras</li></ul>","en":"<ul><li>Yellowing between the leaf veins on some branches (sectorial)</li><li>Leaves become smaller, like henna leaves, and grow upright.</li><li>Leaves curl slightly and become hard</li></ul>","zh":"<ul><li>部分枝条的叶片在叶脉之间发黄（扇区性/局部发生）</li><li>叶片变小，像指甲花（凤仙）叶，并向上直立生长。</li><li>叶片稍微卷曲并变硬</li></ul>"},"steps":[{"img":"cgdiagnosedaun_jpg.jpg","text":{"ms":"Daun akan menjadi hujau kekuningan, kelihatan tebal, kaku dan bersaiz lebih kecil. Kekuningan pada daun akan kelihatan pada urat daunnya.","en":"Leaves turn yellowish-green, look thick and stiff, and are smaller. The yellowing can be seen along the leaf veins.","zh":"叶片变成黄绿色，看起来厚而僵硬，并且变小。叶脉上可看到发黄。"}}]}],"sci":"<em>Candidatus</em> Liberibacter asiaticus","kind":"bacteria","ai":["Diafenthiuron","Imidacloprid"]},{"id":79,"crops":["PAPAYA"],"name":{"ms":"Mati Rosot Betik","en":"Papaya Dieback","zh":"木瓜细菌性顶枯病"},"desc":{"ms":"Bakteria ini menyebabkan penyakit Mati Rosot pada betik. Semua kultivar komersial terdedah dan amalan pengurusan oleh petani belum terbukti berjaya dalam menguruskan penyakit ini. Bakteria biasanya memasuki inang melalui luka dan melewati tangkai ke batang hijau. Segmen tangkai daun yang melekat pada lamina akan menyebabkan pengeringan dan busuk. Untuk mengelakkan perkara ini terjadi, sebelum jangkitan berlaku atau di kawasan tanpa jangkitan, pengesanan awal gejala penyakit dari masa ke masa. Pengurusan tanaman yang betul seperti pembajaan dan penuaian. Sentiasa lakukan kebersihan di padang seperti merumput untuk memusnahkan tuan rumah sekunder. Kawal perosak di ladang dan cegah jangkitan dan penyebaran penyakit dari ladang lain dengan mengawal pergerakan manusia dan kenderaan. Sebelum menanam di ladang, gunakan bahan penanaman yang bebas penyakit. Pada peringkat semaian, lebih baik menanam anak benih di rumah kalis serangga. Gunakan biji dari buah yang diambil dari ladang bebas penyakit.","en":"This bacterium causes Papaya Dieback disease. All commercial varieties are susceptible, and the practices used by farmers have not yet been proven successful in managing this disease. The bacterium usually enters the host through wounds and passes through the leaf stalk into the green stem. The part of the leaf stalk attached to the leaf blade dries up and rots. To prevent this, before infection occurs or in areas without infection, check regularly for early signs of the disease. Manage the crop properly, including fertilising and harvesting. Always keep the field clean, for example by weeding to destroy alternative host plants. Control pests in the field, and prevent infection and spread of the disease from other farms by controlling the movement of people and vehicles. Before planting in the field, use disease-free planting material. At the nursery stage, it is better to raise seedlings in an insect-proof house. Use seeds from fruits taken from disease-free farms.","zh":"这种细菌会引起木瓜顶枯病。所有商业品种都容易感染，农民目前采用的管理方法尚未被证明能有效控制此病。细菌通常从伤口侵入寄主，经叶柄进入绿色茎干。叶柄与叶片相连的部分会干枯并腐烂。为防止这种情况，在感染发生之前或在未受感染的地区，应定期检查以及早发现病害症状。妥善管理作物，例如施肥和采收。经常保持田间清洁，例如除草以消灭其他寄主植物。控制田间害虫，并通过管制人员和车辆的进出，防止病害从其他农场传入和扩散。下田种植前，使用无病种苗。在育苗阶段，最好在防虫网室内培育幼苗。使用从无病农场采摘的果实的种子。"},"symptoms":[{"part":"FR","img":"buahdiebacknew.jpg","text":{"ms":"Isi buah juga menjadi melecur dan terdapat tompok-tompok hitam pada kulit.","en":"The fruit flesh becomes water-soaked and there are black patches on the skin.","zh":"果肉呈水渍状，果皮上有黑色斑块。"},"steps":[{"img":"buahdiebacknew_Czwda9G.jpg","text":{"ms":"Terdapat tompok-tompok hitam pada buah muda bermula dengan satu bintik perang kehitaman kecil yang kemudiannya membesar dan merebak. Terdapat kesan melecur pada isi buah betik apabila dibelah.","en":"Black patches appear on young fruit, starting as a small blackish-brown spot that later enlarges and spreads. The flesh of the papaya looks water-soaked when the fruit is cut open.","zh":"幼果上出现黑色斑块，起初是一个小的黑褐色斑点，之后逐渐扩大并蔓延。切开木瓜时，果肉呈水渍状。"}}]},{"part":"PLANT","img":"newpapayapokokdieback.jpg","text":{"ms":"Pucuk akan menjadi seperti melecur dan nekrotik kehitaman pada bahagian antara pucuk dan pelepah. Pucuk kemudian akan terkulai dan mati.","en":"The shoot becomes water-soaked with blackish necrosis (dead tissue) between the shoot and the leaf stalks. The shoot then droops and dies.","zh":"嫩梢与叶柄之间的部位出现水渍状及黑色坏死（组织死亡）。嫩梢随后下垂并死亡。"},"steps":[{"img":"newpapayapokokdieback.jpg","text":{"ms":"Kesan seperti <em>watersoaked </em>dan nekrotik yang berwarna kehitaman antara pucuk dan pelepah. Pucuk akan kelihatan terkulai dan pokok akan mati.","en":"Water-soaked and blackish necrotic symptoms between the shoot and the leaf stalks. The shoot droops and the tree dies.","zh":"嫩梢与叶柄之间出现水渍状和黑色坏死症状。嫩梢下垂，植株死亡。"}}]},{"part":"LEAF","img":"daunpapayadiebacknew.jpg","text":{"ms":"Tepi daun menjadi nekrotik, layu dan kering. <em>Lesion</em> pada bahagian atas dan bawah daun dan terdapat bintik-bintik pada daun.","en":"Leaf edges become necrotic, wilted and dry. Lesions appear on the upper and lower leaf surfaces, and there are spots on the leaves.","zh":"叶缘坏死、萎蔫并干枯。叶片正面和背面都出现病斑，叶上有斑点。"},"steps":[{"img":"daunpapayadiebacknew_4e6QHKG.jpg","text":{"ms":"Keadaan tepi daun yang layu dan kering. <em>Lesion</em> pada bahagian atas dan bawah daun dan terdapat bintik-bintik pada daun dan berwarna kehitaman.","en":"Leaf edges are wilted and dry. Lesions appear on the upper and lower leaf surfaces, and there are blackish spots on the leaves.","zh":"叶缘萎蔫干枯。叶片正面和背面都出现病斑，叶上有黑色斑点。"}}]},{"part":"STEM","img":"batangpapayadiebacknew.jpg","text":{"ms":"Batang dan pelepah daun menunjukkan simptom melecur. Pelepah juga menjadi nekrotik kehitaman dan terkulai.","en":"The stem and leaf stalks show water-soaked symptoms. The leaf stalks also become blackish, necrotic and droop.","zh":"茎干和叶柄出现水渍状症状。叶柄也会变黑、坏死并下垂。"},"steps":[{"img":"batangpapayadiebacknew_DcRb4h9.jpg","text":{"ms":"Batang dan pelepah daun menunjukkan simptom <em>watersoaked</em>, nekrotik kehitaman dan pelepah terkulai.","en":"The stem and leaf stalks show water-soaked symptoms and blackish necrosis, and the leaf stalks droop.","zh":"茎干和叶柄出现水渍状和黑色坏死症状，叶柄下垂。"}}]}],"sci":"<em>Erwinia papayae</em>","kind":"bacteria","ai":[]},{"id":90,"crops":["KOPI"],"name":{"ms":"Karat Daun Kopi","en":"Coffee Leaf Rust","zh":"咖啡锈病"},"desc":{"ms":"<p>Penyakit Karat Daun Kopi merupakan penyakit kulat yang serius pada tanaman kopi dan disebabkan oleh kulat <em>Hemileia vastatrix</em>. Penyakit ini menyerang terutamanya daun kopi, sekali gus mengurangkan keupayaan pokok untuk menjalankan fotosintesis dan menghasilkan buah yang berkualiti. Daun yang dijangkiti menunjukkan tompok-tompok kuning pada permukaan atas daun dan serbuk berwarna jingga hingga oren pada bahagian bawah daun. Serangan yang teruk boleh menyebabkan daun gugur pramatang, pokok menjadi lemah, pengurangan hasil, serta penurunan kualiti biji kopi. Penyakit ini mudah merebak melalui angin, percikan air hujan, dan bahan tanaman yang dijangkiti, terutama pada cuaca panas dan lembap.</p><p><strong>Pengurusan Penyakit Tanaman:</strong></p><ul><li>Pangkas dahan dan daun yang dijangkiti untuk mengurangkan sumber inokulum.</li><li>Pastikan pengudaraan yang baik dengan mengekalkan jarak tanaman yang sesuai.</li><li>Kutip dan musnahkan daun yang gugur serta dijangkiti.</li><li>Laksanakan pembajaan yang seimbang untuk meningkatkan kesihatan dan ketahanan pokok.</li><li>Kurangkan kelembapan berlebihan di ladang melalui pengurusan naungan dan saliran yang baik.</li><li>Pantau tanaman secara berkala bagi mengesan serangan awal.</li><li>Gunakan racun kulat yang sesuai seperti berasaskan kuprum atau fungisid sistemik mengikut syor dan label produk. Eg: Copper Oxychloride</li><li>Amalkan sanitasi ladang yang baik untuk mengurangkan penyebaran penyakit.</li></ul>","en":"<p>Coffee leaf rust is a serious fungal disease of coffee caused by the fungus <em>Hemileia vastatrix</em>. The disease mainly attacks coffee leaves, reducing the tree's ability to photosynthesise and to produce good-quality berries. Infected leaves show yellow spots on the upper surface and yellow-orange to orange powder on the underside. Severe attacks can cause early leaf drop, weak trees, lower yields and poorer coffee bean quality. The disease spreads easily through wind, rain splash and infected planting material, especially in hot and humid weather.</p><p><strong>Crop Disease Management:</strong></p><ul><li>Prune infected branches and leaves to reduce the source of inoculum.</li><li>Ensure good air flow by keeping suitable planting distances.</li><li>Collect and destroy fallen and infected leaves.</li><li>Apply balanced fertiliser to improve tree health and resistance.</li><li>Reduce excess humidity in the field through good shade and drainage management.</li><li>Check the crop regularly to detect attacks early.</li><li>Use suitable fungicides, such as copper-based or systemic fungicides, according to the recommendations and the product label. E.g. Copper Oxychloride</li><li>Practise good field sanitation to reduce the spread of the disease.</li></ul>","zh":"<p>咖啡锈病是咖啡的一种严重真菌病害，由真菌 <em>Hemileia vastatrix</em>（咖啡驼孢锈菌）引起。此病主要侵害咖啡叶片，降低植株进行光合作用和结出优质果实的能力。受感染的叶片正面出现黄色斑点，叶背出现橙黄色至橙色的粉状物。严重侵害会导致叶片提早脱落、植株衰弱、产量下降以及咖啡豆品质降低。此病很容易通过风、雨水飞溅和受感染的种植材料传播，尤其是在炎热潮湿的天气。</p><p><strong>作物病害管理：</strong></p><ul><li>修剪受感染的枝条和叶片，以减少病菌来源。</li><li>保持适当的种植距离，确保通风良好。</li><li>收集并销毁掉落及受感染的叶片。</li><li>均衡施肥，以增强植株的健康和抵抗力。</li><li>通过良好的遮荫和排水管理，减少园内过多的湿气。</li><li>定期检查作物，以便及早发现病害。</li><li>根据建议和产品标签使用合适的杀菌剂，例如铜基杀菌剂或内吸性杀菌剂。例如：Copper Oxychloride（氧氯化铜）</li><li>保持园地清洁卫生，以减少病害传播。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Coffee_Rust_DOA_Sabah.jpg","text":{"ms":"<ul><li>Pada permulaannya, kelihatan bintik kecil berwarna kuning pudar di atas permukaan daun.</li><li>Bintik ini bertukar menjadi jingga kemudiannya bertukar keperangan.</li><li>Keadaan serangan teruk menyebabkan daun gugur dan pokok mati rosot.</li></ul>","en":"<ul><li>At first, small pale yellow spots appear on the leaf surface.</li><li>These spots turn orange and later turn brown.</li><li>Severe attacks cause leaves to fall and the tree to die back.</li></ul>","zh":"<ul><li>起初，叶面上出现细小的淡黄色斑点。</li><li>这些斑点会变成橙色，之后再变成褐色。</li><li>严重侵害会导致叶片脱落，植株枯萎衰退。</li></ul>"},"steps":[]}],"sci":"<em>Hemileia vastatrix</em> Berk. &amp; Broome","kind":"fungus","ai":["Copper"]},{"id":92,"crops":["KOPI"],"name":{"ms":"Bintik Daun Kopi","en":"Coffee Brown Eye Spot","zh":"咖啡褐眼斑病"},"desc":{"ms":"<p>Bintik Daun Kopi ialah penyakit kulat pada tanaman kopi yang disebabkan oleh spesies <em>Cercospora</em>. Penyakit ini menyerang daun kopi dan menghasilkan tompok-tompok kecil berwarna coklat berbentuk bulat atau tidak sekata, sering kali dengan bahagian tengah yang lebih cerah atau kelabu, menyerupai &ldquo;mata&rdquo;. Apabila serangan menjadi teruk, daun akan menjadi kuning, kering, dan gugur lebih awal. Ini mengurangkan keupayaan fotosintesis pokok, melemahkan tanaman, serta boleh menyebabkan penurunan hasil dan kualiti biji kopi. Penyakit ini biasanya lebih mudah merebak dalam keadaan kelembapan tinggi, pengudaraan yang kurang baik, dan kawasan tanaman yang terlalu teduh.</p><p><strong>Kawalan Penyakit Tanaman:</strong></p><ul><li>Pangkas dahan dan daun yang terlalu rimbun untuk meningkatkan pengudaraan.</li><li>Keluarkan dan musnahkan daun yang dijangkiti bagi mengurangkan sumber inokulum.</li><li>Amalkan jarak tanaman yang sesuai untuk mengurangkan kelembapan berlebihan.</li><li>Kawal naungan agar tidak terlalu teduh di kawasan tanaman.</li><li>Laksanakan pembajaan seimbang untuk meningkatkan kesihatan pokok.</li><li>Elakkan kelembapan berlebihan dengan sistem saliran ladang yang baik.</li><li>Gunakan racun kulat yang sesuai (contohnya berasaskan kuprum atau fungisid sistemik) mengikut syor label. eg. Copper hydroxide</li><li>Pantau tanaman secara berkala untuk pengesanan awal serangan.</li></ul></p>","en":"<p>Coffee leaf spot is a fungal disease of coffee caused by <em>Cercospora</em> species. It attacks coffee leaves and produces small, round or irregular brown spots, often with a lighter or grey centre that looks like an &ldquo;eye&rdquo;. When the attack becomes severe, the leaves turn yellow, dry up and fall early. This reduces the tree's ability to photosynthesise, weakens the plant, and can lower the yield and quality of coffee beans. The disease usually spreads more easily in high humidity, poor air flow and plantings that are too shaded.</p><p><strong>Crop Disease Control:</strong></p><ul><li>Prune branches and leaves that are too dense to improve air flow.</li><li>Remove and destroy infected leaves to reduce the source of inoculum.</li><li>Use suitable plant spacing to reduce excess humidity.</li><li>Control shade so the planting area is not too shaded.</li><li>Apply balanced fertiliser to improve tree health.</li><li>Avoid excess moisture with a good farm drainage system.</li><li>Use a suitable fungicide (for example copper-based or systemic fungicides) according to the label recommendation, e.g. Copper hydroxide.</li><li>Monitor the crop regularly for early detection of attack.</li></ul>","zh":"<p>咖啡叶斑病（褐眼斑病）是由 <em>Cercospora</em>（尾孢菌）引起的咖啡真菌病害。它侵害咖啡叶片，形成圆形或不规则的褐色小斑点，斑点中央往往较浅或呈灰色，看起来像“眼睛”。病害严重时，叶片会变黄、干枯并提早脱落。这会降低植株的光合作用能力，使植株衰弱，并可能导致咖啡豆产量和品质下降。在高湿度、通风不良及过度遮荫的种植区，此病通常更容易蔓延。</p><p><strong>作物病害防治：</strong></p><ul><li>修剪过于茂密的枝叶，以改善通风。</li><li>清除并销毁受感染的叶片，以减少病原菌来源。</li><li>采用适当的种植距离，以减少过高的湿度。</li><li>控制遮荫，避免种植区过于阴暗。</li><li>均衡施肥，增强植株健康。</li><li>做好农场排水系统，避免湿气过多。</li><li>按照标签建议使用适当的杀菌剂（例如铜基或内吸性杀菌剂），如氢氧化铜 Copper hydroxide。</li><li>定期巡查作物，以便及早发现病害。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Fungus_DOA_Sabah.jpg","text":{"ms":"<ul><li>Terdapat bintik perang pada daun dan akan membesar dengan margin berwarna perang kemerahan.</li><li>Bintik ini kelihatan pada atas dan bahagian bawah daun.</li><li>Apabila terdapat banyak bintik pada daun, daun kelihatan seperti terbakar.</li></ul>","en":"<ul><li>Brown spots appear on the leaves and grow larger with a reddish-brown margin.</li><li>These spots can be seen on both the upper and lower sides of the leaf.</li><li>When there are many spots, the leaf looks as if it has been burnt.</li></ul>","zh":"<ul><li>叶片上出现褐色斑点，斑点会扩大，边缘呈红褐色。</li><li>叶片正面和背面都可看到这些斑点。</li><li>当叶片上斑点很多时，叶片看起来像被火烧过一样。</li></ul>"},"steps":[]}],"sci":"<em>Cercospora</em> sp.","kind":"fungus","ai":["Copper"]},{"id":97,"crops":["PADDY"],"name":{"ms":"Penyakit Hawar Bulir Bakteria","en":"Bacterial Panicle Blight","zh":"水稻细菌性穗枯病"},"desc":{"ms":"Penyakit ini boleh menyebabkan biji padi dan plantlet reput yang disebabkan oleh <em>Burkholderia glumae</em> iaitu penyakit bawaan benih. Walaupun<em> B. glumae</em> adalah penyebab utama penyakit ini, <em>Burkholderia gladioli</em> juga boleh menjadi punca penyakit ini. Penyakit ini berjangkit melalui benih dan juga boleh menjadi kedua-dua benih dan tanah. Titik kritikal adalah semasa peringkat kemunculan dan berbunga tanaman padi. Ia akan membiak dalam dan menyerang spikelet sebaik sahaja ia bercambah. Penyakit ini mampu menjadi punca utama kepada kehilangan hasil yang besar kepada petani. Lakukan rawatan benih dengan merendam benih dalam racun kulat berasaskan kuprum seperti yang disyorkan.","en":"This disease causes rotting of rice grains and seedlings and is caused by <em>Burkholderia glumae</em>, a seed-borne disease. Although <em>B. glumae</em> is the main cause, <em>Burkholderia gladioli</em> can also cause this disease. It spreads through seed and can be both seed-borne and soil-borne. The critical periods are the emergence and flowering stages of the rice plant. The bacteria multiply and attack the spikelets as soon as they emerge. This disease can be a major cause of heavy yield losses for farmers. Treat seed by soaking it in a copper-based fungicide as recommended.","zh":"此病会引起稻谷和秧苗腐烂，病原为种传病菌<em>Burkholderia glumae</em>（颖壳伯克霍尔德氏菌）。虽然<em>B. glumae</em>是主要病原，<em>Burkholderia gladioli</em>（唐菖蒲伯克霍尔德氏菌）也可引起此病。病害通过种子传播，也可经种子和土壤两种途径传播。关键时期是水稻出苗期和抽穗开花期。病菌在小穗抽出后便在其中繁殖并侵害小穗。此病可给农民造成严重的产量损失。请按推荐方法用铜基杀菌剂浸种处理。"},"symptoms":[{"part":"FR","img":"BPB1.jpg","text":{"ms":"Perubahan warna perang gelap di pangkal bijiran","en":"Dark brown discolouration at the base of the grain.","zh":"谷粒基部变成深褐色。"},"steps":[{"img":"BPB2.jpg","text":{"ms":"Perhatikan bijiran padi. Biji padi yang dijangkiti akan menunjukkan bahagian pangkal bijiran yang lebih gelap. Batang bulir yang dijangkiti kekal hijau dan daun pengasuh sihat dan tegak.","en":"Check the rice grains. Infected grains show a darker area at the base. The stalk of an infected panicle stays green, and the flag leaf remains healthy and upright.","zh":"检查稻谷。受感染的谷粒基部颜色较深。受害稻穗的穗梗仍保持绿色，剑叶健康挺直。"}}]}],"sci":"<em>Burkholderia glumae</em> &amp; <em>Burkholderia gladioli</em>","kind":"bacteria","ai":["Copper"]},{"id":100,"crops":["BANANA"],"name":{"ms":"Bintik Daun Cordana","en":"Cordana Leaf Spot","zh":"香蕉灰纹病"},"desc":{"ms":"Bintik daun Cordana bermula dengan bintikl perang atau perang pucat berbentuk bujur/lonjong pada permukaan daun. Bintik ini membesar dengan bahagian tengahnya mempunyai pusaran berwarna kehitaman dikelilingi warna kuning cerah. Jangkitan yang teruk pada permukaan daun akan menyebabkan kawasan hijau berkurangan dan menghalang proses fotosintesis. Kebersihan ladang adalah penting untuk mengawal penyakit ini. Daun yang dijangkiti mesti dipangkas dan dimusnahkan. Kawasan penanaman harus mempunyai saliran yang baik untuk pertumbuhan pokok yang sihat. Kawalan menggunakan racun kulat Mancozeb jika perlu sahaja dan hendaklah dibuat secara berhemah dengan mematuhi peraturan pada bekas/botol racun.","en":"Cordana leaf spot starts as brown or pale brown oval/oblong spots on the leaf surface. The spots grow larger, with a blackish ring pattern in the centre surrounded by bright yellow. Severe infection of the leaf surface reduces the green area and blocks photosynthesis. Farm cleanliness is important to control this disease. Infected leaves must be cut off and destroyed. The planting area should have good drainage for healthy plant growth. Use the fungicide Mancozeb only when necessary, and use it carefully by following the instructions on the pesticide container/bottle.","zh":"灰纹病（Cordana叶斑病）初期在叶面出现褐色或淡褐色的椭圆形/长圆形斑点。病斑逐渐扩大，中央有黑色轮纹，外围有鲜黄色晕圈。叶面严重感染会减少绿色面积，妨碍光合作用。保持园地清洁对防治此病很重要。受感染的叶片必须剪除并销毁。种植区应排水良好，使植株健康生长。仅在必要时才使用杀菌剂代森锰锌 Mancozeb，并须谨慎使用，遵守农药容器/瓶子上的使用规定。"},"symptoms":[{"part":"LEAF","img":"Penyakit_Pisang_Bintik_Daun_Cordana_New_PnG.jpg","text":{"ms":"Penyakit ini menyebabkan bintik kuning atau perang pucat berbentuk bujur/lonjong pada permukaan daun.","en":"This disease causes yellow or pale brown oval/oblong spots on the leaf surface.","zh":"此病使叶面出现黄色或淡褐色的椭圆形/长圆形斑点。"},"steps":[]}],"sci":"<em>Cordana musae</em>","kind":"fungus","ai":["Mancozeb"]},{"id":102,"crops":["BANANA"],"name":{"ms":"Sigatoka Kuning","en":"Yellow Sigatoka","zh":"香蕉黄叶斑病"},"desc":{"ms":"Sigatoka Kuning merupakan penyakit yang biasa untuk tanaman pisang. Penyakit ini menjejaskan daun dan mengurangkan proses fotosintesis dan seterusnya saiz tandan.","en":"Yellow Sigatoka is a common disease of banana. It affects the leaves, reducing photosynthesis and, as a result, the size of the bunch.","zh":"黄叶斑病（Yellow Sigatoka）是香蕉的常见病害。此病危害叶片，降低光合作用，从而使果穗变小。"},"symptoms":[{"part":"LEAF","img":"Penyakit_Pisang_-_Sigatoka_Kuning_New.jpg","text":{"ms":"Penyakit bintik daun Sigatoka Kuning","en":"Yellow Sigatoka leaf spot disease","zh":"香蕉黄叶斑病（Sigatoka）叶斑症状"},"steps":[]}],"sci":"<em>Mycosphaerella musicola</em>","kind":"fungus","ai":[]},{"id":104,"crops":["PADDY"],"name":{"ms":"Ulat Pengorek Batang Padi","en":"Rice Stem Borer","zh":"水稻螟虫（三化螟、二化螟）"},"desc":{"ms":"<p>Serangga ini ialah Pengorek Batang Kepala Hitam ia adalah jenis kupu-kupu yang tergolong dalam famili Crambidae. Edward Meyrick (1932) menyatakan bahawa spesis ini terdapat di India, Malaysia, Thailand, Laos, Vietnam dan Indonesia. Lebar sayap kupu-kupu ini adalah 16-25mm, berwarna kuning dan coklat dengan tompok-tompok kecil yang gelap. Larva ulat pengorek batang menyerang bahagian batang padi dengan mengorek masuk ke dalam batang. Serangan pada peringkat vegetatif menyebabkan simptom &ldquo;mati pucuk&rdquo; manakala pada peringkat pengisian biji menyebabkan simptom &ldquo;white head&rdquo; iaitu tangkai padi kosong dan berwarna putih.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Gunakan varieti padi yang tahan serangan jika tersedia.</li><li>Musnahkan tunggul dan sisa tanaman selepas menuai.</li><li>Laksanakan penanaman serentak bagi mengurangkan sumber makanan perosak.</li><li>Pasang perangkap feromon untuk pemantauan populasi rama-rama dewasa.</li><li>Galakkan musuh semula jadi seperti parasitoid telur dan labah-labah.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga seperti chlorantraniliprole, fipronil atau cartap hydrochloride berdasarkan dos yang disyorkan.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>This insect is the yellow stem borer, a moth belonging to the family Crambidae. Edward Meyrick (1932) recorded this species in India, Malaysia, Thailand, Laos, Vietnam and Indonesia. The wingspan of this moth is 16-25mm, and it is yellow and brown with small dark spots. The stem borer caterpillars attack the rice stem by boring into it. Attack at the vegetative stage causes the “dead heart” symptom, while attack at the grain-filling stage causes the “white head” symptom, where the panicle is empty and white.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Use resistant rice varieties if available.</li><li>Destroy stubble and crop residues after harvest.</li><li>Practise synchronised planting to reduce the pest's food sources.</li><li>Set up pheromone traps to monitor adult moth populations.</li><li>Encourage natural enemies such as egg parasitoids and spiders.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray insecticides such as chlorantraniliprole, fipronil or cartap hydrochloride at the recommended dose.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>这种昆虫是水稻螟虫，属于草螟科（Crambidae）的蛾类。Edward Meyrick（1932）记录此物种分布于印度、马来西亚、泰国、老挝、越南和印度尼西亚。成虫翅展 16-25mm，呈黄色和褐色，带有小的暗色斑点。螟虫幼虫钻入稻茎内部进行危害。在营养生长期受害会出现“枯心”症状，而在灌浆期受害则出现“白穗”症状，即稻穗空瘪并呈白色。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>如有抗虫水稻品种，应加以使用。</li><li>收割后销毁稻桩和作物残体。</li><li>实行同期种植，以减少害虫的食物来源。</li><li>设置性信息素诱捕器，监测成虫（蛾）的数量。</li><li>保护和利用天敌，例如卵寄生蜂和蜘蛛。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按推荐剂量喷施杀虫剂，例如 chlorantraniliprole（氯虫苯甲酰胺）、fipronil（氟虫腈）或 cartap hydrochloride（杀螟丹）。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括推荐剂量、合适的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"FR","img":"Stemborer_symptom_DOA_Sabah.jpg","text":{"ms":"Serangan pengorek batang menyebabkan tangkai padi menjadi putih dan hampa sehingga membentuk gejala &ldquo;white head&rdquo; atau &ldquo;bulu ayam&rdquo; akibat gangguan terhadap aliran nutrien dalam pokok padi.","en":"Stem borer attack causes the rice panicles to turn white and empty, producing the “white head” or “chicken feather” symptom, because the flow of nutrients in the rice plant is disrupted.","zh":"螟虫危害会使稻穗变白、空瘪，形成“白穗”（又称“鸡毛穗”）症状，这是因为稻株体内的养分输送受到破坏。"},"steps":[]},{"part":"PEST","img":"Pengorek_batang_DOA_Sabah.jpg","text":{"ms":"Dewasa Pengorek batang <em>Scirpophaga incertulas</em> /<em>Chilo </em>spp<em>.</em>","en":"Adult stem borer <em>Scirpophaga incertulas</em> / <em>Chilo</em> spp.","zh":"螟虫成虫 <em>Scirpophaga incertulas</em> / <em>Chilo</em> spp."},"steps":[]},{"part":"STEM","img":null,"text":{"ms":"<p><strong>Simptom serangan Pengorek batang padi</strong></p><ul><li>Batang padi menjadi lemah dan mudah tercabut.</li><li>Batang padi bertukar kekuningan dan layu.</li><li>Terdapat lubang gerekan pada batang padi.</li><li>Serangan teruk menyebabkan batang padi mati.</li></ul>","en":"<p><strong>Symptoms of rice stem borer attack</strong></p><ul><li>Rice stems become weak and are easily pulled out.</li><li>Rice stems turn yellowish and wilt.</li><li>There are bore holes in the rice stems.</li><li>Severe attack causes the rice stems to die.</li></ul>","zh":"<p><strong>水稻螟虫危害症状</strong></p><ul><li>稻茎变得软弱，容易被拔起。</li><li>稻茎变黄并枯萎。</li><li>稻茎上有蛀孔。</li><li>严重危害会导致稻茎死亡。</li></ul>"},"steps":[{"img":null,"text":{"ms":"Dapat dilihat pada batang yang telah diserang akan berubah warna daripada hijau ke kekuning kuningan.","en":"Attacked stems can be seen changing colour from green to yellowish.","zh":"可以看到受害的稻茎由绿色变为淡黄色。"}}]}],"sci":"<em>Scirpophaga incertulas</em> / <em>Chilo</em> spp.","kind":"insect","ai":["Cartap hydrochloride","Chlorantraniliprole","Fipronil"]},{"id":105,"crops":["PADDY"],"name":{"ms":"Kesing","en":"Rice Ear Bug","zh":"稻缘蝽"},"desc":{"ms":"<p>Pianggang atau kesing merupakan perosak utama padi. Serangga ini bertelur pada permukaan daun secara berbaris, telur berwarna coklat gelap dan mengambil masa sekitar 7 hari untuk menetas menjadi nimfa. Serangga ini menyerang padi pada peringkat pengisian biji dengan menghisap cecair daripada biji yang sedang matang, menyebabkan biji menjadi hampa, berkualiti rendah serta mengeluarkan bau yang kurang menyenangkan.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Kawalan rumpai yang menjadi perumah seperti rumput sambau dan padi angin.</li><li>Lakukan penanaman dan penuaian serentak bagi mengurangkan populasi perosak.</li><li>Menggunakan perangkap cahaya untuk menarik dan memantau kehadiran serangga dewasa.</li><li><em>Parasitoid telur</em> <em>Gryon nixoni</em> serta pemangsa seperti labah-labah merupakan musuh semula jadi kepada kesing/pianggang.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga seperti fipronil atau lambda-cyhalothrin berdasarkan dos yang disyorkan.</li><li>Semburan racun serangga dilakukan dari peringkat berbunga dan susu.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>The rice ear bug (pianggang or kesing) is a major pest of paddy. This insect lays its eggs in rows on the leaf surface. The eggs are dark brown and take about 7 days to hatch into nymphs. The insect attacks paddy at the grain-filling stage by sucking the liquid from the ripening grains, causing the grains to become empty and of low quality, and to give off an unpleasant smell.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Control host weeds such as sambau grass and weedy rice.</li><li>Plant and harvest at the same time as neighbouring fields to reduce pest numbers.</li><li>Use light traps to attract and monitor adult insects.</li><li>The egg parasitoid <em>Gryon nixoni</em> and predators such as spiders are natural enemies of the rice ear bug (kesing/pianggang).</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray insecticides such as fipronil or lambda-cyhalothrin at the recommended dose.</li><li>Spray insecticides from the flowering stage through the milk stage.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>稻缘蝽（当地称 pianggang 或 kesing）是水稻的主要害虫。这种昆虫把卵成排产在叶面上，卵呈深褐色，约7天孵化成若虫。它在灌浆期侵害水稻，吸食正在成熟的谷粒中的汁液，导致谷粒空瘪、品质低劣，并散发难闻的气味。</p><p><strong>综合虫害管理 (IPM)</strong></p><ul><li>防除作为寄主的杂草，例如牛筋草（rumput sambau）和杂草稻。</li><li>与邻近稻田同时插秧和收割，以减少害虫数量。</li><li>使用诱虫灯吸引并监测成虫。</li><li>卵寄生蜂 <em>Gryon nixoni</em> 以及蜘蛛等捕食者是稻缘蝽（kesing/pianggang）的天敌。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按建议剂量喷洒杀虫剂，例如 fipronil（氟虫腈）或 lambda-cyhalothrin（高效氯氟氰菊酯）。</li><li>从开花期到乳熟期喷洒杀虫剂。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"PLANT","img":"Kesing_Doa_Sabah.jpg","text":{"ms":"<p><strong>Simptom serangan kesing pada padi</strong></p><ul><li>Biji padi mempunyai kesan cucukan atau lubang kecil.</li><li>Buah padi menjadi hampa dan ringan akibat cecair diisap.</li><li>Terdapat tompok perang atau hitam pada biji padi.</li><li>Kualiti dan hasil tuaian menurun akibat kerosakan biji padi</li></ul>","en":"<p><strong>Symptoms of rice ear bug attack on paddy</strong></p><ul><li>Rice grains have puncture marks or small holes.</li><li>Grains become empty and light because the liquid has been sucked out.</li><li>Brown or black spots appear on the rice grains.</li><li>Grain quality and harvest yield drop because of the damaged grains.</li></ul>","zh":"<p><strong>稻缘蝽侵害水稻的症状</strong></p><ul><li>谷粒上有刺吸痕迹或小孔。</li><li>谷粒因汁液被吸走而变得空瘪、轻飘。</li><li>谷粒上出现褐色或黑色斑点。</li><li>谷粒受损导致品质和收成下降。</li></ul>"},"steps":[]},{"part":"PEST","img":"Dewasa_kesing_Leptocorisa_oratorius_DOA_Sabah.jpg","text":{"ms":"Dewasa kesing <em>Leptocorisa oratorius</em>","en":"Adult rice ear bug <em>Leptocorisa oratorius</em>","zh":"稻缘蝽成虫 <em>Leptocorisa oratorius</em>"},"steps":[]}],"sci":"<em>Leptocorisa oratorius</em> (Fabricius)","kind":"insect","ai":["Fipronil","Lambda-cyhalothrin"]},{"id":106,"crops":["MANGO"],"name":{"ms":"Kumbang Pengerat Daun Mangga","en":"Mango Leaf-Cutting Weevil","zh":"芒果切叶象甲"},"desc":{"ms":"<p>Serangga ini dikenali sebagai kumbang pengerat daun mangga, telur ditanam pada tisu daun. <br>serangga ini akan membuat belahan pada daun dan telur akan dimasukkan kedalamnya. <br>Telur diletakkan secara tunggal (0.5mm).<br>Perkembangan selanjutnya berlaku didalam daun yang telah dipotong. <br>Daun gugur pada sesetengah tumbuhan mengelakkan daripada dehidrasi serta merta.<br>Pengeraman: Kira-kira 2 hari<br>Apabila menetas, larva mengorek lubang pada tanah, meyebabkan permukaan yang tidak rata.<br>Peringkat larva: 1 minggu (Saiz :5 mm)<br>Penyediaan pupa: larva membina sel di dalam tanah terlebih dahulu, di dalam sel membentuk pupa.<br>Peringkat pupa: 9 hari &amp; Peringkat Dewasa (5mm) <br>(Khoo et al., 1991) </p><p><strong>Kawalan</strong></p><p>Satu gabungan budaya dan kawalan kimia ialah disyorkan. Semasa menyembur sistemik racun serangga: untuk contoh 0.15% a.i. asetat penyelesaian pada daun baru, yang populasi perosak akan lebih jauh ditindas jika daun potong yang gugur dikeluarkan dan musnah.</p>","en":"<p>This insect is known as the mango leaf-cutting weevil; its eggs are embedded in the leaf tissue. <br>The insect makes a slit in the leaf and the egg is inserted into it. <br>Eggs are laid singly (0.5mm).<br>Further development takes place inside the leaf that has been cut off. <br>On some vegetation the fallen leaf is kept from drying out immediately.<br>Incubation: about 2 days<br>After hatching, the larva tunnels (mines) in the leaf on the ground, forming an irregular mine.<br>Larval stage: 1 week (size: 5 mm)<br>Before pupation: the larva first builds a cell in the soil, and forms a pupa inside the cell.<br>Pupal stage: 9 days &amp; Adult stage (5mm) <br>(Khoo et al., 1991) </p><p><strong>Control</strong></p><p>A combination of cultural and chemical control is recommended. While spraying a systemic insecticide, for example a 0.15% a.i. acephate solution on new leaves, the pest population will be suppressed further if the fallen cut leaves are collected and destroyed.</p>","zh":"<p>这种昆虫称为芒果切叶象甲，卵产在叶片组织内。<br>成虫在叶片上割开一道裂缝，然后把卵产进去。<br>卵单粒产下（0.5mm）。<br>之后的发育在被切下的叶片内进行。<br>落在某些植被上的叶片不会立即干枯。<br>孵化期：约 2 天<br>孵化后，幼虫在落地叶片中钻蛀取食，形成不规则的蛀道。<br>幼虫期：1 周（体长：5 mm）<br>化蛹准备：幼虫先在土中筑一个土室，并在土室内化蛹。<br>蛹期：9 天 &amp; 成虫期（5mm）<br>(Khoo et al., 1991) </p><p><strong>防治</strong></p><p>建议结合栽培防治与化学防治。在新叶上喷施内吸性杀虫剂（例如 0.15% a.i. 乙酰甲胺磷 acephate 溶液）的同时，若把掉落的被切叶片收集并销毁，害虫数量会被进一步压低。</p>"},"symptoms":[{"part":"LEAF","img":"Deporaus_marginatus.jpg","text":{"ms":"<p>Kumbang merosakkan daun muda dengan dua cara: </p><ol><li> Kumbang dewasa memakan daun menyebabkan dehidrasi.</li><li> Serangga betina yang matang akan memotong daun muda merangsang pertumbuhan pucuk baru yang banyak mengakibatkan pertumbuhan yang tidak kemas. Serangan serius akan memberi kesan terhadap pengeluaran buah.</li></ol>","en":"<p>The weevil damages young leaves in two ways: </p><ol><li>Adult weevils feed on the leaves, causing them to dry out.</li><li>Mature females cut off young leaves, which stimulates many new shoots to grow, resulting in untidy growth. A serious attack will affect fruit production.</li></ol>","zh":"<p>这种象甲以两种方式危害嫩叶：</p><ol><li>成虫取食叶片，导致叶片失水干枯。</li><li>成熟的雌虫会切断嫩叶，刺激大量新芽长出，使植株生长杂乱。严重危害会影响果实产量。</li></ol>"},"steps":[{"img":"Deporaus_marginatus.jpg","text":{"ms":"Kerosakan pada pucuk daun mangga oleh Pengerat daun. Daun muda dipotong dipangkal oleh kumbang betina selepas meletakkan telurnya dibahagian tulang daun. Pangkal daun akhirnya gugur meninggalkan batang yang tandus.","en":"Damage to mango shoots by the leaf-cutting weevil. Young leaves are cut at the base by the female weevil after she lays her eggs in the leaf midrib. The leaves finally fall, leaving bare stems.","zh":"芒果切叶象甲对芒果嫩梢的危害。雌虫在叶片中脉产卵后，从叶基部把嫩叶切断。叶片最终脱落，只留下光秃的枝条。"}}]}],"sci":"<em>Deporaus marginatus</em> Pascoe","kind":"insect","ai":["Acephate"]},{"id":109,"crops":["COCONUT"],"name":{"ms":"Kumbang Merah Palma","en":"Red Palm Weevil","zh":"红棕象甲"},"desc":{"ms":"<p>Dua spesies kumbang merah palma iaitu <em>Rhynchophorus vulneratus</em> - RPW rv (ada di Sabah) dan <em>Rhynchophorus ferrugineus</em> - RPW rf (tiada di Sabah) merupakan serangga perosak utama yang menyerang pelbagai spesies palma seperti kelapa, kelapa sawit, kurma dan pinang. Larva kumbang ini mengorek serta memakan tisu lembut di bahagian batang dan pucuk palma, menyebabkan kerosakan dalaman yang serius. Serangan awal sukar dikesan kerana kebanyakan aktiviti perosak berlaku di dalam batang. Pokok yang diserang biasanya menunjukkan simptom seperti pelepah layu, daun muda rosak atau patah, lubang pada batang yang mengeluarkan cecair berbau busuk, serta kehadiran sisa makanan (frass). Serangan yang teruk boleh menyebabkan pokok menjadi lemah, tumbang, dan akhirnya mati jika tidak dikawal dengan segera.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Elakkan kecederaan pada batang pokok kerana ia menarik perosak.</li><li>Musnahkan pokok yang telah dijangkiti teruk.</li><li>Gunakan perangkap feromon untuk pemantauan populasi dewasa.</li><li>Lakukan pemeriksaan berkala pada batang dan pangkal pokok.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Suntikan racun serangga seperti methamidophos ke dalam batang pokok.</li><li>Apabila menggunakan racun perosak, patuhi arahan label termasuk kadar dos, masa aplikasi dan langkah keselamatan.</li></ul></p>","en":"<p>Two species of red palm weevil, <em>Rhynchophorus vulneratus</em> - RPW rv (present in Sabah) and <em>Rhynchophorus ferrugineus</em> - RPW rf (not present in Sabah), are major insect pests that attack many palm species such as coconut, oil palm, date palm and areca palm. The larvae bore into and feed on the soft tissue of the trunk and shoot of the palm, causing serious internal damage. Early attacks are hard to detect because most of the pest's activity happens inside the trunk. Attacked palms usually show symptoms such as wilting fronds, damaged or broken young leaves, holes in the trunk that release a foul-smelling liquid, and the presence of chewed fibre waste (frass). A severe attack can make the palm weak, fall over and finally die if it is not controlled quickly.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Avoid injuring the palm trunk, as wounds attract the pest.</li><li>Destroy palms that are severely infested.</li><li>Use pheromone traps to monitor the adult population.</li><li>Inspect the trunk and base of the palm regularly.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Inject insecticides such as methamidophos into the palm trunk.</li><li>When using pesticides, follow the label instructions, including dosage rate, application timing and safety precautions.</li></ul>","zh":"<p>红棕象甲有两种：<em>Rhynchophorus vulneratus</em>（RPW rv，沙巴有分布）和<em>Rhynchophorus ferrugineus</em>（RPW rf，沙巴未发现），都是危害多种棕榈植物的主要害虫，如椰子、油棕、椰枣和槟榔。幼虫蛀入并取食棕榈树干和心部（生长点）的柔软组织，造成严重的内部损害。早期危害难以察觉，因为害虫大部分活动都在树干内进行。受害植株通常出现以下症状：叶柄（叶片）萎蔫、嫩叶受损或折断、树干上有孔洞并流出恶臭液体，以及出现蛀屑（虫粪纤维）。若不及时防治，严重危害会使植株衰弱、倒伏，最终死亡。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>避免弄伤树干，因为伤口会吸引害虫。</li><li>销毁受害严重的植株。</li><li>使用信息素诱捕器监测成虫数量。</li><li>定期检查树干和树基部。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>将杀虫剂如甲胺磷 Methamidophos 注射入树干。</li><li>使用农药时，须遵守标签说明，包括剂量、施用时间和安全措施。</li></ul>"},"symptoms":[{"part":"PLANT","img":"RPW_Doa_Sabah.jpg","text":{"ms":"Dewasa betina bertelur di bahagian yang luka atau cedera disebabkan oleh serangan kumbang badak, aktiviti manusia atau lain-lain faktor. Larva memakan pucuk sehingga menyebabkan pokok mati. Simptom tidak kelihatan pada peringkat awal serangan kerana ia hanya disedari setelah serangan pada peringkat teruk, pucuk yang diserang menjadi reput dan mudah tercabut. Pokok yang diserang kebiasaannya akan patah di bahagian crown/pucuk dan meninggalkan batang sahaja. Keseluruhan kitaran hidup kumbang RPW adalah berada di dalam pokok dan hanya akan keluar untuk mencari tempat untuk membiak setelah pokok mati.","en":"Adult females lay eggs in wounded or injured parts of the palm caused by rhinoceros beetle attack, human activity or other factors. The larvae feed on the shoot until the palm dies. There are no visible symptoms in the early stage, because the attack is only noticed once it is severe; by then the attacked shoot has rotted and is easily pulled out. Attacked palms usually break at the crown/shoot, leaving only the trunk. The whole life cycle of the red palm weevil takes place inside the palm, and the beetles only come out to look for a new place to breed after the palm dies.","zh":"雌成虫在因犀角金龟危害、人为活动或其他原因造成的伤口处产卵。幼虫取食心部，直至植株死亡。早期没有明显症状，往往到危害严重时才被发现，此时受害心部已腐烂，很容易被拔出。受害植株通常在树冠/心部折断，只剩下树干。红棕象甲的整个生活史都在树内完成，只有在树死后才会飞出寻找新的繁殖场所。"},"steps":[]},{"part":"TREE","img":"RPW_Simptom.jpg","text":{"ms":"<ul><li>Daun muda atau pelepah menjadi layu dan menguning secara beransur-ansur.</li><li>Pelepah mudah patah atau rebah akibat kerosakan dalaman pada batang dan pucuk.</li><li>Lubang pada batang atau pangkal pelepah yang menjadi tempat keluar masuk larva dan kumbang dewasa.</li></ul>","en":"<ul><li>Young leaves or fronds gradually wilt and turn yellow.</li><li>Fronds break or collapse easily because of internal damage to the trunk and shoot.</li><li>Holes in the trunk or at the base of the fronds, where larvae and adult beetles go in and out.</li></ul>","zh":"<ul><li>嫩叶或叶柄逐渐萎蔫、变黄。</li><li>由于树干和心部内部受损，叶柄容易折断或垂倒。</li><li>树干或叶柄基部有孔洞，是幼虫和成虫进出的地方。</li></ul>"},"steps":[]}],"sci":"<em>Rhynchophorus</em> spp.","kind":"insect","ai":["Methamidophos"]},{"id":110,"crops":["COCONUT"],"name":{"ms":"Kumbang Daun Kelapa","en":"Coconut Leaf Beetle","zh":"椰心叶甲"},"desc":{"ms":"<p>Kumbang daun kelapa, terutamanya spesies <em>Brontispa longissima</em>, ialah perosak utama yang memakan tisu lembut pada pucuk dan daun muda yang belum kembang. Serangan menyebabkan daun kelihatan seperti terbakar atau kering dan bertukar warna coklat, yang boleh membantutkan pertumbuhan atau mematikan pokok jika tidak dikawal.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Pangkas dan musnahkan daun atau pelepah yang terjejas teruk bagi mengurangkan sumber infestasi.</li><li>Elakkan pemindahan anak benih dari kawasan yang dijangkiti perosak.</li><li>Galakkan penggunaan musuh semula jadi seperti parasitoid <em>Asecodes hispinarum</em> yang menyerang larva kumbang.</li><li>Amalkan sanitasi ladang dengan memusnahkan pelepah mati dan sisa tanaman yang berpotensi menjadi tempat pembiakan perosak.</li><li>Lakukan pemantauan berkala terutama pada pucuk dan pelepah muda di kawasan tanaman muda.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Penggunaan racun serangga atau ubat gegat (naphthalene) yang diletakkan di celah pelepah daun untuk anak pokok.</li><li>Apabila menggunakan racun perosak, patuhi arahan label termasuk kadar dos, masa aplikasi dan langkah keselamatan.</li></ul></p>","en":"<p>The coconut leaf beetle, especially the species <em>Brontispa longissima</em>, is a major pest that feeds on the soft tissue of shoots and young unopened leaves. The attack makes the leaves look burnt or dry and turn brown, which can stunt growth or kill the palm if not controlled.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Prune and destroy badly affected leaves or fronds to reduce sources of infestation.</li><li>Avoid moving seedlings from pest-infested areas.</li><li>Encourage the use of natural enemies such as the parasitoid <em>Asecodes hispinarum</em>, which attacks the beetle larvae.</li><li>Practise farm sanitation by destroying dead fronds and crop debris that can become breeding places for the pest.</li><li>Check regularly, especially the shoots and young fronds in areas with young palms.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Use insecticides or mothballs (naphthalene) placed between the frond bases of young palms.</li><li>When using pesticides, follow the label instructions, including the dose rate, application timing and safety measures.</li></ul>","zh":"<p>椰心叶甲，特别是 <em>Brontispa longissima</em> 这一种，是一种主要害虫，取食心叶和尚未展开的嫩叶的柔软组织。受害叶片看起来像被火烧过或干枯，变成褐色；如不加以防治，会导致植株生长受阻甚至死亡。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>剪除并销毁受害严重的叶片或叶柄，减少虫源。</li><li>避免从虫害发生地区移出种苗。</li><li>鼓励利用天敌，例如寄生蜂 <em>Asecodes hispinarum</em>（椰甲截脉姬小蜂），它会寄生椰心叶甲的幼虫。</li><li>做好园地卫生，销毁可能成为害虫繁殖场所的枯叶和作物残体。</li><li>定期巡查，尤其是幼龄种植区的心叶和嫩叶。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>对幼苗可使用杀虫剂，或把樟脑丸（萘 naphthalene）放在叶柄基部的缝隙中。</li><li>使用农药时，须遵守标签说明，包括剂量、施药时间和安全措施。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Brontispa_DOA_Sabah.jpg","text":{"ms":"<p><strong>Simptom serangan </strong></p><ul><li>Daun muda bergulung dan berkedut.</li><li>Terdapat tompok-tompok perang atau jalur kering pada permukaan daun.</li><li>Daun kelihatan terbakar atau kering.</li><li>Pertumbuhan anak pokok menjadi terencat.</li><li>Pelepah muda tidak terbuka dengan sempurna.</li></ul>","en":"<p><strong>Symptoms of attack</strong></p><ul><li>Young leaves curl and wrinkle.</li><li>Brown patches or dry streaks appear on the leaf surface.</li><li>Leaves look burnt or dry.</li><li>Growth of young palms is stunted.</li><li>Young fronds do not open properly.</li></ul>","zh":"<p><strong>受害症状</strong></p><ul><li>嫩叶卷曲、起皱。</li><li>叶面出现褐色斑块或干枯条纹。</li><li>叶片看起来像被火烧过或干枯。</li><li>幼苗生长受阻。</li><li>嫩叶无法正常展开。</li></ul>"},"steps":[]}],"sci":"<em>Brontispa longissima</em> (Gestro)","kind":"insect","ai":["Naphthalene"]},{"id":112,"crops":["DURIAN"],"name":{"ms":"Pengorek Biji Durian","en":"Durian Seed Borer","zh":"榴莲种子螟"},"desc":{"ms":"<p>Sejenis perosak yang menyerang buah durian dengan mengorek dan memakan biji di dalam buah. Larva (ulat) masuk ke dalam buah dan membentuk terowong sehingga ke bahagian biji, menyebabkan kerosakan dalaman yang serius. Serangan biasanya berlaku pada buah yang sedang berkembang hingga hampir masak. Perosak ini sukar dikesan pada peringkat awal kerana kerosakan berlaku di dalam buah tanpa tanda luar yang jelas. Serangga ini merupakan sejenis kupu-kupu yang tergolong dalam famili Noctuidae dan oder Lepidoptera. Terdapat lubang serangan dan sisa buangan fras pada permukaan buah. Buah yang diserang biasanya akan busuk dan luruh.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Amalan Pertanian Baik (APB) </li><li>Kutip dan musnahkan buah yang diserang atau gugur untuk mengurangkan sumber pembiakan.</li><li>Lakukan pemantauan kebun secara berkala, terutama pada musim berbuah.</li><li>Gunakan pembungkusan buah (fruit bagging) untuk menghalang rama-rama bertelur pada buah.</li><li>Kawal rumpai dan pastikan kebun bersih untuk mengurangkan habitat perosak.</li><li>Membersihkan persekitaran ladang serta mengutip buah yang rosak dan dihapuskan bagi mengelak serangga membiak pada buah yang rosak.</li></ul><p>Kawalan Kimia (Jika Perlu)</p><ul><li>Sembur racun seperti Deltamethrin /Cypermethrin/ Dimethoate mengikut kadar yang disyorkan pada label.</li><li>Semasa menggunakan racun perosak, sentiasa memakai pakaian pelindung dan mematuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>A pest that attacks durian fruit by boring into and eating the seeds inside the fruit. The larvae (caterpillars) enter the fruit and make tunnels down to the seeds, causing serious internal damage. Attacks usually happen on fruit from the developing stage until almost ripe. The pest is hard to detect early because the damage happens inside the fruit with no clear outside signs. This insect is a moth belonging to the family Noctuidae and the order Lepidoptera. There are entry holes and frass (droppings) on the surface of the fruit. Attacked fruit usually rots and drops.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Good Agricultural Practices (GAP) </li><li>Collect and destroy attacked or fallen fruit to reduce breeding sources.</li><li>Check the orchard regularly, especially during the fruiting season.</li><li>Use fruit bagging to stop moths from laying eggs on the fruit.</li><li>Control weeds and keep the orchard clean to reduce pest habitat.</li><li>Clean the farm surroundings, and collect and destroy damaged fruit so the insects cannot breed in it.</li></ul><p>Chemical Control (If Needed)</p><ul><li>Spray an insecticide such as Deltamethrin / Cypermethrin / Dimethoate at the rate recommended on the label.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>一种危害榴莲果实的害虫，会钻蛀并取食果实内的种子。幼虫（毛虫）钻入果实，蛀出隧道直达种子，造成严重的内部损害。危害通常发生在果实发育期至接近成熟期。由于损害发生在果实内部，外表没有明显迹象，所以早期很难发现。这种昆虫是蛾类，属于夜蛾科（Noctuidae）、鳞翅目（Lepidoptera）。果实表面有蛀孔和虫粪。被害果实通常会腐烂并掉落。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>良好农业规范（APB/GAP） </li><li>收集并销毁被害果或落果，以减少害虫的繁殖来源。</li><li>定期巡查果园，尤其是在结果期。</li><li>采用果实套袋，防止蛾子在果实上产卵。</li><li>控制杂草，保持果园清洁，减少害虫的栖息地。</li><li>清理园区环境，收集并销毁受损果实，避免害虫在受损果实中繁殖。</li></ul><p>化学防治（如有需要）</p><ul><li>按标签建议用量喷洒杀虫剂，例如溴氰菊酯 Deltamethrin / 氯氰菊酯 Cypermethrin / 乐果 Dimethoate。</li><li>使用农药时，务必穿戴防护服，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及采收前的安全间隔期。</li></ul>"},"symptoms":[{"part":"FR","img":"JABATAN_PERTANIAN_SABAH_2.jpg","text":{"ms":"<ul><li>Larva mengorek kulit buah, isi dan biji.</li><li>Di permukaan buah terdapat lubang serangan yang dipenuhi oleh butiran fras yang kasar dan basah.</li><li>Fras yang basah menunjukkan adanya larva yang hidup di dalam buah, sedangkan fras yang kering pula menunjukkan larva telah membentung kepompong atau telah muncul menjadi dewasa.</li><li>Buah yang diserang biasanya jadi busuk dan luruh.</li></ul>","en":"<ul><li>The larvae bore into the fruit skin, flesh and seeds.</li><li>On the fruit surface there are entry holes filled with coarse, wet frass.</li><li>Wet frass shows that live larvae are inside the fruit, while dry frass shows that the larvae have pupated or have already emerged as adults.</li><li>Attacked fruit usually rots and drops.</li></ul>","zh":"<ul><li>幼虫蛀食果皮、果肉和种子。</li><li>果实表面有蛀孔，孔内充满粗糙、潮湿的虫粪。</li><li>虫粪潮湿表示果实内有活的幼虫；虫粪干燥则表示幼虫已化蛹或已羽化为成虫。</li><li>被害果实通常会腐烂并掉落。</li></ul>"},"steps":[]}],"sci":"<em>Mudaria magniplaga</em> Walker","kind":"insect","ai":["Cypermethrin","Deltamethrin","Dimethoate"]},{"id":117,"crops":["DURIAN"],"name":{"ms":"Kutu Psilid Durian","en":"Durian Psyllid","zh":"榴莲木虱"},"desc":{"ms":"<p>Psyllid durian (Psylidae: Hemiptera) ialah serangga perosak kecil yang menghisap sap dan terutamanya menyerang pokok durian. Kedua-dua peringkat nimfa dan dewasa memakan pucuk muda, daun, dan tunas dengan cara mencucuk tisu tumbuhan dan menghisap sap. Aktiviti pemakanan ini boleh menyebabkan daun menggulung, pertumbuhan pucuk terbantut, serta pembentukan kulapuk hitam (sooty mould) akibat rembesan honeydew.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Laksanakan pemantauan awal untuk mengesan kehadiran perosak.</li><li>Lakukan kawalan menggunakan semburan biopestisid seperti cuka kayu.</li></ul><p>Kawalan Kimia (Jika Perlu)</p><ul><li>Gunakan racun perosak yang mengandungi bahan aktif abamectin atau cypermethrin mengikut syor label.</li><li>Semasa menggunakan racun perosak, sentiasa memakai pakaian pelindung dan mematuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>The durian psyllid (Psyllidae: Hemiptera) is a small sap-sucking insect pest that mainly attacks durian trees. Both nymphs and adults feed on young shoots, leaves and buds by piercing the plant tissue and sucking the sap. This feeding can cause leaf curling, stunted shoot growth and the formation of sooty mould on the honeydew they excrete.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Monitor early to detect the presence of the pest.</li><li>Control using biopesticide sprays such as wood vinegar.</li></ul><p>Chemical Control (If Necessary)</p><ul><li>Use pesticides containing the active ingredient abamectin or cypermethrin, following the label recommendations.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>榴莲木虱（木虱科 Psyllidae：半翅目 Hemiptera）是一种体型细小、吸食汁液的害虫，主要危害榴莲树。若虫和成虫都以刺吸植物组织、吸取汁液的方式取食嫩梢、叶片和芽。这种取食会导致叶片卷曲、新梢生长受阻，以及由其分泌的蜜露引起煤烟病（黑霉）。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>及早进行监测，以发现害虫的出现。</li><li>使用生物农药喷施防治，例如木醋液。</li></ul><p>化学防治（如有需要）</p><ul><li>按照标签建议，使用含有 abamectin（阿维菌素）或 cypermethrin（氯氰菊酯）有效成分的农药。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括推荐剂量、合适的施药时间，以及收获前的安全间隔期。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Psilid_pada_daun_muda_durian.jpg","text":{"ms":"<ul><li>Psyllid menyerang pucuk terutama daun muda ketika pengeluaran pucuk.</li><li>Larva dan dewasa menghisap cecair daun.</li><li>Populasi tinggi menyebabkan serangan teruk- daun menjadi kerinting, kering dan gugur.</li></ul>","en":"<ul><li>Psyllids attack the shoots, especially young leaves during flushing.</li><li>Nymphs and adults suck the sap from the leaves.</li><li>High populations cause severe damage: leaves become curled, dry and fall off.</li></ul>","zh":"<ul><li>木虱危害嫩梢，尤其是抽梢期的嫩叶。</li><li>若虫和成虫吸食叶片汁液。</li><li>虫口密度高时危害严重：叶片卷曲、干枯并脱落。</li></ul>"},"steps":[]},{"part":"MORFOLOGI","img":"Psyllid_durian_cpEnabx.jpg","text":{"ms":"Psilid durian (<em>Allocaridara malayensis</em>)","en":"Durian psyllid (<em>Allocaridara malayensis</em>)","zh":"榴莲木虱（<em>Allocaridara malayensis</em>）"},"steps":[]}],"sci":"<em>Allocaridara malayensis</em> Crawford","kind":"insect","ai":["Abamectin","Cypermethrin","Wood vinegar"]},{"id":118,"crops":["DURIAN"],"name":{"ms":"Koya","en":"Mealybug","zh":"粉蚧"},"desc":{"ms":"<p>Serangga ini menyerang tanaman durian dengan menghisap sap daripada pucuk muda, daun, tangkai, bunga dan buah. Serangga ini diselaputi lapisan putih seperti kapas yang melindungi badannya dan sering ditemui secara berkelompok. Serangan menyebabkan pertumbuhan pokok terbantut, daun menjadi kuning, layu dan gugur. Pada buah, serangan boleh mengurangkan saiz, menjejaskan kualiti dan menyebabkan buah gugur pramatang. Madu yang dirembeskan juga menggalakkan pertumbuhan kulapuk jelaga (sooty mould), yang menutupi permukaan daun dan buah lalu mengurangkan kadar fotosintesis.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Amalan Pertanian Baik (APB) </li><li>Pantau kebun secara berkala, terutamanya pada pucuk muda, bunga dan buah, bagi mengesan serangan pada peringkat awal.</li><li>Pangkas dan musnahkan bahagian pokok yang diserang dengan teruk untuk mengurangkan sumber infestasi.</li><li>Kawal populasi semut kerana semut melindungi koya daripada musuh semula jadi dan membantu penyebarannya.</li><li>Galakkan pemeliharaan musuh semula jadi seperti kumbang kura-kura (ladybird beetles), lacewings dan tebuan parasitoid yang membantu mengawal populasi koya.</li><li>Elakkan penggunaan baja nitrogen secara berlebihan kerana pertumbuhan pucuk yang terlalu subur menggalakkan serangan koya</li><li>Bersihkan persekitaran ladang serta kutip dan hapuskan buah yang rosak</li></ul><p>Kawalan Kimia (Jika Perlu)</p><ul><li>Semburkan racun serangga seperti minyak putih, malathion atau dimethoate serta racun kulat seperti benomyl mengikut kadar yang disyorkan pada label.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>This insect attacks durian trees by sucking sap from young shoots, leaves, stalks, flowers and fruits. It is covered with a white, cotton-like layer that protects its body, and is often found in groups. The attack stunts the growth of the tree, and leaves turn yellow, wilt and fall. On fruits, the attack can reduce fruit size, lower quality and cause the fruit to drop early. The honeydew it gives off also encourages sooty mould, which covers the surface of leaves and fruits and reduces photosynthesis.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Good Agricultural Practices (GAP) </li><li>Check the orchard regularly, especially young shoots, flowers and fruits, to detect attacks early.</li><li>Prune and destroy badly attacked parts of the tree to reduce the source of infestation.</li><li>Control ants, because ants protect mealybugs from their natural enemies and help them spread.</li><li>Encourage and protect natural enemies such as ladybird beetles, lacewings and parasitoid wasps, which help control mealybug numbers.</li><li>Avoid using too much nitrogen fertiliser, because very lush shoot growth encourages mealybug attack.</li><li>Keep the farm surroundings clean, and collect and destroy damaged fruits.</li></ul><p>Chemical Control (If Necessary)</p><ul><li>Spray insecticides such as white oil, malathion or dimethoate, and fungicides such as benomyl, at the rate recommended on the label.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>这种害虫吸食榴莲嫩梢、叶片、叶柄/果柄、花和果实的汁液，从而侵害榴莲树。虫体覆盖着一层像棉花的白色蜡质保护层，常成群出现。侵害会使植株生长受阻，叶片发黄、萎蔫并脱落。在果实上，侵害会使果实变小、品质下降，并导致果实提早脱落。它分泌的蜜露还会促使煤烟病（sooty mould）滋生，覆盖叶片和果实表面，降低光合作用。</p><p><strong>综合虫害管理 (IPM)</strong></p><ul><li>良好农业规范 (APB/GAP) </li><li>定期检查果园，尤其是嫩梢、花和果实，以便及早发现虫害。</li><li>修剪并销毁受害严重的植株部位，以减少虫源。</li><li>控制蚂蚁数量，因为蚂蚁会保护粉蚧免受天敌攻击，并帮助它们传播。</li><li>保护和鼓励天敌，例如瓢虫、草蛉和寄生蜂，它们有助于控制粉蚧数量。</li><li>避免过量施用氮肥，因为嫩梢生长过于茂盛会招来粉蚧。</li><li>保持园地环境清洁，收集并销毁受损的果实。</li></ul><p>化学防治（如有需要）</p><ul><li>按标签上的建议用量喷洒杀虫剂，例如白油（矿物油）、malathion（马拉硫磷）或 dimethoate（乐果），以及杀菌剂，例如 benomyl（苯菌灵）。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"FR","img":"koya_durian_DOA_Sabah.jpg","text":{"ms":"<ul><li>Kulat kulapuk hitam akan tumbuh pada permukaan buah akibat daripada rembesan cecair manisan oleh koya.</li></ul>","en":"<ul><li>Black sooty mould grows on the fruit surface because of the sweet honeydew given off by the mealybugs.</li></ul>","zh":"<ul><li>由于粉蚧分泌甜蜜露，果实表面会长出黑色的煤烟霉。</li></ul>"},"steps":[]},{"part":"LEAF","img":null,"text":{"ms":"<ul><li>Tanda serangan koya dapat dilihat secara jelas pada permukaan daun (depan dan belakang). </li><li>Daun akan diliputi koya mengakibatkan kualiti dan keupayaan fungsi daun merosot</li></ul>","en":"<ul><li>Signs of mealybug attack can be clearly seen on the leaf surface (upper and lower sides). </li><li>Leaves become covered with mealybugs, lowering leaf quality and function.</li></ul>","zh":"<ul><li>在叶片表面（正面和背面）可以清楚看到粉蚧侵害的迹象。</li><li>叶片被粉蚧覆盖，导致叶片质量和功能下降。</li></ul>"},"steps":[]}],"sci":"<em>Planococcus pacificus</em> Cox","kind":"insect","ai":["Benomyl","Dimethoate","Malathion","White oil"]},{"id":120,"crops":["DURIAN"],"name":{"ms":"Kumbang Belangkas","en":"Gold-dust Weevil","zh":"绿鳞象甲"},"desc":{"ms":"<p>Perosak daun yang menyerang tanaman durian, terutama pada peringkat pokok muda hingga matang. Kumbang dewasa memakan permukaan daun, pucuk muda dan kadang-kadang bunga, menyebabkan kerosakan yang jelas pada kanopi pokok.Serangga ini dikenali melalui badan yang diselaputi sisik berwarna kehijauan keemasan seperti debu emas. Larvanya hidup di dalam tanah dan memakan akar, manakala dewasa menyerang bahagian atas pokok. Kumbang dewasa memakan daun dengan cara menggigit bahagian tepi, menyebabkan tepi daun menjadi tidak sekata atau bergerigi. Najis serangga (frass) sering kelihatan pada permukaan daun dan di atas tanah di sekelilingnya.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Amalan Pertanian Baik (APB) </li><li>Pantau kebun secara berkala, terutama pada pucuk muda dan daun baharu.</li><li>Kutip dan musnahkan kumbang dewasa secara manual jika populasi rendah.</li><li>Kawal rumpai di sekitar pokok untuk mengurangkan habitat larva di dalam tanah.</li><li>Galakkan musuh semula jadi seperti burung dan pemangsa serangga.</li></ul><p>Kawalan Kimia (Jika Perlu)</p><ul><li>Gunakan racun serangga yang mengandungi bahan aktif cypermethrin atau deltamethrin, mengikut kadar yang disyorkan pada label produk.</li><li>Semburan hendaklah dilakukan pada waktu pagi di permukaan daun, kerana serangga ini aktif pada waktu tersebut.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>A leaf pest that attacks durian, especially from the young to mature tree stage. Adult beetles feed on the leaf surface, young shoots and sometimes flowers, causing clear damage to the tree canopy. This insect is recognised by its body covered with greenish-gold scales that look like gold dust. The larvae live in the soil and feed on roots, while the adults attack the upper parts of the tree. Adults feed by biting the leaf edges, making the edges uneven or jagged. Insect droppings (frass) are often seen on the leaf surface and on the ground around the tree.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Good Agricultural Practices (GAP)</li><li>Check the orchard regularly, especially young shoots and new leaves.</li><li>Collect and destroy adult beetles by hand when numbers are low.</li><li>Control weeds around the trees to reduce larval habitat in the soil.</li><li>Encourage natural enemies such as birds and insect predators.</li></ul><p>Chemical Control (If Needed)</p><ul><li>Use insecticides containing the active ingredient cypermethrin or deltamethrin, at the rate recommended on the product label.</li><li>Spray the leaf surface in the morning, because the insect is active at that time.</li><li>When using pesticides, always wear protective clothing and follow the label instructions, including the recommended dose, the right time of application and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>一种危害榴莲叶片的害虫，尤其在幼树至成龄树阶段。成虫取食叶面、嫩梢，有时也取食花朵，对树冠造成明显损害。这种昆虫的特征是身体覆盖着金绿色的鳞片，看起来像金粉。幼虫生活在土中取食根部，而成虫则危害树的上部。成虫从叶缘啃食叶片，使叶缘变得不整齐或呈锯齿状。叶面及树下地面常可见到虫粪。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>良好农业规范（APB/GAP）</li><li>定期巡查果园，尤其是嫩梢和新叶。</li><li>虫口数量少时，用手捕捉并销毁成虫。</li><li>清除树木周围的杂草，减少土中幼虫的栖息地。</li><li>保护和利用天敌，如鸟类和捕食性昆虫。</li></ul><p>化学防治（如有需要）</p><ul><li>使用含有效成分氯氰菊酯 cypermethrin 或溴氰菊酯 deltamethrin 的杀虫剂，按产品标签建议的用量使用。</li><li>应在早上喷洒叶面，因为这种害虫在此时段最活跃。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的指示，包括建议剂量、适当的施药时间以及收成前的安全间隔期。</li></ul>"},"symptoms":[{"part":"PEST","img":"Gold_Dust_1_DOA_Sabah.jpg","text":{"ms":"<ul><li>Kumbang dewasa berwarna badan hijau keemasan berkilau yang diselaputi sisik halus.</li><li>Peringkat dewasa merupakan peringkat yang paling kerap ditemui dan menyebabkan kerosakan pada tanaman dengan memakan daun.</li><li>Serangan menyebabkan terbentuknya lubang-lubang tidak sekata pada permukaan dan tepi daun, sekali gus mengurangkan kadar fotosintesis tumbuhan.</li></ul>","en":"<ul><li>The adult beetle has a shiny golden-green body covered with fine scales.</li><li>The adult stage is the one most often found and damages crops by eating the leaves.</li><li>The attack makes irregular holes on the surface and edges of the leaves, which reduces the plant's photosynthesis.</li></ul>","zh":"<ul><li>成虫身体呈闪亮的金绿色，覆盖着细小的鳞片。</li><li>成虫期是最常见的虫期，以取食叶片危害作物。</li><li>受害叶片的表面和边缘出现不规则的孔洞，从而降低植株的光合作用。</li></ul>"},"steps":[]},{"part":"LEAF","img":"Gold_dust_DOA_sabah_qJXzU0j.jpg","text":{"ms":"<ul><li>Kumbang dewasa menyerang dengan mengunyah tepi daun dan menyebabkan tepi daun bergerigi</li></ul>","en":"<ul><li>Adult beetles attack by chewing the leaf edges, making the edges jagged</li></ul>","zh":"<ul><li>成虫啃食叶缘，使叶缘呈锯齿状</li></ul>"},"steps":[]}],"sci":"<em>Hypomeces squamosus</em> Fabricius","kind":"insect","ai":["Cypermethrin","Deltamethrin"]},{"id":122,"crops":["PADDY"],"name":{"ms":"Bena Hijau","en":"Green Leafhopper","zh":"黑尾叶蝉（绿叶蝉）"},"desc":{"ms":"<p>Bena hijau menghisap cecair daun padi dan bertindak sebagai vektor penyakit virus seperti penyakit merah virus (PMV). Serangan menyebabkan daun menjadi kuning, pertumbuhan terbantut dan hasil padi menurun.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Gunakan varieti padi yang rintang atau sederhana rintang.</li><li>Musnahkan rumpai yang menjadi perumah alternatif.</li><li>Laksanakan penanaman serentak dan pengurusan air yang baik.</li><li>Jalankan pemantauan populasi secara berkala.</li><li>Galakkan musuh semula jadi seperti labah-labah dan kumbang pemangsa.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga seperti imidacloprid, dinotefuran atau buprofezin berdasarkan dos yang disyorkan.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>The green leafhopper sucks sap from rice leaves and acts as a vector of virus diseases such as rice tungro disease (PMV). Its attack causes the leaves to turn yellow, stunted growth and lower rice yield.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Use resistant or moderately resistant rice varieties.</li><li>Destroy weeds that act as alternative hosts.</li><li>Plant at the same time as neighbouring fields and manage water well.</li><li>Monitor the pest population regularly.</li><li>Encourage natural enemies such as spiders and predatory beetles.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray insecticides such as imidacloprid, dinotefuran or buprofezin at the recommended dose.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dosage rate, suitable application timing and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>黑尾叶蝉吸食稻叶汁液，并传播病毒病，如水稻东格鲁病（PMV）。受害后叶片变黄、植株生长受阻、稻谷产量下降。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>使用抗虫或中抗的水稻品种。</li><li>清除作为中间寄主的杂草。</li><li>统一同期种植，并做好水分管理。</li><li>定期监测虫口数量。</li><li>保护和利用天敌，如蜘蛛和捕食性甲虫。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按推荐剂量喷施杀虫剂，如吡虫啉 Imidacloprid、呋虫胺 Dinotefuran 或噻嗪酮 Buprofezin。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签说明，包括推荐剂量、适当的施药时间以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"LEAF","img":"Penyakit_PMV_DOA_Sabah.jpg","text":{"ms":"Simptom serangan penyakit merah virus (PMV) yang disebabkan oleh bena hijau.","en":"Symptoms of rice tungro disease (PMV) spread by the green leafhopper.","zh":"由黑尾叶蝉传播的水稻东格鲁病（PMV）症状。"},"steps":[{"img":null,"text":{"ms":"Peringkat nimfa dan dewasa menghisap sap pada daun dan upih rumpun padi mengakibatkan pertumbuhan pokok terbantut dan daunnya menjadi pucat kekeringan.","en":"Nymphs and adults suck sap from the leaves and leaf sheaths of the rice clump, causing stunted growth and pale, dried-out leaves.","zh":"若虫和成虫吸食稻丛叶片和叶鞘的汁液，导致植株生长受阻，叶片发白干枯。"}}]},{"part":"PEST","img":"Bena_hijau_DOA_Sabah_SRU0K3p.jpg","text":{"ms":"Dewasa Bena hijau (Green leafhopper) - <em>Nephotettix virescens</em>","en":"Adult green leafhopper - <em>Nephotettix virescens</em>","zh":"黑尾叶蝉成虫 - <em>Nephotettix virescens</em>"},"steps":[]}],"sci":"<em>Nephotettix virescens</em> (Distant)","kind":"insect","ai":["Buprofezin","Dinotefuran","Imidacloprid"]},{"id":124,"crops":["PADDY"],"name":{"ms":"Bena Perang","en":"Brown Planthopper","zh":"褐飞虱"},"desc":{"ms":"<p>Bena perang ialah perosak utama padi di Asia yang membiak dengan cepat. Betina bertelur pada upih atau daun secara berkelompok. Dewasa berwarna perang dan mempunyai dua bentuk, iaitu makroptera (bersayap panjang) dan brachyptera (bersayap pendek).Perosak ini menghisap cecair pada pangkal pokok padi hingga menyebabkan &ldquo;hopper burn&rdquo; serta boleh menyebarkan penyakit virus padi.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Elakkan penggunaan baja nitrogen secara berlebihan.</li><li>Pantau populasi bena perang secara berkala di sawah.</li><li>Kekalkan musuh semula jadi seperti labah-labah dan kumbang pemangsa.</li><li>Gunakan varieti tahan jika ada dan laksanakan penanaman serentak.</li><li>Elakkan penggunaan racun serangga secara tidak terkawal yang boleh membunuh musuh semula jadi.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga seperti buprofezin, pymetrozine atau imidacloprid berdasarkan dos yang disyorkan.</li><li>Semburan racun serangga dilakukan pada pangkal pokok padi.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>The brown planthopper is a major rice pest in Asia that breeds quickly. Females lay eggs in clusters on the leaf sheaths or leaves. Adults are brown and come in two forms: macropterous (long-winged) and brachypterous (short-winged). This pest sucks sap from the base of the rice plant, causing &ldquo;hopper burn&rdquo;, and it can also spread rice virus diseases.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Avoid using too much nitrogen fertiliser.</li><li>Monitor brown planthopper numbers in the rice field regularly.</li><li>Protect natural enemies such as spiders and predatory beetles.</li><li>Use resistant varieties if available and plant at the same time as neighbouring fields.</li><li>Avoid uncontrolled use of insecticides, which can kill natural enemies.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray insecticides such as buprofezin, pymetrozine or imidacloprid at the recommended dose.</li><li>Spray the insecticide at the base of the rice plants.</li><li>When using pesticides, always wear protective clothing and follow the product label instructions, including the recommended dose rate, the right application timing, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>褐飞虱是亚洲水稻的主要害虫，繁殖速度很快。雌虫把卵成堆产在叶鞘或叶片上。成虫呈褐色，有两种型态：长翅型（macropterous）和短翅型（brachypterous）。这种害虫在稻株基部吸食汁液，造成“虱烧”（hopper burn），还会传播水稻病毒病。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>避免过量施用氮肥。</li><li>定期监测稻田里的褐飞虱数量。</li><li>保护蜘蛛和捕食性甲虫等天敌。</li><li>如有抗虫品种应加以采用，并实行同期种植。</li><li>避免滥用杀虫剂，以免杀死天敌。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按推荐剂量喷施杀虫剂，如噻嗪酮 buprofezin、吡蚜酮 pymetrozine 或吡虫啉 imidacloprid。</li><li>杀虫剂应喷在稻株基部。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括推荐剂量、适当的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"MORFOLOGI","img":"2_cbIYOtG.jpg","text":{"ms":"Bena perang (<em>Nilaparvata lugens</em>)","en":"Brown planthopper (<em>Nilaparvata lugens</em>)","zh":"褐飞虱（<em>Nilaparvata lugens</em>）"},"steps":[]},{"part":"STEM","img":"Hopperburn_DOA_Sabah.jpg","text":{"ms":"<p><strong>Simptom serangan Bena perang pada padi</strong></p><ul><li>Pokok menjadi kuning, layu dan kering secara bertompok (hopper burn).</li><li>Pertumbuhan padi terbantut dan boleh menyebabkan kemusnahan tanaman apabila serangan teruk.</li><li>Lokasi : Projek Penanaman Padi Sawit Kinabalu, Kg. Ongkilan</li></ul>","en":"<p><strong>Symptoms of brown planthopper attack on rice</strong></p><ul><li>Plants turn yellow, wilt and dry out in patches (hopper burn).</li><li>Rice growth is stunted, and severe attack can destroy the crop.</li><li>Location: Projek Penanaman Padi Sawit Kinabalu, Kg. Ongkilan</li></ul>","zh":"<p><strong>褐飞虱危害水稻的症状</strong></p><ul><li>稻株成片变黄、萎蔫并干枯（虱烧）。</li><li>水稻生长受阻，严重时可导致作物毁损。</li><li>地点：Projek Penanaman Padi Sawit Kinabalu（京那巴鲁稻田种植项目），Kg. Ongkilan</li></ul>"},"steps":[]}],"sci":"<em>Nilaparvata lugens</em> (Stål)","kind":"insect","ai":["Buprofezin","Imidacloprid","Pymetrozine"]},{"id":125,"crops":["PADDY"],"name":{"ms":"Kutu Beruang","en":"Rice Black Bug","zh":"稻黑蝽"},"desc":{"ms":"<p>Kutu beruang menghisap cecair batang dan daun padi terutamanya di bahagian pangkal pokok. Serangan menyebabkan pokok menjadi kuning, layu dan pertumbuhan terbantut. Serangan teruk boleh menyebabkan kehilangan hasil yang tinggi.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Bersihkan rumpai dan tunggul jerami kawasan sawah.</li><li>Keringkan petak sawah sementara waktu untuk mengganggu pembiakan kutu dan mendedahkannya kepada musuh semula jadi.</li><li>Gunakan perangkap lampu untuk mengurangkan populasi dewasa.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga seperti fenobucarb, fenthion atau malathion berdasarkan dos yang disyorkan.</li><li>Semburan perlu dilakukan di pangkal pokok padi.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>The rice black bug sucks sap from the stems and leaves of rice plants, especially at the base of the plant. Attacks cause the plants to turn yellow, wilt and become stunted. Severe attacks can cause high yield losses.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Clear weeds and straw stubble from the paddy field.</li><li>Drain the paddy plots for a while to disrupt the bugs' breeding and expose them to natural enemies.</li><li>Use light traps to reduce the adult population.</li></ul><p><strong>Chemical Control (If Needed)</strong></p><ul><li>Spray an insecticide such as fenobucarb, fenthion or malathion at the recommended dose.</li><li>Spray at the base of the rice plants.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>稻黑蝽吸食水稻茎和叶的汁液，尤其是在植株基部。受害植株会变黄、萎蔫，生长受阻。严重危害可造成很大的产量损失。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>清除稻田中的杂草和稻茬。</li><li>暂时排干稻田，以干扰害虫繁殖，并使其暴露于天敌之下。</li><li>使用灯光诱捕器，减少成虫数量。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按建议剂量喷洒杀虫剂，例如仲丁威 fenobucarb、倍硫磷 fenthion 或马拉硫磷 malathion。</li><li>应对准水稻植株基部喷洒。</li><li>使用农药时，务必穿戴防护服，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及采收前的安全间隔期。</li></ul>"},"symptoms":[{"part":"MORFOLOGI","img":"Kutu_beruang_DOA_Sabah.jpg","text":{"ms":"Serangga dewasa Kutu Beruang(<em>Scotinophara coarctata</em>)","en":"Adult rice black bug (<em>Scotinophara coarctata</em>)","zh":"稻黑蝽成虫（<em>Scotinophara coarctata</em>）"},"steps":[]},{"part":"PLANT","img":"Simptom_kutu_beruang_DOA_Sabah.jpg","text":{"ms":"Serangan kutu beruang pada tanaman padi menyebabkan daun menguning, layu, dan pertumbuhan terbantut, manakala serangan yang teruk boleh mengakibatkan tanaman padi mati.","en":"Rice black bug attacks on rice plants cause the leaves to turn yellow and wilt and the plants to be stunted, while severe attacks can kill the rice plants.","zh":"稻黑蝽危害水稻会导致叶片变黄、萎蔫，植株生长受阻；严重危害可使水稻植株死亡。"},"steps":[]}],"sci":"<em>Scotinophara coarctata</em>","kind":"insect","ai":["Fenobucarb","Fenthion","Malathion"]},{"id":126,"crops":["BUAH"],"name":{"ms":"Bintik Daun Alga","en":"Algal Leaf Spot","zh":"藻斑病"},"desc":{"ms":"<p>Bintik daun alga, yang disebabkan oleh patogen <em>Cephaleuros</em> sp., biasanya berlaku pada daun yang terlindung daripada cahaya matahari, terutamanya apabila tanaman terdedah kepada suhu dan kelembapan yang tinggi. Ia menyebabkan kerosakan tidak langsung dengan mengurangkan kawasan fotosintesis daun.</p><p><strong>Pengurusan Penyakit</strong></p><ul><li>Pastikan pokok dipangkas dan dibaja dengan baik untuk menggalakkan pertumbuhan yang sihat. </li><li>Buang semua rumpai di sekitar pangkal pokok</li><li>Gunakan jarak tanaman yang lebih luas untuk meningkatkan pengedaran udara di sekeliling pokok.</li><li>Pokok yang dijangkiti dengan teruk boleh dirawat dengan racun kulat yang mengandungi kuprum.</li></ul></p>","en":"<p>Algal leaf spot, caused by the pathogen <em>Cephaleuros</em> sp., usually occurs on leaves shaded from sunlight, especially when the crop is exposed to high temperature and humidity. It causes indirect damage by reducing the photosynthetic area of the leaves.</p><p><strong>Disease Management</strong></p><ul><li>Make sure trees are well pruned and fertilised to encourage healthy growth.</li><li>Remove all weeds around the base of the tree.</li><li>Use wider plant spacing to improve air circulation around the trees.</li><li>Badly infected trees can be treated with copper-based fungicides.</li></ul>","zh":"<p>藻斑病由病原体 <em>Cephaleuros</em> sp.（头孢藻）引起，通常发生在遮荫、照不到阳光的叶片上，尤其是在作物处于高温高湿环境时。它通过减少叶片的光合作用面积而造成间接危害。</p><p><strong>病害管理</strong></p><ul><li>确保果树修剪得当、施肥充足，以促进健康生长。</li><li>清除树基周围的所有杂草。</li><li>采用较宽的种植距离，以改善树木周围的空气流通。</li><li>严重感染的树可用含铜杀菌剂处理。</li></ul>"},"symptoms":[{"part":"LEAF","img":"1.jpg","text":{"ms":"<ul><li>Bintik-bintik merah jingga yang timbul pada kedua-dua permukaan atas dan bawah daun.</li><li>Tompok-tompok mungkin bercantum untuk membentuk tompok berbentuk tidak sekata.</li><li>Bintik-bintik juga mungkin terdapat pada ranting dan dahan.</li><li>Apabila permukaan bintik dikikis, kerak nekrotik berwarna kelabu dapat dilihat.</li></ul>","en":"<ul><li>Raised orange-red spots on both the upper and lower surfaces of the leaves.</li><li>The spots may merge to form irregularly shaped patches.</li><li>Spots may also be found on twigs and branches.</li><li>When the surface of a spot is scraped off, a grey necrotic crust can be seen.</li></ul>","zh":"<ul><li>叶片正面和背面都出现凸起的橙红色斑点。</li><li>斑点可能会合并，形成形状不规则的斑块。</li><li>细枝和枝条上也可能出现斑点。</li><li>刮去斑点表面后，可见灰色的坏死硬壳。</li></ul>"},"steps":[]}],"sci":"<em>Cephaleuros virescens</em>","kind":"alga","ai":["Copper"]},{"id":127,"crops":["BUAH"],"name":{"ms":"Kutu Trip Avokado","en":"Avocado Thrips","zh":"牛油果蓟马"},"desc":{"ms":"<p>Kutu trip (Thysanoptera: Thripidae) adalah serangga kecil, bersaiz 1-2 mm, mempunyai dua pasang sayap yang terdiri daripada rerambut halus serta bahagian mulut yang menusuk. Kutu trip (dewasa dan nimfa) menyerang tumbuhan dengan cara menusuk lapisan tisu tumbuhan dan menyedut sap yang menyebabkan kerosakan. Kutu trip boleh dijumpai pada daun dan dalam bunga.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Kawal rumpai di sekitar yang menjadi perumah alternatif bagi kutu trip</li><li>Potong dan musnahkan bahagian tanaman yang terdapat simptom serangan</li><li>Pemangsa semula jadi: lacewings hijau dan beberapa jenis lebah parasit membantu mengawal kutu trip.</li><li>Mendorong populasi pemangsa semula jadi yang bermanfaat, dengan mengurangkan penggunaan racun perosak berspektrum luas.</li></ul><p>Kaedah kimia (Jika Perlu)</p><ul><li>Racun perosak jenis sentuh; azadirachtin, sabun insektisida, dan neem.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>Thrips (Thysanoptera: Thripidae) are small insects, 1-2 mm in size, with two pairs of wings made of fine hairs and piercing mouthparts. Thrips (adults and nymphs) attack plants by piercing the plant tissue and sucking the sap, which causes damage. Thrips can be found on leaves and inside flowers.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Control weeds in the surrounding area that serve as alternative hosts for thrips</li><li>Cut off and destroy plant parts that show symptoms of attack</li><li>Natural predators: green lacewings and some types of parasitic wasps help control thrips.</li><li>Encourage populations of beneficial natural predators by reducing the use of broad-spectrum pesticides.</li></ul><p>Chemical control (If needed)</p><ul><li>Contact pesticides: azadirachtin, insecticidal soap and neem.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>蓟马（缨翅目：蓟马科）是体长1-2 mm的小型昆虫，有两对由细毛组成的翅膀，口器为刺吸式。蓟马（成虫和若虫）刺破植物组织并吸食汁液，从而造成损害。蓟马可在叶片上和花朵内发现。</p><p><strong>综合虫害管理 (IPM)</strong></p><ul><li>防除周边作为蓟马替代寄主的杂草</li><li>剪除并销毁出现受害症状的植株部位</li><li>天然捕食者：草蛉和一些寄生蜂有助于控制蓟马。</li><li>减少使用广谱农药，以促进有益天敌的数量。</li></ul><p>化学防治（如有需要）</p><ul><li>触杀型农药：azadirachtin（印楝素）、杀虫皂和印楝（neem）。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"MORFOLOGI","img":"avocdo_thrips_2YJbXCP.jpg","text":{"ms":"Kutu trip avokado dewasa","en":"Adult avocado thrips","zh":"牛油果蓟马成虫"},"steps":[]},{"part":"FR","img":"Psyllid_durian_2.jpg","text":{"ms":"Kesan calar dan parut pada permukaan kulit buah","en":"Scratch marks and scars on the surface of the fruit skin","zh":"果皮表面出现刮痕和疤痕"},"steps":[]}],"sci":"<em>Scirtothrips perseae</em> Nakahara","kind":"insect","ai":["Azadirachtin","Neem"]},{"id":128,"crops":["BUAH"],"name":{"ms":"Antraknos Avokado","en":"Avocado Anthracnose","zh":"牛油果炭疽病"},"desc":{"ms":"<p>Kulat yang menyebabkan antraknos pada avokado boleh hidup sepanjang musim dalam sisa tumbuhan yang dijangkiti atau di dalam buah. Apabila keadaan persekitaran menggalakkan pertumbuhan patogen, seperti kelembapan tinggi dan suhu sederhana, kulat ini akan menghasilkan spora. Spora tersebut boleh tersebar melalui hujan, angin atau sentuhan fizikal dan akan menjangkiti tisu avokado yang sihat lalu menyebabkan jangkitan baharu.</p><p><strong>Pengurusan Kawalan:</strong></p><ul><li>Pangkas ranting dan dahan mati sebelum kulat menghasilkan spora</li><li>Buang daun mati dari kanopi pokok.</li><li>Pastikan buah yang telah dituai sentiasa kering dan disimpan dalam keadaan sejuk.</li></ul>","en":"<p>The fungus that causes anthracnose in avocado can survive all season in infected plant debris or inside the fruit. When conditions favour the pathogen, such as high humidity and moderate temperatures, the fungus produces spores. These spores can be spread by rain, wind or physical contact, and they infect healthy avocado tissue, causing new infections.</p><p><strong>Control Management:</strong></p><ul><li>Prune dead twigs and branches before the fungus produces spores</li><li>Remove dead leaves from the tree canopy.</li><li>Keep harvested fruit dry and store it in cool conditions.</li></ul>","zh":"<p>引起牛油果炭疽病的真菌可在受感染的植物残体或果实内存活一整季。当环境有利于病原菌生长时，例如高湿度和温度适中，这种真菌便会产生孢子。孢子可通过雨水、风或接触传播，感染健康的牛油果组织，造成新的感染。</p><p><strong>防治管理：</strong></p><ul><li>在真菌产生孢子之前，剪除枯死的小枝和枝条</li><li>清除树冠中的枯叶。</li><li>确保采收后的果实保持干燥，并存放在阴凉处。</li></ul>"},"symptoms":[{"part":"FR","img":"gmbar.jpg","text":{"ms":"Bintik-bintik klorotik dan nekrotik; lesi coklat atau ungu pada buah.","en":"Chlorotic (yellowing) and necrotic (dead) spots; brown or purple lesions on the fruit.","zh":"出现褪绿（发黄）和坏死斑点；果实上有褐色或紫色病斑。"},"steps":[]}],"sci":"<em>Glomerella cingulata</em>","kind":"fungus","ai":[]},{"id":129,"crops":["BUAH"],"name":{"ms":"Keruping Avokado","en":"Avocado Scab","zh":"鳄梨疮痂病（牛油果疮痂病）"},"desc":{"ms":"<p>Keruping (Sphaceloma perseae) adalah penyakit kulat pada avokado yang mengurangkan kualiti buah.</p><p>Pengurusan Penyakit</p><ul><li>Pangkas ranting dan dahan yang mati dari pokok sebelum kulat menghasilkan spora</li><li>Sembur dengan racun kulat kuprum pada peringkat awal perkembangan buah.</li></ul>","en":"<p>Scab (<em>Sphaceloma perseae</em>) is a fungal disease of avocado that reduces fruit quality.</p><p>Disease Management</p><ul><li>Prune dead twigs and branches from the tree before the fungus produces spores.</li><li>Spray with a copper fungicide at the early stage of fruit development.</li></ul>","zh":"<p>疮痂病（<em>Sphaceloma perseae</em>）是鳄梨（牛油果）的一种真菌病害，会降低果实品质。</p><p>病害管理</p><ul><li>在真菌产生孢子之前，剪除树上的枯枝。</li><li>在果实发育初期喷施铜制杀菌剂。</li></ul>"},"symptoms":[{"part":"FR","img":"Untitled_design-2.jpg","text":{"ms":"<ul><li>Kehadiran tompok-tompok kecil berwarna coklat gelap atau hitam yang kasar dan berkeruping pada permukaan kulit buah.</li><li>Jangkitan ini boleh menyebabkan kulit buah retak, berparut dan memberi kesan lekuk yang menjejaskan penampilan buah walaupun isinya masih elok.</li><li>Dalam kes yang teruk, buah yang dijangkiti mungkin gugur sebelum matang.</li></ul>","en":"<ul><li>Small, rough, scabby dark brown or black spots appear on the fruit skin.</li><li>The infection can make the fruit skin crack, scar and become dented, spoiling the look of the fruit even though the flesh is still good.</li><li>In severe cases, infected fruit may drop before it is ripe.</li></ul>","zh":"<ul><li>果皮表面出现深褐色或黑色、粗糙结痂的小斑点。</li><li>感染可导致果皮开裂、留疤和凹陷，影响果实外观，但果肉仍然完好。</li><li>严重时，受感染的果实可能在成熟前脱落。</li></ul>"},"steps":[]}],"sci":"<em>Sphaceloma perseae</em> Jenkins","kind":"fungus","ai":["Copper"]},{"id":131,"crops":["BUAH"],"name":{"ms":"Lalat Buah","en":"Fruit Fly","zh":"果实蝇"},"desc":{"ms":"<p>Lalat buah (Diptera: Tephritidae) merupakan serangga perosak utama bagi tanaman buah-buahan. Serangga ini bertelur di dalam buah sama ada pada peringkat muda atau matang, dan larvanya akan berkembang di dalam buah tersebut. Serangan larva boleh merosakkan isi buah, menyebabkan pembusukan, serta menurunkan kualiti hasil buah.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Kumpulkan buah yang menunjukkan simptom serangan serta buah yang gugur.</li><li>Tanam buah tersebut dalam lubang yang dalam bagi mengelakkan penyebaran perosak.</li><li>Amalkan pembungkusan buah untuk melindungi buah daripada serangan lanjut.</li><li>Menggunakan <em>Fopius arisanus</em>, parasitoid hymenoptera (Kawalan biologi)</li></ul><p>Kawalan kimia (Jika Perlu)</p><ul><li>Semburan racun serangga yang sesuai (contohnya, malathion, spinosad, fipronil) dicampur dengan umpan protein (methyl eugenol) berdasarkan dos yang disyorkan.</li><li>Umpan menggunakan feromon methyl eugenol untuk menarik lalat buah jantan.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul></p>","en":"<p>Fruit flies (Diptera: Tephritidae) are major insect pests of fruit crops. They lay eggs inside young or ripe fruits, and the larvae develop inside the fruit. Larval attack damages the fruit flesh, causes rotting and lowers fruit quality.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Collect fruits showing signs of attack as well as fallen fruits.</li><li>Bury these fruits in a deep hole to stop the pest from spreading.</li><li>Wrap (bag) the fruits to protect them from further attack.</li><li>Use <em>Fopius arisanus</em>, a hymenopteran parasitoid (biological control).</li></ul><p>Chemical control (If Necessary)</p><ul><li>Spray a suitable insecticide (for example malathion, spinosad, fipronil) mixed with a protein bait (methyl eugenol) at the recommended dose.</li><li>Use methyl eugenol pheromone bait to attract male fruit flies.</li><li>When using pesticides, always wear protective clothing and follow the product label instructions, including the recommended dose rate, the right application timing, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>果实蝇（双翅目：实蝇科）是果树的主要害虫。它们把卵产在幼果或成熟果实里，幼虫在果实内发育。幼虫危害果肉，使果实腐烂，降低果实品质。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>收集有受害症状的果实以及掉落的果实。</li><li>把这些果实埋在深坑中，防止害虫扩散。</li><li>为果实套袋，保护果实免受进一步危害。</li><li>利用膜翅目寄生蜂 <em>Fopius arisanus</em>（阿里山潜蝇茧蜂）进行生物防治。</li></ul><p>化学防治（如有需要）</p><ul><li>按推荐剂量喷施适当的杀虫剂（例如马拉硫磷 malathion、多杀菌素 spinosad、氟虫腈 fipronil），并混合蛋白诱饵（甲基丁香酚 methyl eugenol）。</li><li>使用甲基丁香酚 methyl eugenol 信息素诱饵引诱雄性果实蝇。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括推荐剂量、适当的施药时间，以及收割前的安全间隔期。</li></ul>"},"symptoms":[{"part":"MORFOLOGI","img":"lalat_buah_avo_v2URDZE.jpg","text":{"ms":"Lalat buah <em>Bactrocera</em> spp.","en":"Fruit fly <em>Bactrocera</em> spp.","zh":"果实蝇 <em>Bactrocera</em> spp."},"steps":[]},{"part":"FR","img":"Simptom_serangan_lalat_buah_pada_buah_avokado_1.jpg","text":{"ms":"<strong>Simptom serangan lalat buah pada buah avokado;</strong><p>1. Pembentukan buah terbantut </p><p>2. Buah muda gugur</p><p>3. Lubang kecil pada kulit buah (lalat buah bertelur)</p><p>4. Terdapat larva di dalam buah</p><p>5. Cairan atau residu keluar dari buah</p>","en":"<strong>Symptoms of fruit fly attack on avocado fruit:</strong><p>1. Fruit development is stunted</p><p>2. Young fruits drop</p><p>3. Small holes on the fruit skin (where the fruit fly laid eggs)</p><p>4. Larvae (maggots) inside the fruit</p><p>5. Liquid or residue oozes out of the fruit</p>","zh":"<strong>果实蝇危害牛油果果实的症状：</strong><p>1. 果实发育受阻</p><p>2. 幼果掉落</p><p>3. 果皮上有小孔（果实蝇产卵处）</p><p>4. 果实内有幼虫（蛆）</p><p>5. 果实流出汁液或残留物</p>"},"steps":[]}],"sci":"<em>Bactrocera</em> spp.","kind":"insect","ai":["Fipronil","Malathion","Methyl eugenol","Spinosad"]},{"id":132,"crops":["BUAH"],"name":{"ms":"Reput Akar Phytophthora","en":"Phytophthora Root Rot","zh":"鳄梨疫霉根腐病"},"desc":{"ms":"<p><em>Phytophthora cinnamomi </em>adalahagen penyebab penyakit reput akar Phytophthora. Setelah patogen ini berjaya bertapak dalam tanah, ia tidak dapat dimusnahkan dari kawasan yang terjejas kerana ia boleh kekal dalam tanah atau bahan tanaman yang dijangkiti dalam jangka masa yang panjang.</p><p><strong>Pengurusan Penyakit</strong></p><ul><li>Laksanakan langkah sanitasi yang betul, amalan kultur yang baik dan kawalan kimia yang bersesuaian.</li><li>Kawalan paling penting bagi penyakit ini adalah pengurusan pengairan yang baik.</li><li>Gunakan bahan tanaman yang bebas penyakit terutamanya apabila menanam di kawasan baharu.</li><li>Gunakan baja yang mengandungi elemen nitrogen yang sederhana untuk menggalakkan pertumbuhan yang baik dan membantu pokok avokado lebih tahan terhadap penyakit reput akar. Elakkan penggunaan baja yang berlebihan.</li><li>Beberapa jenis racun kulat fosfonat (asid fosforus dan sebatian fosfonat) boleh meningkatkan keupayaan pokok untuk menahan, mencegah atau pulih daripada jangkitan.</li><li>Racun kulat berasaskan kuprum juga telah digunakan secara meluas untuk mengawal penyakit ini pada tanaman avokado.</li></ul>","en":"<p><em>Phytophthora cinnamomi</em> is the agent that causes Phytophthora root rot. Once this pathogen has become established in the soil, it cannot be eliminated from the affected area, because it can survive in the soil or in infected plant material for a long time.</p><p><strong>Disease Management</strong></p><ul><li>Carry out proper sanitation, good cultural practices and suitable chemical control.</li><li>The most important control for this disease is good irrigation (water) management.</li><li>Use disease-free planting material, especially when planting in a new area.</li><li>Use fertiliser with a moderate nitrogen content to encourage good growth and help avocado trees better withstand root rot. Avoid using too much fertiliser.</li><li>Some phosphonate fungicides (phosphorous acid and phosphonate compounds) can improve the tree's ability to withstand, prevent or recover from infection.</li><li>Copper-based fungicides have also been widely used to control this disease in avocado.</li></ul>","zh":"<p><em>Phytophthora cinnamomi</em>（樟疫霉）是引起疫霉根腐病的病原。这种病原一旦在土壤中立足，就无法从受害地区清除，因为它可以在土壤或受感染的植物材料中长期存活。</p><p><strong>病害管理</strong></p><ul><li>落实正确的卫生措施、良好的栽培管理和适当的化学防治。</li><li>防治此病最重要的是做好灌溉（水分）管理。</li><li>使用无病的种植材料，尤其是在新地区种植时。</li><li>使用含氮量适中的肥料，促进良好生长，帮助鳄梨（牛油果）树更能抵抗根腐病。避免过量施肥。</li><li>某些亚磷酸盐类杀菌剂（亚磷酸及亚磷酸盐化合物）可提高果树抵抗、预防感染或从感染中恢复的能力。</li><li>铜基杀菌剂也已被广泛用于防治鳄梨上的这种病害。</li></ul>"},"symptoms":[{"part":"ROOT","img":"Screenshot_2024-01-16_103032.jpg","text":{"ms":"<ul><li>Akar serabut berkurangan pada peringkat jangkitan penyakit yang teruk.</li></ul>","en":"<ul><li>Fine feeder roots become fewer when the infection is severe.</li></ul>","zh":"<ul><li>感染严重时，须根（吸收根）明显减少。</li></ul>"},"steps":[]},{"part":"LEAF","img":"Screenshot_2024-01-16_103902.jpg","text":{"ms":"<ul><li>Daun kecil, hijau pucat atau kekuningan.</li><li>Daun sering layu dan mempunyai hujung berwarna coklat dan nekrotik.</li><li>Daun menjadi jarang dan pertumbuhan baru jarang berlaku. Terdapat longgokan daun gugur di bawah pokok yang dijangkiti.</li></ul>","en":"<ul><li>Leaves are small, pale green or yellowish.</li><li>Leaves often wilt and have brown, dead (necrotic) tips.</li><li>Foliage becomes sparse and new growth is rare. Fallen leaves pile up under infected trees.</li></ul>","zh":"<ul><li>叶片小，呈淡绿色或黄色。</li><li>叶片常萎蔫，叶尖褐色、坏死。</li><li>树叶稀疏，很少长出新梢。受感染的树下堆积着落叶。</li></ul>"},"steps":[]}],"sci":"<em>Phytophthora cinnamomi</em>","kind":"oomycete","ai":["Copper","Phosphonate"]},{"id":134,"crops":["KOPI"],"name":{"ms":"Kumbang Pengorek Buah Kopi","en":"Coffee Berry Borer","zh":"咖啡果小蠹"},"desc":{"ms":"<p>Pengorek Buah Kopi merupakan salah satu perosak serangga yang paling merosakkan tanaman kopi di seluruh dunia. Kumbang betina dewasa mengorek masuk ke dalam buah kopi yang sedang berkembang atau masak untuk bertelur, manakala larvanya memakan biji kopi di dalam buah. Serangan perosak ini menyebabkan penurunan kualiti biji kopi, pengurangan hasil, dan kerugian ekonomi yang ketara. Simptom serangan termasuk kehadiran lubang kecil pada buah kopi, buah gugur sebelum matang, serta biji kopi yang rosak atau berongga. Serangan yang teruk boleh menjejaskan nilai pasaran hasil kopi.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Kutip dan musnahkan buah kopi yang gugur atau rosak.</li><li>Laksanakan penuaian tepat pada masa.</li><li>Amalkan kebersihan ladang secara berterusan.</li><li>Gunakan perangkap feromon untuk pemantauan dan pengendalian populasi.</li><li>Gunakan biopestisid berasaskan kulat seperti <em>Metarhizium anisopliae</em> dan <em>Beauveria bassiana</em> untuk mengawal CBB secara biologi.</li><li>Galakkan musuh semula jadi seperti parasitoid <em>Cephalonomia stephanoderis</em>.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan racun serangga mengikut syor dalam label.</li><li> Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>The Coffee Berry Borer is one of the most damaging insect pests of coffee worldwide. Adult female beetles bore into developing or ripe coffee berries to lay eggs, and the larvae feed on the coffee beans inside the berry. This pest reduces bean quality, lowers yield and causes significant economic losses. Symptoms include small holes in the coffee berries, berries falling before they are ripe, and damaged or hollow beans. Severe attacks can reduce the market value of the coffee harvest.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Collect and destroy fallen or damaged coffee berries.</li><li>Harvest on time.</li><li>Keep the farm clean at all times.</li><li>Use pheromone traps to monitor and control the population.</li><li>Use fungus-based biopesticides such as <em>Metarhizium anisopliae</em> and <em>Beauveria bassiana</em> for biological control of CBB.</li><li>Encourage natural enemies such as the parasitoid <em>Cephalonomia stephanoderis</em>.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray insecticides according to the label recommendations.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>咖啡果小蠹是全世界危害咖啡最严重的害虫之一。成年雌虫钻入正在发育或已成熟的咖啡果内产卵，幼虫则取食果内的咖啡豆。这种害虫会降低咖啡豆品质、减少产量，并造成严重的经济损失。危害症状包括咖啡果上有小孔、果实未熟先落，以及咖啡豆受损或中空。严重危害会降低咖啡收成的市场价值。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>收集并销毁掉落或受损的咖啡果。</li><li>适时采收。</li><li>持续保持园地清洁。</li><li>使用性信息素诱捕器监测和控制虫口数量。</li><li>使用真菌类生物农药，例如 <em>Metarhizium anisopliae</em>（绿僵菌）和 <em>Beauveria bassiana</em>（白僵菌），对咖啡果小蠹进行生物防治。</li><li>保护和利用天敌，例如寄生蜂 <em>Cephalonomia stephanoderis</em>。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>按照标签建议喷施杀虫剂。</li><li>使用农药时，务必穿戴防护衣物，并遵守产品标签上的说明，包括推荐剂量、合适的施药时间，以及收获前的安全间隔期。</li></ul>"},"symptoms":[{"part":"PEST","img":"CBB_DOA_Sabah.jpg","text":{"ms":"Kumbang pengorek biji kopi (Coffee Pod Borer) - <em>Hypothenemus hampei</em>","en":"Coffee berry borer (Coffee Pod Borer) - <em>Hypothenemus hampei</em>","zh":"咖啡果小蠹 - <em>Hypothenemus hampei</em>"},"steps":[]},{"part":"FR","img":"CBB_2_DOA_Sabah.jpg","text":{"ms":"<ul><li>Terdapat lubang kecil berbentuk bulat pada permukaan buah kopi (lubang kumbang masuk).</li><li>Kehadiran serbuk halus berwarna coklat di sekitar lubang serangan akibat aktiviti pengorekan.</li><li>Buah kopi menunjukkan tanda kerosakan dalaman apabila dibelah.</li><li>Buah yang diserang boleh mengalami kematangan tidak sekata.</li><li>Berlaku keguguran buah pramatang dalam serangan yang serius.</li></ul>","en":"<ul><li>Small round holes on the surface of the coffee berry (beetle entry holes).</li><li>Fine brown powder (frass) around the entry hole from the boring activity.</li><li>The coffee berry shows internal damage when cut open.</li><li>Attacked berries may ripen unevenly.</li><li>Berries drop before they are ripe in serious attacks.</li></ul>","zh":"<ul><li>咖啡果表面有圆形小孔（成虫钻入孔）。</li><li>蛀孔周围有蛀食留下的褐色细粉（虫粪）。</li><li>切开咖啡果可见内部受损。</li><li>受害果实可能成熟不均匀。</li><li>严重危害时会出现未熟落果。</li></ul>"},"steps":[]},{"part":"BEAN","img":"CBB_3_DOA_Sabah.jpg","text":{"ms":"<ul><li>Buah kopi menunjukkan tanda kerosakan dalaman apabila dibelah.</li><li>Biji kopi menjadi berlubang, rosak atau berongga akibat pemakanan larva.</li><li>Kualiti dan berat biji kopi menurun, menyebabkan nilai pasaran hasil berkurangan.</li><li>Serangan teruk boleh menyebabkan kehilangan hasil yang ketara dan menjejaskan mutu kopi.</li></ul>","en":"<ul><li>The coffee berry shows internal damage when cut open.</li><li>Coffee beans become holed, damaged or hollow because of larval feeding.</li><li>Bean quality and weight drop, lowering the market value of the harvest.</li><li>Severe attacks can cause significant yield loss and lower coffee quality.</li></ul>","zh":"<ul><li>切开咖啡果可见内部受损。</li><li>由于幼虫取食，咖啡豆出现蛀孔、受损或中空。</li><li>咖啡豆的品质和重量下降，使收成的市场价值降低。</li><li>严重危害会造成显著的产量损失，并影响咖啡品质。</li></ul>"},"steps":[]}],"sci":"<em>Hypothenemus hampei</em>","kind":"insect","ai":["Beauveria bassiana","Metarhizium anisopliae"]},{"id":156,"crops":["CABBAGE"],"name":{"ms":"Ulat Ratus","en":"Common Cutworm","zh":"斜纹夜蛾"},"desc":{"ms":"Serangga ini menyerang diperingkat larva yang baru menetas makan daun dan pucuk secara berkumpulan dan berselerak. Apabila meningkat kedua dan seterusnya larva menyerang daun dan pucuk berasingan. serangan yang teruk boleh memusnahkan daun sehingga daun tinggal rangka sahaja. Kawalan dilakukan dengan menyembur racun perosak deltamethrin, cypermethrin, gamma-cyhalothrin, emamectin benzoate atau <em>Bacillus thuringiensis</em> mengikut kadar yang disyorkan, musnah serangga dan daun yang di serang.","en":"This insect attacks at the larval stage. Newly hatched larvae feed on leaves and shoots in groups, then scatter. From the second instar onwards, the larvae attack leaves and shoots separately. Severe attacks can destroy the leaves until only the leaf skeleton is left. Control by spraying pesticides such as deltamethrin, cypermethrin, gamma-cyhalothrin, emamectin benzoate or <em>Bacillus thuringiensis</em> at the recommended rate, and destroy the insects and attacked leaves.","zh":"这种害虫在幼虫期造成危害。刚孵化的幼虫成群取食叶片和嫩梢，之后分散开来。从二龄起，幼虫分散各自取食叶片和嫩梢。严重侵害可把叶片吃光，只剩下叶脉骨架。防治方法：按建议用量喷洒农药，例如 deltamethrin（溴氰菊酯）、cypermethrin（氯氰菊酯）、gamma-cyhalothrin（精高效氯氟氰菊酯）、emamectin benzoate（甲氨基阿维菌素苯甲酸盐）或 <em>Bacillus thuringiensis</em>（苏云金杆菌，Bt），并销毁害虫和受害叶片。"},"symptoms":[{"part":"LEAF","img":"kobis.jpg","text":{"ms":"Serangga ini menyerang diperingkat larva yang baru menetas makan daun dan pucuk secara berkumpulan dan berselerak. Apabila peringkat kedua dan seterusnya larva menyerang daun dan pucuk berasingan. serangan yang teruk boleh memusnahkan daun sehingga daun tinggal rangka sahaja.","en":"This insect attacks at the larval stage. Newly hatched larvae feed on leaves and shoots in groups, then scatter. From the second instar onwards, the larvae attack leaves and shoots separately. Severe attacks can destroy the leaves until only the leaf skeleton is left.","zh":"这种害虫在幼虫期造成危害。刚孵化的幼虫成群取食叶片和嫩梢，之后分散开来。从二龄起，幼虫分散各自取食叶片和嫩梢。严重侵害可把叶片吃光，只剩下叶脉骨架。"},"steps":[]}],"sci":"<em>Spodoptera litura</em> (Fabricius)","kind":"insect","ai":["Bacillus thuringiensis","Cypermethrin","Deltamethrin","Emamectin benzoate","Gamma-cyhalothrin"]},{"id":157,"crops":["PAPAYA"],"name":{"ms":"Lalat Buah Betik","en":"Papaya Fruit Fly","zh":"木瓜果实蝇"},"desc":{"ms":"<ul><li>Serangga aktif pada waktu siang terutama waktu pagi dan petang</li><li>Populasi lalat buah meningkat dengan cepat dalam cuaca panas dan lembap</li><li>Lalat buah biasanya menyerang buah betik semasa buah hampir matang atau baru mula masak</li></ul><p>Pengurusan perosak</p><ul><li>Amalan pertanian baik</li><li>Balut buah betik dengan plastik lutsinar atau kertas khas.</li><li>Tuai buah awal, jangan tunggu terlalu masak atas pokok.</li><li>Guna perangkap feromon (methyl eugenol) yang sangat menarik lalat jantan.</li><li>Penggunaan racun kimia mengikut syor dalam label (contoh: cypermethrin dan deltamethrin).</li></ul>","en":"<ul><li>The insect is active during the day, especially in the morning and late afternoon</li><li>Fruit fly numbers increase quickly in hot and humid weather</li><li>Fruit flies usually attack papaya when the fruit is nearly ripe or just starting to ripen</li></ul><p>Pest management</p><ul><li>Good Agricultural Practices</li><li>Wrap papaya fruits with clear plastic or special paper.</li><li>Harvest fruit early; do not wait until it is too ripe on the tree.</li><li>Use pheromone traps (methyl eugenol), which strongly attract male flies.</li><li>Use chemical pesticides according to the label recommendation (e.g. cypermethrin and deltamethrin).</li></ul>","zh":"<ul><li>这种昆虫在白天活动，尤其是早上和傍晚</li><li>在炎热潮湿的天气里，果实蝇数量会迅速增加</li><li>果实蝇通常在木瓜接近成熟或刚开始成熟时危害果实</li></ul><p>害虫管理</p><ul><li>良好农业规范（APB/GAP）</li><li>用透明塑料袋或专用纸袋包裹木瓜果实。</li><li>提早采收，不要等果实在树上过熟。</li><li>使用信息素诱捕器（甲基丁香酚 methyl eugenol），对雄蝇有很强的吸引力。</li><li>按照标签建议使用化学农药（例如：氯氰菊酯 cypermethrin 和溴氰菊酯 deltamethrin）。</li></ul>"},"symptoms":[{"part":"FR","img":"papaya-fruit-fly.jpg","text":{"ms":"<ul><li>Buah betik yang diserang lalat buah menunjukkan tanda seperti lubang tusukan kecil, buah mengeluarkan getah putih, isi buah lembik atau busuk, terdapat larva di dalamnya, dan sering gugur sebelum matang.</li></ul>","en":"<ul><li>Papaya fruits attacked by fruit flies show signs such as small puncture holes, white sap oozing from the fruit, soft or rotten flesh, larvae (maggots) inside, and often drop before ripening.</li></ul>","zh":"<ul><li>受果实蝇危害的木瓜会出现以下迹象：果皮上有细小的刺孔、果实流出白色乳汁、果肉变软或腐烂、果内有幼虫（蛆），并常在成熟前掉落。</li></ul>"},"steps":[]}],"sci":"<em>Bactrocera papayae</em>","kind":"insect","ai":["Cypermethrin","Deltamethrin","Methyl eugenol"]},{"id":159,"crops":["GINGER"],"name":{"ms":"Penyakit Layu Bakteria Halia","en":"Ginger Bacterial Wilt","zh":"生姜青枯病（细菌性枯萎病）"},"desc":{"ms":"Penyakit layu bakteria pada tanaman halia, disebabkan oleh <em>Ralstonia solanacearum</em>, merupakan ancaman serius. Ia menjejaskan sistem vaskular, menyebabkan gejala layu pada daun muda pada siang hari yang mungkin pulih pada malam hari, manakala daun lebih tua layu secara beransur-ansur tetapi kekal hijau. Penyakit ini berkembang dengan kuningnya daun sebelum layu, sering disertai dengan pemeronokan batang. Akar dan rizom yang dijangkiti menjadi lembik dan berwarna coklat, mengeluarkan bau yang tidak menyenangkan. Pertumbuhan tanaman terhambat, dan batang yang dijangkiti mungkin mengeluarkan lendir bakteria putih (ooze) apabila dipotong. Penyakit ini merebak dengan cepat, biasanya bermula dari satu sisi tanaman dan menjangkiti keseluruhan tanaman, memerlukan pengurusan yang cermat melalui bahan tanaman yang bebas penyakit, penggiliran tanaman, dan pemeliharaan kesihatan tanah.","en":"Bacterial wilt of ginger, caused by <em>Ralstonia solanacearum</em>, is a serious threat. It affects the plant's vascular system, causing young leaves to wilt during the day and possibly recover at night, while older leaves wilt gradually but stay green. As the disease develops, the leaves turn yellow before wilting, often together with browning of the stems. Infected roots and rhizomes become soft and brown and give off an unpleasant smell. Plant growth is stunted, and infected stems may release white bacterial slime (ooze) when cut. The disease spreads quickly, usually starting on one side of the plant and then infecting the whole plant. It needs careful management through disease-free planting material, crop rotation and keeping the soil healthy.","zh":"由<em>Ralstonia solanacearum</em>（青枯雷尔氏菌）引起的生姜青枯病是一种严重威胁。它破坏植株的维管束系统，使嫩叶在白天萎蔫、夜间可能恢复，而老叶则逐渐萎蔫但仍保持绿色。随着病情发展，叶片先变黄后萎蔫，茎部也常常变褐。受感染的根和根茎（姜块）变软、变褐，并散发难闻气味。植株生长受阻，切开受感染的茎时可能流出白色菌脓。此病蔓延迅速，通常从植株一侧开始，再扩展到整株。需要认真管理，包括使用无病种植材料、实行轮作以及保持土壤健康。"},"symptoms":[{"part":"PLANT","img":"Untitled_design.jpg","text":{"ms":"Penyakit ini menyebabkan lesi lecuh basah pada pangkal pseudostem menjadikannya reput dan mudah tercabut. Daun akan berubah kekuningan bermula dari daun bawah dan merebak ke daun atas dan kemudian akan menjadi nekrotik. Rizom turut mereput, berbau busuk, pokok terbantut serta mati.","en":"The disease causes wet, water-soaked lesions at the base of the pseudostem, making it rot and easy to pull out. The leaves turn yellow, starting from the lower leaves and spreading to the upper leaves, and then become necrotic (die). The rhizome also rots and smells foul, and the plant is stunted and dies.","zh":"此病会在假茎基部造成湿润的水渍状病斑，使其腐烂，容易被拔起。叶片从下部开始变黄，逐渐蔓延到上部叶片，随后坏死。根茎（姜块）也会腐烂并发出恶臭，植株矮化并死亡。"},"steps":[]}],"sci":"<em>Ralstonia solanacearum</em> (Smith) Yabuuchi et al.","kind":"bacteria","ai":[]},{"id":171,"crops":["GINGER"],"name":{"ms":"Busuk Rizom Halia","en":"Ginger Rhizome Rot","zh":"姜根茎腐病"},"desc":{"ms":"<p>Busuk rizom pada halia, disebabkan oleh pelbagai patogen seperti spesies <em>Pythium</em>, melibatkan penerangan berikut :<br><strong>- Gejala:</strong> Tanda-tanda awal busuk rizom biasanya termasuk lembut dan perubahan warna pada rizom halia. Rizom yang terkena boleh kelihatan seperti diserap air, lembap, dan boleh memancarkan bau busuk apabila penyakit berkembang. Rizom yang dijangkiti juga boleh mempunyai lepuhan atau bintik hitam.</p><p><strong>- Patogen: </strong>Busuk rizom disebabkan oleh beberapa patogen, di mana spesies <em>Pythium</em> adalah salah satu penyebab yang utama. Patogen ini berkembang dengan baik di tanah yang bertakung air atau sistem pengairan yang tidak baik, terutamanya dalam keadaan panas dan lembap.</p><p><strong>- Impak: </strong>Penyakit ini mempengaruhi organ penyimpanan tanaman halia, mengurangkan kualiti dan nilai pasarnya. Infeksi yang teruk boleh menyebabkan kerugian hasil yang signifikan kerana rizom yang terinfeksi tidak sesuai untuk dimakan atau ditanam semula.</p><p><strong>- Penyebaran:</strong> Patogen yang bertanggungjawab terhadap busuk rizom boleh menyebar melalui tanah yang tercemar, air, atau bahan tanam yang terinfeksi. Ia dapat memasuki rizom melalui luka atau bukaan semulajadi, Jadi ia akan memulakan proses pereputan.</p><p><strong>- Pengurusan: </strong>Strategi pengurusan yang berkesan termasuk meningkatkan saliran tanah untuk mencegah takungan air, menggunakan bahan tanam bebas penyakit, dan melakukan aktiviti pengiliran tanaman dengan tanaman berlainan. Rawatan fungisida juga boleh digunakan secara preventif atau kurasif untuk mengawal penyebaran penyakit.</p><p>Menguruskan busuk rizom pada tanaman halia adalah penting untuk menjaga kesihatan tanaman dan memaksimumkan hasil, terutamanya di kawasan yang tahan terhadap keadaan air bertakung atau kelembapan tinggi di mana penyakit ini berkembang.</p>","en":"<p>Rhizome rot of ginger, caused by various pathogens such as <em>Pythium</em> species, can be described as follows:<br><strong>- Symptoms:</strong> Early signs of rhizome rot usually include softening and discolouration of the ginger rhizome. Affected rhizomes may look water-soaked and mushy, and may give off a bad smell as the disease develops. Infected rhizomes may also have lesions or black spots.</p><p><strong>- Pathogens: </strong>Rhizome rot is caused by several pathogens, and <em>Pythium</em> species are among the main causes. These pathogens thrive in waterlogged soil or where drainage is poor, especially in hot and humid conditions.</p><p><strong>- Impact: </strong>The disease affects the storage organ (rhizome) of the ginger plant, reducing its quality and market value. Severe infection can cause major yield losses because infected rhizomes are not fit for eating or replanting.</p><p><strong>- Spread:</strong> The pathogens that cause rhizome rot can spread through contaminated soil, water or infected planting material. They enter the rhizome through wounds or natural openings and start the rotting process.</p><p><strong>- Management: </strong>Effective management includes improving soil drainage to prevent waterlogging, using disease-free planting material, and rotating with different crops. Fungicide treatment can also be used to prevent or cure the disease and control its spread.</p><p>Managing rhizome rot in ginger is important to keep the crop healthy and get the highest yield, especially in areas prone to waterlogging or high humidity where this disease thrives.</p>","zh":"<p>姜的根茎腐病由多种病原体引起，例如 <em>Pythium</em>（腐霉菌）属的多个种，说明如下：<br><strong>- 症状：</strong>根茎腐病的早期症状通常是姜根茎变软和变色。受害的根茎可能呈水渍状、软烂，随着病情发展会发出腐臭味。受感染的根茎也可能出现病斑或黑色斑点。</p><p><strong>- 病原：</strong>根茎腐病由几种病原体引起，其中 <em>Pythium</em> 属的种类是主要病因之一。这些病原体在积水或排水不良的土壤中生长旺盛，尤其是在炎热潮湿的条件下。</p><p><strong>- 影响：</strong>此病危害姜的贮藏器官（根茎），降低其品质和市场价值。严重感染会造成重大减产，因为受感染的根茎既不能食用，也不能再用作种植材料。</p><p><strong>- 传播：</strong>引起根茎腐病的病原体可通过受污染的土壤、水或带病的种植材料传播。它们从伤口或自然孔口侵入根茎，从而开始腐烂过程。</p><p><strong>- 管理：</strong>有效的管理措施包括改善土壤排水以防积水、使用无病种植材料，以及与其他作物轮作。也可使用杀菌剂进行预防或治疗，以控制病害蔓延。</p><p>管理好姜的根茎腐病，对保持作物健康和获得最高产量非常重要，尤其是在容易积水或湿度高、利于此病发展的地区。</p>"},"symptoms":[{"part":"LEAF","img":"Rhizome_Rot.jpg","text":{"ms":"<ul><li><p><strong>Kuning dan Layu</strong>: Daun halia mungkin mulai kekuningan dan kemudian layu. Ini disebabkan oleh gangguan pada rizom yang mengakibatkan ketidakmampuan tanaman untuk menyerap nutrien dan air secara efektif.</p></li><li><p><strong>Pertumbuhan Terbantut</strong>: Tanaman yang terinfeksi biasanya menunjukkan pertumbuhan yang terbantut karena kekurangan nutrisi yang disebabkan oleh gangguan pada rizom.</p></li><li><p><strong>Daun Kecil dan Kurang Sihat</strong>: Daun pada tanaman yang terkena biasanya lebih kecil dari biasanya dan kurang sehat. Mereka mungkin tampak kerdil atau tidak berkembang dengan baik.</p></li><li><p><strong>Penurunan hasil</strong>: Pertumbuhan dan tumbesaran tanaman merosot disebabkan gangguan rizom yang menjejaskan ketersediaan nutrisi</p></li></ul>","en":"<ul><li><p><strong>Yellowing and Wilting</strong>: Ginger leaves may start to turn yellow and then wilt. This is because damage to the rhizome stops the plant from taking up nutrients and water properly.</p></li><li><p><strong>Stunted Growth</strong>: Infected plants usually show stunted growth because of the nutrient shortage caused by damage to the rhizome.</p></li><li><p><strong>Small, Unhealthy Leaves</strong>: Leaves on affected plants are usually smaller than normal and less healthy. They may look dwarfed or not develop properly.</p></li><li><p><strong>Lower Yield</strong>: Plant growth and development decline because damage to the rhizome reduces the supply of nutrients.</p></li></ul>","zh":"<ul><li><p><strong>发黄和萎蔫</strong>：姜叶可能开始发黄，随后萎蔫。这是因为根茎受损，使植株无法有效吸收养分和水分。</p></li><li><p><strong>生长受阻</strong>：由于根茎受损导致养分不足，受感染的植株通常生长受阻。</p></li><li><p><strong>叶片细小、不健康</strong>：受害植株的叶片通常比正常的小，也较不健康，可能显得矮小或发育不良。</p></li><li><p><strong>产量下降</strong>：根茎受损影响养分供应，使植株的生长和发育衰退。</p></li></ul>"},"steps":[]},{"part":"ROOT","img":"Rhizome_Rot_3dlnM46.jpg","text":{"ms":"<ul><li><p><strong>Lembut dan Pembusukan</strong>: Akar yang terinfeksi menjadi lembut dan lembik. Ia akan bertakung air dan mudah patah apabila disentuh.</p></li><li><p><strong>Perubahan Warna</strong>: Akar mungkin menunjukkan perubahan warna, sering kali menjadi gelap atau menunjukkan warna yang tidak normal disebabkan oleh jangkitan kulat atau bakteria.</p></li><li><p><strong>Akar Menjadi ringan</strong>: Akar yang terinfeksi akan menyebabkan kemerosotan jisim pada akar begitu juga dengan rupa luarannya, mengakibatkan kesukaran tanaman untuk mencengkam dan menyerap nutrien dari tanah.</p></li><li><p><strong>Bau Busuk</strong>: Pada tahap teruk jangkitan, akar boleh mengeluarkan bau busuk, menandakan reput dan penguraian yang teruk.</p></li><li><p><strong>Kesan Terhadap Kesihatan Tanaman</strong>: Seiring dengan perkembangan penyakit, kemampuan akar untuk membekalkan air dan nutrien kepada tanaman lain berkurang, menyebabkan penurunan keseluruhan tanaman, layu, dan boleh menyebabkan kematian jika tidak dirawat dengan sewajarnya.</p></li></ul>","en":"<ul><li><p><strong>Softening and Rotting</strong>: Infected roots become soft and mushy. They become water-soaked and break easily when touched.</p></li><li><p><strong>Discolouration</strong>: The roots may change colour, often turning dark or showing abnormal colours because of fungal or bacterial infection.</p></li><li><p><strong>Lighter Roots</strong>: Infection reduces the mass and changes the outer appearance of the roots, making it hard for the plant to anchor itself and take up nutrients from the soil.</p></li><li><p><strong>Bad Smell</strong>: In severe infection, the roots may give off a bad smell, a sign of serious rotting and decay.</p></li><li><p><strong>Effect on Plant Health</strong>: As the disease develops, the roots are less able to supply water and nutrients to the rest of the plant, causing overall decline and wilting, and the plant may die if not treated properly.</p></li></ul>","zh":"<ul><li><p><strong>变软和腐烂</strong>：受感染的根变软、软烂，呈水渍状，一碰就容易断。</p></li><li><p><strong>变色</strong>：由于真菌或细菌感染，根部可能变色，往往变暗或呈现不正常的颜色。</p></li><li><p><strong>根变轻</strong>：感染使根的重量减少，外观也改变，导致植株难以固定在土中并从土壤吸收养分。</p></li><li><p><strong>腐臭味</strong>：感染严重时，根部会发出腐臭味，表示已严重腐烂分解。</p></li><li><p><strong>对植株健康的影响</strong>：随着病情发展，根部向植株其他部分供应水分和养分的能力下降，导致整株衰弱、萎蔫，如不及时妥善处理，植株可能死亡。</p></li></ul>"},"steps":[]}],"sci":"<em>Pythium</em> spp.","kind":"oomycete","ai":[]},{"id":173,"crops":["PINEAPPLE"],"name":{"ms":"Koya Merah Jambu","en":"Pink Pineapple Mealybug","zh":"黄梨灰粉蚧"},"desc":{"ms":"<p>Koya merah jambu (<em>Dysmicoccus brevipes</em>) salah satu perosak utama tanaman nanas. Perosak ini menghisap cecair daripada daun, batang, akar dan buah, menyebabkan pokok menjadi lemah serta pertumbuhannya terbantut. Koya juga menghasilkan madu (honeydew) yang menggalakkan pertumbuhan kulapuk jelaga, sekali gus mengurangkan kadar fotosintesis. Selain itu, koya merah jambu merupakan pembawa Virus Layu Koya Nenas (Pineapple Mealybug Wilt-Associated Virus, PMWaV) yang boleh menyebabkan penyakit layu pada tanaman nanas.</p><p><strong>Pengurusan perosak Bersepadu (IPM)</strong></p><ul><li>Amalan pertanian baik.</li><li>Gunakan bahan tanaman yang bebas daripada serangan koya.</li><li>Lakukan pemeriksaan secara berkala, terutama pada pangkal daun, akar dan buah.</li><li>Musnahkan pokok atau bahagian tanaman yang diserang dengan teruk.</li><li>Bersihkan kawasan kebun dan kawal rumpai yang boleh menjadi perumah alternatif.</li><li>Pelihara dan galakkan musuh semula jadi seperti kumbang kura-kura (<em>Cryptolaemus montrouzieri</em>), kumbang ladybird, lacewing dan tebuan parasitoid yang menyerang koya.</li><li>Kurangkan penggunaan racun serangga secara berlebihan bagi memelihara populasi musuh semula jadi</li></ul><p>Kawalan Kimia (Jika Perlu)</p><ul><li>Menggunakan bahan kimia mengikut syor dalam label, contoh malathion dan dimethoate.</li><li>Semburan hendaklah ditumpukan pada bahagian yang menjadi tempat persembunyian koya seperti celah daun, pangkal daun dan pangkal buah.</li><li>Apabila menggunakan racun perosak, sentiasa pakai pakaian pelindung dan patuhi arahan pada label produk, termasuk kadar dos yang disyorkan, masa aplikasi yang sesuai, serta tempoh pra-tuai sebelum hasil dituai.</li></ul>","en":"<p>The pink mealybug (<em>Dysmicoccus brevipes</em>) is one of the main pests of pineapple. It sucks sap from the leaves, stems, roots and fruit, making the plant weak and stunted. Mealybugs also produce honeydew, which encourages sooty mould to grow and so reduces photosynthesis. In addition, the pink mealybug carries Pineapple Mealybug Wilt-Associated Virus (PMWaV), which can cause wilt disease in pineapple.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Good agricultural practices.</li><li>Use planting material that is free from mealybugs.</li><li>Inspect plants regularly, especially the leaf bases, roots and fruit.</li><li>Destroy badly infested plants or plant parts.</li><li>Keep the farm clean and control weeds that can act as alternative hosts.</li><li>Protect and encourage natural enemies such as the mealybug destroyer (<em>Cryptolaemus montrouzieri</em>), ladybird beetles, lacewings and parasitoid wasps that attack mealybugs.</li><li>Avoid overusing insecticides, to protect natural enemy populations</li></ul><p>Chemical Control (If Needed)</p><ul><li>Use chemicals as recommended on the label, for example malathion and dimethoate.</li><li>Focus the spray on places where mealybugs hide, such as between the leaves, the leaf bases and the base of the fruit.</li><li>When using pesticides, always wear protective clothing and follow the instructions on the product label, including the recommended dose, the right time to apply, and the pre-harvest interval before harvesting.</li></ul>","zh":"<p>黄梨灰粉蚧（<em>Dysmicoccus brevipes</em>）是黄梨的主要害虫之一。它吸食叶、茎、根和果实的汁液，使植株衰弱、生长受阻。粉蚧还会分泌蜜露，诱发煤烟病（煤污霉）生长，从而降低光合作用。此外，黄梨灰粉蚧是黄梨粉蚧萎蔫相关病毒（Pineapple Mealybug Wilt-Associated Virus, PMWaV）的传播媒介，可引起黄梨萎蔫病。</p><p><strong>综合虫害管理（IPM）</strong></p><ul><li>良好农业规范。</li><li>使用没有粉蚧危害的种植材料。</li><li>定期检查，尤其是叶基、根部和果实。</li><li>销毁受害严重的植株或植株部位。</li><li>保持园地清洁，控制可能成为替代寄主的杂草。</li><li>保护并利用天敌，例如孟氏隐唇瓢虫（<em>Cryptolaemus montrouzieri</em>）、瓢虫、草蛉和寄生蜂，它们会攻击粉蚧。</li><li>避免过量使用杀虫剂，以保护天敌种群</li></ul><p>化学防治（如有需要）</p><ul><li>按照标签建议使用化学农药，例如马拉硫磷 malathion 和乐果 dimethoate。</li><li>喷药应集中在粉蚧藏身的部位，例如叶片缝隙、叶基和果实基部。</li><li>使用农药时，务必穿戴防护服，并遵守产品标签上的说明，包括建议剂量、合适的施药时间，以及采收前的安全间隔期。</li></ul>"},"symptoms":[{"part":"FR","img":"Koya_nanas_Doa_sabah.jpg","text":{"ms":"<ul><li>Terdapat kehadiran koya di pangkal buah disertai kulapuk jelaga dan kehadiran semut</li></ul>","en":"<ul><li>Mealybugs are present at the base of the fruit, together with sooty mould and ants</li></ul>","zh":"<ul><li>果实基部有粉蚧，并伴有煤烟病（煤污霉）和蚂蚁</li></ul>"},"steps":[]},{"part":"PEST","img":"Koya_Merah_Jambu_Doa_Sabah.jpg","text":{"ms":"Koya Merah Jambu","en":"Pink Mealybug","zh":"黄梨灰粉蚧"},"steps":[]},{"part":"LEAF","img":"Simptom_Virus_Koya_Doa_Sabah.jpg","text":{"ms":"<ul><li>Koya juga boleh menjadi vektor kepada Penyakit Layu Koya Nanas (Pineapple Mealybug Wilt) yang menyebabkan daun kemerahan, melengkung ke bawah dan akhirnya layu.</li></ul>","en":"<ul><li>Mealybugs can also spread Pineapple Mealybug Wilt disease, which makes the leaves turn reddish, curl downwards and finally wilt.</li></ul>","zh":"<ul><li>粉蚧还可传播黄梨粉蚧萎蔫病（Pineapple Mealybug Wilt），使叶片变红、向下卷曲，最后萎蔫。</li></ul>"},"steps":[]}],"sci":"<em>Dysmicoccus brevipes</em>","kind":"insect","ai":["Dimethoate","Malathion"]},{"id":182,"crops":["GINGER"],"name":{"ms":"Hawar Daun Halia","en":"Ginger Leaf Blight","zh":"姜叶枯病"},"desc":{"ms":"<p>Penyakit hawar daun pada tanaman halia yang disebabkan khususnya oleh <em>Phyllosticta zingiberi</em> </p><p><strong>Penerangan:</strong></p><ul><li><p><strong>Gejala</strong>: Hawar daun oleh <em>Phyllosticta zingiberi</em> biasanya muncul sebagai bintik bulat tidak teratur pada daun halia. Bintik ini pada awalnya kelihatan berair dan kemudian bertukar warna menjadi coklat gelap atau hitam dengan busur kuning di sekelilingnya. Seiring dengan perkembangan penyakit, bintik-bintik ini bergabung dan boleh meliputi kawasan besar permukaan daun.</p></li><li><p><strong>Patogen</strong>: <em>Phyllosticta zingiberi</em> adalah sejenis kulat patogen yang menyerang khususnya daun halia, menyebabkan lesi khas yang menjejaskan kesihatan dan kekuatan tanaman.</p></li><li><p><strong>Penyebaran</strong>: Kulat ini tersebar melalui percikan air dan angin, serta melalui alat tanam yang tercemar dan serpihan tumbuhan. Ia bertumbuhsubur di dalam keadaan panas dan lembap yang lazim di kawasan penanaman halia.</p></li><li><p><strong>Kesan</strong>: Daun yang diserang mengalami kemerosotan fotosintesis, menyebabkan kuning, layu, dan gugur awal daun. Infeksi yang teruk mengurangkan hasil tanaman.</p></li><li><p><strong>Pengurusan</strong>: Langkah-langkah kawalan termasuk menanam benih atau tanaman yang bebas penyakit, mempraktikkan penggiliran tanaman, menjaga kebersihan taman dengan membuang sisa tumbuhan yang diserang dan menggunakan fungisida jika perlu untuk mencegah penyebaran penyakit.</p></li></ul><p>Mengurus <em>Phyllosticta zingiberi</em> dengan berkesan adalah penting untuk meminimumkan kesan negatifnya terhadap tanaman halia, memastikan pertumbuhan yang sihat, dan meningkatkan produktiviti tanaman.</p>","en":"<p>Leaf blight disease of ginger, caused specifically by <em>Phyllosticta zingiberi</em>.</p><p><strong>Description:</strong></p><ul><li><p><strong>Symptoms</strong>: Leaf blight caused by <em>Phyllosticta zingiberi</em> usually appears as round to irregular spots on ginger leaves. The spots first look water-soaked and later turn dark brown or black with a yellow halo around them. As the disease develops, the spots merge and can cover large areas of the leaf surface.</p></li><li><p><strong>Pathogen</strong>: <em>Phyllosticta zingiberi</em> is a fungal pathogen that attacks mainly ginger leaves, causing typical lesions that affect the health and vigour of the plant.</p></li><li><p><strong>Spread</strong>: The fungus spreads through water splash and wind, as well as through contaminated tools and plant debris. It thrives in the hot, humid conditions common in ginger-growing areas.</p></li><li><p><strong>Impact</strong>: Infected leaves lose photosynthetic ability, causing yellowing, wilting and early leaf drop. Severe infection reduces crop yield.</p></li><li><p><strong>Management</strong>: Control measures include planting disease-free seed or plants, practising crop rotation, keeping the field clean by removing infected plant debris, and using fungicides if necessary to prevent the disease from spreading.</p></li></ul><p>Managing <em>Phyllosticta zingiberi</em> effectively is important to minimise its harmful effects on ginger, ensure healthy growth and increase crop productivity.</p>","zh":"<p>姜叶枯病，由 <em>Phyllosticta zingiberi</em>（姜叶点霉）引起的姜叶部病害。</p><p><strong>说明：</strong></p><ul><li><p><strong>症状</strong>：由 <em>Phyllosticta zingiberi</em> 引起的叶枯病，通常在姜叶上出现圆形至不规则形的斑点。斑点起初呈水渍状，之后变成深褐色或黑色，周围有黄色晕圈。随着病害发展，斑点相互合并，可覆盖叶面的大片区域。</p></li><li><p><strong>病原菌</strong>：<em>Phyllosticta zingiberi</em> 是一种真菌病原菌，主要侵染姜叶，造成典型病斑，影响植株的健康和长势。</p></li><li><p><strong>传播</strong>：这种真菌通过雨水飞溅和风传播，也会通过受污染的农具和植物残体传播。它在姜种植区常见的高温潮湿条件下繁殖旺盛。</p></li><li><p><strong>影响</strong>：受害叶片的光合作用能力下降，导致叶片变黄、萎蔫和提早脱落。严重感染会降低作物产量。</p></li><li><p><strong>管理</strong>：防治措施包括种植无病种姜或种苗、实行轮作、清除受感染的植物残体以保持田园清洁，以及在必要时使用杀菌剂防止病害扩散。</p></li></ul><p>有效管理 <em>Phyllosticta zingiberi</em> 对于减少其对姜作物的不良影响、确保健康生长和提高作物生产力非常重要。</p>"},"symptoms":[{"part":"ROOT","img":null,"text":{"ms":"<ul><li><p><strong>Pembusukan Akar</strong>: Akar yang dijangkiti mungkin mengalami pembusukan, menjadi lembut, lembik, dan berubah warna. Akar yang dijangkitiberubah menjadi coklat atau hitam.</p></li><li><p><strong>Ringan Akar</strong>: Jisim akar secara keseluruhan mungkin berkurang karena akar yang dijangkiti membusuk, mengakibatkan sistem akar yang lemah yang tidak dapat mendukung tanaman dengan baik.</p></li><li><p><strong>Luka pada Akar</strong>: Sama dengan gejala pada daun, bintik kecil gelap atau lesi dapat muncul pada akar. Bercak ini dapat berkembang dan menyebabkan akar semakin rusak.</p></li><li><p><strong>Gangguan Penyerapan Air dan Nutrien</strong>: Pembusukan dan kerosakan akar mengganggu kemampuan tanaman untuk menyerap air dan nutrien dengan efektif, mengakibatkan pertumbuhan yang terbantut dan kesihatan tanaman yang buruk.</p></li><li><strong>Jangkitan Sekunder : </strong>Akar yang lemah boleh menjadi lebih terdedah kepada jangkitan sekunder oleh patogen bawaan tanah yang lain, menambahkan masalah dan menekankan lagi tumbuhan </li></ul>","en":"<ul><li><p><strong>Root Rot</strong>: Infected roots may rot, becoming soft, mushy and discoloured. Infected roots turn brown or black.</p></li><li><p><strong>Reduced Root Mass</strong>: The overall root mass may decrease as infected roots rot, leaving a weak root system that cannot support the plant properly.</p></li><li><p><strong>Lesions on Roots</strong>: As with the leaf symptoms, small dark spots or lesions can appear on the roots. These spots can enlarge and cause further root damage.</p></li><li><p><strong>Poor Water and Nutrient Uptake</strong>: Root rot and damage reduce the plant's ability to absorb water and nutrients effectively, causing stunted growth and poor plant health.</p></li><li><strong>Secondary Infection: </strong>Weakened roots can become more open to secondary infection by other soil-borne pathogens, adding to the problem and putting more stress on the plant.</li></ul>","zh":"<ul><li><p><strong>根腐</strong>：受感染的根可能腐烂，变软、变烂并变色。受感染的根会变成褐色或黑色。</p></li><li><p><strong>根量减少</strong>：随着受感染的根腐烂，整体根量可能减少，形成无法好好支撑植株的衰弱根系。</p></li><li><p><strong>根部病斑</strong>：与叶片症状类似，根上可能出现深色小斑点或病斑。这些斑点会扩大，使根部受损更严重。</p></li><li><p><strong>水分和养分吸收受阻</strong>：根部腐烂和受损会削弱植株有效吸收水分和养分的能力，导致生长受阻、植株健康不良。</p></li><li><strong>二次感染：</strong>衰弱的根更容易受到其他土传病原菌的二次感染，使问题加重，植株承受更大压力。</li></ul>"},"steps":[]},{"part":"LEAF","img":"Leaf_Spot_2.jpg","text":{"ms":"<ul><li><p><strong>Bintik Awal</strong>: Bintik kecil, bulat, dan kelihatan berair muncul pada daun. Bintik ini boleh berwarna coklat muda hingga coklat gelap.</p></li><li><p><strong>Busur Kuning</strong>: Bintik-bintik sering dikelilingi oleh busur kuning, yang dapat terlihat jelas dan membantu membezakan infeksi <em>Phyllosticta</em> dari penyakit bintik daun lainnya.</p></li><li><p><strong>Penggabungan Bintik</strong>: Beberapa bintik dapat bergabung membentuk area nekrotik yang lebih besar, yang dapat meliputi sebagian besar permukaan daun.</p></li><li><p><strong>Kuning dan Nekrosis Daun</strong>: Daun yang dijangkiti mungkin mulai kekuningan, terutama di sekitar luka, dan akhirnya berubah menjadi nekrotik dan mati jika jangkitan teruk.</p></li><li><p><strong>Gugur Daun Pramatang</strong>: Daun yang dijangkiti mungkin gugur lebih awal, mengurangikeluasan permukaan daun untuk fotosintesis dan mempengaruhi pertumbuhan dan hasil tanaman.</p></li></ul>","en":"<ul><li><p><strong>Early Spots</strong>: Small, round, water-soaked spots appear on the leaves. These spots can be light brown to dark brown.</p></li><li><p><strong>Yellow Halo</strong>: The spots are often surrounded by a yellow halo, which can be clearly seen and helps to tell <em>Phyllosticta</em> infection apart from other leaf spot diseases.</p></li><li><p><strong>Merging Spots</strong>: Several spots can merge to form larger necrotic areas, which can cover most of the leaf surface.</p></li><li><p><strong>Leaf Yellowing and Necrosis</strong>: Infected leaves may start to turn yellow, especially around the lesions, and eventually become necrotic and die if the infection is severe.</p></li><li><p><strong>Early Leaf Drop</strong>: Infected leaves may fall early, reducing the leaf area for photosynthesis and affecting plant growth and yield.</p></li></ul>","zh":"<ul><li><p><strong>初期斑点</strong>：叶片上出现细小、圆形、水渍状的斑点。这些斑点可呈浅褐色至深褐色。</p></li><li><p><strong>黄色晕圈</strong>：斑点周围常有明显的黄色晕圈，有助于将 <em>Phyllosticta</em> 感染与其他叶斑病区分开来。</p></li><li><p><strong>斑点合并</strong>：数个斑点可合并成较大的坏死区域，可覆盖叶面的大部分。</p></li><li><p><strong>叶片变黄和坏死</strong>：受感染的叶片可能开始变黄，尤其是病斑周围，若感染严重，最终会坏死枯死。</p></li><li><p><strong>提早落叶</strong>：受感染的叶片可能提早脱落，减少进行光合作用的叶面积，影响植株生长和产量。</p></li></ul>"},"steps":[]}],"sci":"<em>Phyllosticta zingiberi</em>","kind":"fungus","ai":[]},{"id":183,"crops":["BUAH"],"name":{"ms":"Bintik Cercospora","en":"Cercospora Spot","zh":"牛油果尾孢斑点病"},"desc":{"ms":"<ul><li>Gejala jangkitan adalah tompok berbentuk bulat dengan bahagian tengah berwarna kelabu cerah dan tepi berwarna perang kemerahan.</li><li>Tompok tersebut pada awalnya kecil dan akan membesar secara perlahan-lahan.</li><li>Di bahagian tepi daun, terdapat tompok yang warnanya lebih tua (selalunya berwarna kecoklatan) berbanding bahagian tengah yang berwarna perang.</li></ul>","en":"<ul><li>The infection appears as round spots with a light grey centre and a reddish-brown edge.</li><li>The spots are small at first and slowly grow larger.</li><li>Along the leaf edge, there are spots that are darker in colour (usually brownish) than the brown centre.</li></ul>","zh":"<ul><li>感染症状为圆形斑点，中央呈浅灰色，边缘呈红褐色。</li><li>斑点起初很小，然后慢慢扩大。</li><li>叶缘处有颜色较深（通常为深褐色）的斑点，比中央的褐色部分更深。</li></ul>"},"symptoms":[{"part":"LEAF","img":"image_11.jpg","text":{"ms":"<ul><li>Simptom jangkitan seperti bintik melingkar dengan pusat kelabu cerah dan tepi coklat kemerahan.</li><li>Bintik awal berukuran kecil akhirnya membesar dengan perlahan.</li><li>Pada bahagian tepi daun, terdapat bintik berwarna lebih tua (berwarna kecoklatan) dari berwarna coklat di bahagian tengahnya.</li></ul>","en":"<ul><li>The infection appears as round spots with a light grey centre and a reddish-brown edge.</li><li>The spots are small at first and slowly grow larger.</li><li>Along the leaf edge, there are spots that are darker in colour (brownish) than the brown centre.</li></ul>","zh":"<ul><li>感染症状为圆形斑点，中央呈浅灰色，边缘呈红褐色。</li><li>斑点起初很小，然后慢慢扩大。</li><li>叶缘处有颜色较深（深褐色）的斑点，比中央的褐色部分更深。</li></ul>"},"steps":[]},{"part":"FR","img":"image_12.jpg","text":{"ms":"<ul><li>Jangkitan muncul pada buah sebagai bintik-bintik kecil, bersudut, coklat gelap yang bergabung membentuk tompok yang tidak teratur.</li><li>Tompok-tompok ini mempunyai lingkaran kuning. Luka-luka buah selalunya menjadi titik masuk organisma reput lain, seperti kulat antraknos.</li></ul>","en":"<ul><li>The infection appears on fruits as small, angular, dark brown spots that join together to form irregular patches.</li><li>These patches have a yellow ring around them. Fruit wounds often become entry points for other rot organisms, such as the anthracnose fungus.</li></ul>","zh":"<ul><li>果实受感染时出现细小、有棱角的深褐色斑点，这些斑点会连成不规则的斑块。</li><li>这些斑块周围有黄色晕圈。果实上的伤口常成为其他腐烂病菌（例如炭疽病菌）的入侵点。</li></ul>"},"steps":[]}],"sci":"<em>Cercospora purpurea</em> Cooke","kind":"fungus","ai":[]},{"id":283,"crops":["COCONUT"],"name":{"ms":"Penyakit Batang Berdarah","en":"Stem Bleeding","zh":"椰子茎干流胶病（茎出血病）"},"desc":{"ms":"<ul><li>Tanda serangan ialah cecair merah tua meleleh keluar dari batang pokok</li><li>Serangan biasanya pada pokok yang lemah</li></ul><p><strong>Pengurusan penyakit: </strong></p><ul><li>Bersihkan tisu yang diserang. Musnahkan bahagian pokok yang diserang</li><li>Penggunaan Racun Kawalan &ndash; rawat dengan perekat campuran Bordeaux</li></ul>","en":"<ul><li>The sign of attack is dark red liquid oozing out of the trunk</li><li>Attacks usually occur on weak trees</li></ul><p><strong>Disease management: </strong></p><ul><li>Clean off the infected tissue. Destroy the infected parts of the tree</li><li>Chemical control &ndash; treat with Bordeaux mixture paste mixed with a sticker</li></ul>","zh":"<ul><li>发病迹象是树干流出深红色的液体</li><li>通常危害生长衰弱的树</li></ul><p><strong>病害管理：</strong></p><ul><li>清除受感染的组织，并销毁树上受害的部分</li><li>化学防治 &ndash; 用加入粘着剂的波尔多液 Bordeaux mixture 糊剂涂抹处理</li></ul>"},"symptoms":[{"part":"STEM","img":"Source__Stephanie_Sokol_Nov_9_2023_6.jpg","text":{"ms":"<ul><li> Tanda serangan ialah cecair merah tua meleleh keluar dari batang pokok</li><li> Serangan biasanya pada pokok yang lemah</li></ul>","en":"<ul><li>The sign of attack is dark red liquid oozing out of the trunk</li><li>Attacks usually occur on weak trees</li></ul>","zh":"<ul><li>发病迹象是树干流出深红色的液体</li><li>通常危害生长衰弱的树</li></ul>"},"steps":[]}],"sci":"<em>Thielaviopsis paradoxa</em>","kind":"fungus","ai":["Bordeaux mixture"]},{"id":286,"crops":["JACKFRUIT"],"name":{"ms":"Nematod Puru Akar","en":"Root-Knot Nematode","zh":"根结线虫"},"desc":{"ms":"<ul><li>Kehilangan hasil tanaman sehingga 100%.</li><li> Merosakkan pelbagai tanaman tahunan dan saka seperti tomato, sayuran, tanaman hiasan, dan rumput.</li><li> Sangat berbahaya di kawasan tropika dan subtropika.</li></ul>","en":"<ul><li>Crop yield losses of up to 100%.</li><li>Damages many annual and perennial crops such as tomatoes, vegetables, ornamental plants and grasses.</li><li>Very harmful in tropical and subtropical areas.</li></ul>","zh":"<ul><li>可造成高达100%的产量损失。</li><li>危害多种一年生和多年生作物，如番茄、蔬菜、观赏植物和草类。</li><li>在热带和亚热带地区危害极大。</li></ul>"},"symptoms":[{"part":"ROOT","img":"Source__Stephanie_Sokol_Nov_9_2023_1.jpg","text":{"ms":"<ul><li>Pertumbuhan pokok diserang terencat (decline), Pokok kelihatan layu dan batang pokok merekah</li><li>Mengehadkan penghasilan buah dan memendekkan hayat pokok</li><li> Kelihatan &lsquo;gall&rsquo; pada akar diserang</li></ul><p>Kitaran Hidup:</p><ul><li>Juvenil menetas dari telur dan bergerak melalui tanah untuk menyerang akar.</li><li>Juvenil berkembang menjadi betina yang bertelur ratusan biji pada permukaan akar.</li><li>Telur menetas dalam tanah yang hangat dan lembap untuk meneruskan kitaran hidup.</li></ul><p>Pengurusan nematode</p><p>Fumigasi tanah sebelum menanam dengan methyl bromide</p>","en":"<ul><li>Growth of attacked trees declines; the tree looks wilted and the trunk cracks.</li><li>Limits fruit production and shortens the life of the tree.</li><li>'Galls' (swellings) can be seen on attacked roots.</li></ul><p>Life Cycle:</p><ul><li>Juveniles hatch from eggs and move through the soil to attack the roots.</li><li>Juveniles develop into females that lay hundreds of eggs on the root surface.</li><li>The eggs hatch in warm, moist soil and the life cycle continues.</li></ul><p>Nematode management</p><p>Fumigate the soil with methyl bromide before planting.</p>","zh":"<ul><li>受害树木生长衰退，植株萎蔫，树干开裂。</li><li>限制果实产量，缩短树的寿命。</li><li>受害根部可见“根结”（瘤状肿大）。</li></ul><p>生活史：</p><ul><li>幼虫从卵中孵化，在土壤中移动并侵入根部。</li><li>幼虫发育为雌虫，在根表面产下数百粒卵。</li><li>卵在温暖潮湿的土壤中孵化，继续其生活史。</li></ul><p>线虫管理</p><p>种植前用溴甲烷 Methyl bromide 熏蒸土壤。</p>"},"steps":[]}],"sci":"<em>Meloidogyne</em> sp.","kind":"nematode","ai":[]},{"id":288,"crops":["JACKFRUIT"],"name":{"ms":"Karat Buah","en":"Fruit Rust","zh":"菠萝蜜果锈病"},"desc":{"ms":"Karat Buah ialah penyakit <strong>berpunca daripada bakteria</strong> yang menyebabkan tompok-tompok berwarna karat pada permukaan buah. Penyakit ini biasanya berlaku apabila buah mengalami kecederaan atau terdedah kepada keadaan persekitaran yang tidak sesuai.","en":"Fruit Rust is a disease <strong>caused by bacteria</strong> that produces rust-coloured patches on the fruit surface. The disease usually occurs when the fruit is injured or exposed to unsuitable environmental conditions.","zh":"果锈病是一种<strong>由细菌引起</strong>的病害，会在果实表面形成锈色斑块。此病通常在果实受伤或处于不适宜的环境条件时发生。"},"symptoms":[{"part":"FR","img":"Source__Stephanie_Sokol_Nov_9_2023_3.jpg","text":{"ms":"<p><strong>Simptom :</strong></p><ul><li><p>Tompok bulat berwarna karat pada kulit buah</p></li><li><p>Tompok boleh bercantum dan menjadi kasar atau merekah</p></li><li><p>Buah mungkin berubah bentuk</p></li><li><p>Tiada kerosakan dalaman yang ketara kecuali berlaku jangkitan sekunder</p></li></ul><p><strong>Pengurusan Penyakit:</strong></p><ul><li><p>Musnahkan buah yang dijangkiti</p></li><li><p>Elakkan kecederaan pada buah semasa pengendalian</p></li><li><p>Amalkan kebersihan ladang dan pangkasan untuk pengudaraan baik</p></li><li><p>Semburan bakterisid berasaskan kuprum sebagai langkah pencegahan</p></li></ul>","en":"<p><strong>Symptoms:</strong></p><ul><li><p>Round, rust-coloured spots on the fruit skin</p></li><li><p>Spots may join together and become rough or cracked</p></li><li><p>The fruit may become misshapen</p></li><li><p>No obvious internal damage unless secondary infection occurs</p></li></ul><p><strong>Disease Management:</strong></p><ul><li><p>Destroy infected fruits</p></li><li><p>Avoid injuring the fruits during handling</p></li><li><p>Practise farm sanitation and pruning for good air flow</p></li><li><p>Spray a copper-based bactericide as a preventive measure</p></li></ul>","zh":"<p><strong>症状：</strong></p><ul><li><p>果皮上出现圆形锈色斑点</p></li><li><p>斑点可能连成一片，变得粗糙或开裂</p></li><li><p>果实可能变形</p></li><li><p>除非发生二次感染，否则果实内部没有明显损害</p></li></ul><p><strong>病害管理：</strong></p><ul><li><p>销毁受感染的果实</p></li><li><p>处理果实时避免造成损伤</p></li><li><p>保持园地清洁并进行修剪，以利通风</p></li><li><p>喷施铜基杀细菌剂作为预防措施</p></li></ul>"},"steps":[]}],"sci":"<em>Pantoea stewartii</em>","kind":"bacteria","ai":["Copper"]},{"id":290,"crops":["COCONUT"],"name":{"ms":"Nematod Pengorek","en":"Burrowing Nematode","zh":"穿孔线虫"},"desc":{"ms":"<ul><li><p>Daun menjadi kekuningan.</p></li><li><p>Terdapat kecederaan berwarna oren pada akar yang akhirnya menyebabkan akar reput.</p></li><li><p>Pertumbuhan pokok terbantut.</p></li><li><p>Hasil tanaman berkurangan.</p></li><li><p>Daun tidak matang akan gugur.</p></li></ul><p><strong>Pengurusan Penyakit:</strong></p><ul><li><p>Elakkan penanaman pisang di kawasan yang dijangkiti.</p></li><li><p>Buang akar di luar sabut anak benih sebelum dipindahkan ke ladang.</p></li><li><p>Tanam tanaman kekacang <em>Crotalaria juncea</em> di antara barisan tanaman.</p></li><li><p>Gunakan racun kawalan &mdash; taburkan carbosulfan sebelum penanaman.</p></li></ul>","en":"<ul><li><p>Leaves turn yellowish.</p></li><li><p>Orange lesions appear on the roots, eventually causing root rot.</p></li><li><p>Plant growth is stunted.</p></li><li><p>Yield is reduced.</p></li><li><p>Immature leaves drop.</p></li></ul><p><strong>Disease Management:</strong></p><ul><li><p>Avoid planting bananas in infested areas.</p></li><li><p>Remove the roots outside the husk of the seedling before transplanting to the field.</p></li><li><p>Plant the legume <em>Crotalaria juncea</em> between the crop rows.</p></li><li><p>Use chemical control &mdash; broadcast carbosulfan before planting.</p></li></ul>","zh":"<ul><li><p>叶片变黄。</p></li><li><p>根部出现橙色伤斑，最终导致根腐烂。</p></li><li><p>植株生长受阻。</p></li><li><p>产量减少。</p></li><li><p>未成熟的叶片脱落。</p></li></ul><p><strong>病害管理：</strong></p><ul><li><p>避免在受感染的地区种植香蕉。</p></li><li><p>幼苗移植到田间之前，剪除椰壳（椰棕）外的根。</p></li><li><p>在作物行间种植豆科植物 <em>Crotalaria juncea</em>（菽麻）。</p></li><li><p>使用药剂防治 &mdash; 种植前撒施丁硫克百威 carbosulfan。</p></li></ul>"},"symptoms":[{"part":"ROOT","img":"Source__Stephanie_Sokol_Nov_9_2023_8.jpg","text":{"ms":"<p>Gejala:<br>&bull; Daun menjadi kekuningan.<br>&bull; Kecederaan berwarna oren pada akar sehingga menyebabkan akar reput.<br>&bull; Pertumbuhan pokok terbantut.<br>&bull; Hasil pengeluaran berkurangan.<br>&bull; Daun tidak matang akan gugur.</p><p>Pengurusan penyakit (dalam bentuk point):<br>&bull; Elakkan penanaman pisang di kawasan tersebut.<br>&bull; Buang akar di luar sabut anak pokok sebelum dipindahkan ke ladang.<br>&bull; Tanam tanaman kekacang <strong>Crotalaria juncea</strong> di antara barisan tanaman.<br>&bull; Gunakan racun kawalan &ndash; Taburkan <strong>carbosulfan</strong> sebelum penanaman.</p>","en":"<p>Symptoms:<br>&bull; Leaves turn yellowish.<br>&bull; Orange lesions on the roots, leading to root rot.<br>&bull; Plant growth is stunted.<br>&bull; Yield is reduced.<br>&bull; Immature leaves drop.</p><p>Disease management:<br>&bull; Avoid planting bananas in the area.<br>&bull; Remove the roots outside the husk of the seedling before transplanting to the field.<br>&bull; Plant the legume <strong>Crotalaria juncea</strong> between the crop rows.<br>&bull; Use chemical control &ndash; broadcast <strong>carbosulfan</strong> before planting.</p>","zh":"<p>症状：<br>&bull; 叶片变黄。<br>&bull; 根部出现橙色伤斑，导致根腐烂。<br>&bull; 植株生长受阻。<br>&bull; 产量减少。<br>&bull; 未成熟的叶片脱落。</p><p>病害管理：<br>&bull; 避免在该地区种植香蕉。<br>&bull; 幼苗移植到田间之前，剪除椰壳（椰棕）外的根。<br>&bull; 在作物行间种植豆科植物 <strong>Crotalaria juncea</strong>（菽麻）。<br>&bull; 使用药剂防治 &ndash; 种植前撒施丁硫克百威 <strong>carbosulfan</strong>。</p>"},"steps":[]}],"sci":"<em>Radopholus</em> sp.","kind":"nematode","ai":["Carbosulfan"]},{"id":309,"crops":["PINEAPPLE"],"name":{"ms":"Tupai Buah","en":"Fruit Squirrel","zh":"丽松鼠（果园松鼠）"},"desc":{"ms":"<p>Tupai buah ialah mamalia kecil daripada kumpulan rodensia yang memakan pelbagai jenis buah-buahan, biji benih, bunga dan pucuk muda. Di kawasan kebun, tupai dianggap sebagai perosak kerana ia mengorek dan memakan buah yang sedang berkembang serta buah yang hampir ranum, menyebabkan penurunan kualiti dan kuantiti.Tupai akan menggigit dan memakan isi buah, menyebabkan kesan gigitan, lubang, serta kerosakan pada permukaan buah. Buah yang rosak juga lebih mudah dijangkiti oleh kulat dan bakteria, sekali gus meningkatkan kerugian hasil.</p><p><br><strong>Pengurusan Perosak Bersepadu (IPM) </strong><br>&bull; Tuai buah dengan segera apabila mencapai tahap kematangan bagi mengurangkan sumber makanan. <br>&bull; Buang buah yang rosak dari kawasan kebun. <br>&bull; Pasang jaring pelindung pada pokok nanas.<br>&bull; Lakukan pemeriksaan berkala untuk mengesan kerosakan akibat pemakanan, kesan gigitan dan kehadiran tupai. <br>&bull; Galakkan kehadiran musuh semula jadi seperti burung pemangsa (contohnya burung hantu dan helang) jika bersesuaian. <br>&bull; Gunakan penghalau visual atau bunyi .</p><p><br>Kawalan Kimia<br>&bull; Tidak disyorkan. Pengurusan tupai lebih berkesan melalui kaedah pencegahan, pengecualian (exclusion), sanitasi kebun dan penggunaan perangkap yang mematuhi peraturan tempatan.</p>","en":"<p>Fruit squirrels are small mammals of the rodent group that eat many kinds of fruit, seeds, flowers and young shoots. On farms, squirrels are considered pests because they gnaw into and eat developing and nearly ripe fruit, reducing quality and quantity. Squirrels bite and eat the fruit flesh, leaving bite marks, holes and damage on the fruit surface. Damaged fruit is also more easily infected by fungi and bacteria, which further increases yield loss.</p><p><br><strong>Integrated Pest Management (IPM) </strong><br>&bull; Harvest fruit promptly when it is mature to reduce the food source. <br>&bull; Remove damaged fruit from the farm. <br>&bull; Install protective netting on the pineapple plants.<br>&bull; Inspect regularly for feeding damage, bite marks and the presence of squirrels. <br>&bull; Encourage natural enemies such as birds of prey (for example owls and eagles) where suitable. <br>&bull; Use visual or sound repellents.</p><p><br>Chemical Control<br>&bull; Not recommended. Squirrels are managed more effectively through prevention, exclusion, farm sanitation and the use of traps that comply with local regulations.</p>","zh":"<p>果园松鼠是啮齿类的小型哺乳动物，吃各种水果、种子、花朵和嫩芽。在果园里，松鼠被视为害虫，因为它们会啃咬并吃掉正在发育和接近成熟的果实，使果实品质和数量下降。松鼠啃咬并吃掉果肉，在果实表面留下咬痕、孔洞和损伤。受损的果实也更容易受到真菌和细菌感染，进一步增加产量损失。</p><p><br><strong>综合虫害管理（IPM）</strong><br>&bull; 果实成熟时及时采收，以减少松鼠的食物来源。<br>&bull; 将受损果实清出园地。<br>&bull; 在黄梨植株上安装防护网。<br>&bull; 定期检查是否有取食损伤、咬痕和松鼠出没。<br>&bull; 在适合的情况下，保护和吸引天敌，例如猛禽（如猫头鹰和老鹰）。<br>&bull; 使用视觉或声音驱赶装置。</p><p><br>化学防治<br>&bull; 不建议使用。通过预防、隔离阻挡、保持园地清洁，以及使用符合当地法规的捕捉器来管理松鼠更为有效。</p>"},"symptoms":[{"part":"FR","img":"Serangan_Tupai_pada_nanas_DOA_Sabah.jpg","text":{"ms":"<ul><li>Terdapat kesan gigitan yang tidak sekata pada permukaan buah nanas.</li><li>Isi buah dimakan atau dikorek, menyebabkan bahagian buah berlubang.</li><li>Kehadiran luka terbuka pada buah akibat aktiviti pemakanan tupai.</li></ul>","en":"<ul><li>Irregular bite marks on the surface of the pineapple fruit.</li><li>The fruit flesh is eaten or gouged out, leaving holes in the fruit.</li><li>Open wounds on the fruit caused by squirrel feeding.</li></ul>","zh":"<ul><li>黄梨果实表面有不规则的咬痕。</li><li>果肉被吃掉或挖空，使果实出现孔洞。</li><li>松鼠取食造成果实上有开放性伤口。</li></ul>"},"steps":[]}],"sci":"<em>Callosciurus</em> spp.","kind":"mammal","ai":[]},{"id":310,"crops":["COCONUT"],"name":{"ms":"Kumbang Badak","en":"Coconut Rhinoceros Beetle","zh":"椰子犀角金龟"},"desc":{"ms":"<p>Kumbang badak dewasa menyerang bahagian umbut dan pucuk muda pokok kelapa dengan mengorek dan memakan tisu lembut di bahagian tengah (spear leaf). Serangan menyebabkan daun muda menjadi berlubang, rosak dan boleh mengakibatkan pertumbuhan pokok terbantut atau mati jika serangan teruk.</p><p><strong>Pengurusan Perosak Bersepadu (IPM)</strong></p><ul><li>Musnahkan tempat pembiakan seperti batang kelapa reput, tunggul dan sisa organik di kawasan ladang.</li><li>Gunakan perangkap feromon untuk memantau serta mengurangkan populasi kumbang dewasa.</li><li>Pasang jaring serangga di sempadan ladang bagi menghalang kemasukan perosak ke kawasan tanaman.</li><li>Gunakan bunjut ubat gegat sebagai bahan penghalau kerana baunya dapat menghalau CRB.</li><li>Kulat entomopatogen <em>Metarhizium anisopliae</em> untuk mengawal populasi perosak.</li></ul><p><strong>Kawalan Kimia (Jika Perlu)</strong></p><ul><li>Semburan atau aplikasi racun serangga seperti methamidophos </li><li>Apabila menggunakan racun perosak, patuhi arahan label termasuk kadar dos, masa aplikasi dan langkah keselamatan.</li></ul></p>","en":"<p>Adult rhinoceros beetles attack the growing point (heart) and young shoots of coconut palms by boring into and feeding on the soft tissue in the centre (spear leaf). The attack causes young leaves to become holed and damaged, and can stunt the palm's growth or kill it if the attack is severe.</p><p><strong>Integrated Pest Management (IPM)</strong></p><ul><li>Destroy breeding sites such as rotting coconut trunks, stumps and organic waste in the farm area.</li><li>Use pheromone traps to monitor and reduce the number of adult beetles.</li><li>Install insect netting along the farm boundary to stop the pest from entering the crop area.</li><li>Use mothball (naphthalene) sachets as a repellent, because the smell drives away CRB.</li><li>Use the insect-killing fungus <em>Metarhizium anisopliae</em> to control the pest population.</li></ul><p><strong>Chemical Control (If Necessary)</strong></p><ul><li>Spray or apply insecticides such as methamidophos </li><li>When using pesticides, follow the label instructions, including the dose rate, application timing and safety measures.</li></ul>","zh":"<p>椰子犀角金龟成虫钻蛀并取食椰子树中心（未展开的心叶）的嫩组织，从而侵害椰子树的生长点（椰心）和嫩梢。侵害会使嫩叶出现孔洞和损伤，严重时会导致椰子树生长受阻甚至死亡。</p><p><strong>综合虫害管理 (IPM)</strong></p><ul><li>清除繁殖场所，例如园内腐烂的椰子树干、树桩和有机废料。</li><li>使用信息素诱捕器监测并减少成虫数量。</li><li>在园地边界安装防虫网，阻止害虫进入种植区。</li><li>使用樟脑丸（萘）小袋作为驱避剂，因为其气味可驱赶犀角金龟（CRB）。</li><li>使用昆虫病原真菌 <em>Metarhizium anisopliae</em>（绿僵菌）控制害虫数量。</li></ul><p><strong>化学防治（如有需要）</strong></p><ul><li>喷洒或施用杀虫剂，例如 methamidophos（甲胺磷） </li><li>使用农药时，请遵守标签说明，包括剂量、施药时间和安全措施。</li></ul>"},"symptoms":[{"part":"PEST","img":"CRB_Kumbang_badak.jpg","text":{"ms":"<ul><li>CRB dewasa</li></ul>","en":"<ul><li>Adult CRB</li></ul>","zh":"<ul><li>犀角金龟（CRB）成虫</li></ul>"},"steps":[]},{"part":"STEM","img":"CRB_umbut_batang.jpg","text":{"ms":"<ul><li>CRB mengorek dan memakan umbut kelapa</li></ul>","en":"<ul><li>CRB bores into and feeds on the coconut heart (growing point)</li></ul>","zh":"<ul><li>犀角金龟钻蛀并取食椰心（生长点）</li></ul>"},"steps":[]},{"part":"F","img":"CRB_pelepah_simptom_yzPKzVe.jpg","text":{"ms":"<ul><li>Terdapat lubang dan terowong pada pelepah akibat aktiviti pengorek oleh kumbang dewasa.</li><li>Terdapat fiber lembab pada pangkal pelepah menunjukan serangan baru</li></ul>","en":"<ul><li>Holes and tunnels in the fronds caused by the boring of adult beetles.</li><li>Moist fibres at the base of the fronds show a new attack</li></ul>","zh":"<ul><li>叶柄上有成虫钻蛀造成的孔洞和隧道。</li><li>叶柄基部出现潮湿的纤维，表示有新的侵害</li></ul>"},"steps":[]},{"part":"LEAF","img":"CRB_Simptom_daun.jpg","text":{"ms":"<ul><li>Daun muda yang baru terbuka menunjukkan potongan berbentuk &quot;V&quot; atau segi tiga.</li><li>Daun muda kelihatan koyak, tercarik atau tidak sempurna apabila berkembang.</li></ul>","en":"<ul><li>Newly opened young leaves show &quot;V&quot;-shaped or triangular cuts.</li><li>Young leaves look torn, shredded or misshapen as they open.</li></ul>","zh":"<ul><li>新展开的嫩叶出现&quot;V&quot;形或三角形的切口。</li><li>嫩叶展开时显得破裂、撕碎或残缺不全。</li></ul>"},"steps":[]},{"part":"LC","img":"kitaran_hidup_CRB.jpg","text":{"ms":"Kitaran hidup kumbang badak","en":"Life cycle of the rhinoceros beetle","zh":"椰子犀角金龟的生活史"},"steps":[]}],"sci":"<em>Oryctes rhinoceros</em> (Linnaeus)","kind":"insect","ai":["Metarhizium anisopliae","Methamidophos","Naphthalene"]}]};
